/* 平成23年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h23.committeeSessions.push(...[{"id":"h23-20111013-4","meetingId":"h23-c-settlement","date":"2011年10月13日","dateIso":"2011-10-13","committee":"決算特別委員会","time":"午前１０時００分～午後５時１８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を179件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２２年度品川区一般会計歳入歳出決算","agenda":"平成２２年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"成果報告書の１７２ページ、教科書採択事務についてお伺いさせていただきたいと思います。本区の教科書採択の仕組み、検討委員会での絞り込みはなかったとのことですけれども、そういったことも含めて、どういう仕組みになっているのか、また一般質問で教育長よりご答弁いただいた公平・公正とは何をもっての公平・公正で、基準は何なのかご答弁いただきたいと思います。","respondent":"冠木指導課長","answer":"この報告を学識経験者や保護者、地域の代表等からなる教科用図書調査検討委員会において、その分析や表現が適切であるかどうかを検討し、調査資料として教育委員会に提出をしていただいております。今、委員のお話のように、絞り込み等は一切ございません。","voiceIndex":6,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"その領土に関してなんですけれども、北方領土が我が国の固有の領土であることなどの「など」には、竹島や尖閣諸島が我が国の領土であることも入るのでしょうか。例えば教員からこういった質問が来た場合は、どのようにお答えになられるのでしょうか。","respondent":"冠木指導課長","answer":"教員からそういった質問が教育委員会にあった場合は、固有の領土というふうに指導するように説明をしておりますが、そういった事例はございませんので、教員はすべてそういった見解で指導しています。","voiceIndex":8,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"今の答弁の整合性から考えて、また政府の見解や歴史的経緯、何を見ても、竹島が不法占拠であって、尖閣諸島は領海侵犯が繰り返されているということを、教科書の記述はこうなっていますが、今、現場の教員が明確にこの点がはっきりと、教科書はこういう記述であったが違うということを指導していくことが大切だと思いますが、今、指導課長がご説明されたとおり、そういったことを教員に指導というか。","respondent":"冠木指導課長","answer":"何より日本の固有の領土であるということは間違いのないことです。私どもとしましては、まず小中一貫教育要領に明記をいたしまして、学校を指導していますので、そういった点につきましては、今後も日本の固有の領土だということで指導するように指導しています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"そのときのやりとりで、メールが使えないという教員がいらしたんですけれども、何かしらの理由があってのことだと思うので、その教員についてとやかく言うつもりはありませんけれども、一応確認させていただきたいんですけれども、品川区では教員１人に１台ずつパソコンを支給しているということですけれども、その利用についての講習、または使いこなせているのかということと。","respondent":"冠木指導課長","answer":"ただあまり神経質になり過ぎますと、仕事の進みぐあいにご迷惑をかけるということもありますので、その辺は適切に渉外活動ができますように指導してまいりたいと思います。","voiceIndex":12,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういったこともあると思うんですけれども、せっかくパソコンが１人１台ある以上、先生方が使えるような講習とか研修を進めていただいて、なかなか対外的にほかの会社の方とかとやりとりをするとか、学校以外の方とやりとりするときに、メールが使えないというのは今の時代ではおかしいなと思うので、その辺の改善はしていただきたいと思います。","respondent":"冠木指導課長","answer":"平成２２年度のデータでお答えいたします。８８件ということで、品川区のほうにご視察いただいております。人数は４６７名です。","voiceIndex":14,"id":"exchange-005"},{"speaker":"沢田委員","kind":"意見","question":"それは主にどういった内容で視察に、品川区は小中一貫教育をやられているということとか、そういったこともあると思いますが、どういった内容が一番視察にいらっしゃる方が多いのかというのをお聞かせください。","respondent":"冠木指導課長","answer":"一番多いのは小中一貫教育についてのご視察です。続いて市民科について、それから幼少連携という順になっております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"沢田委員","kind":"質問・要望","question":"それと次、１７２ページの文化財保護費のところでもちょっと質問させていただきたいと思います。これも第２回定例会の一般質問で行ったんですけれども、区指定の天然記念物保存樹についてということで質問させていただきました。その後どうなられているでしょうか。","respondent":"齋藤庶務課長","answer":"天然記念物の木をお持ちの方、１３人の方が保存樹と同じサービスを受けたい、７人はこのまま継続したい、３人の方は検討中ということで、以上、そのような形で対応させていただいているところです。","voiceIndex":18,"id":"exchange-007"},{"speaker":"沢田委員","kind":"質問・要望","question":"樹木を管理する上では、天然記念物とはいっても教育委員会の所管になっていますけれども、保存樹は水とみどりの課が管理する。行政の効率的な観点からもぜひ進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"鶴委員","kind":"質問","question":"私は質問順に、成果報告書１６８ページの教職員人材育成経費の同和教育指導推進委員会、１７１ページの調査研究等受託事業、１６９ページのプラン２１推進事業のマナーキッズ教室委託、１７１ページの経済活動体験学習経費、同じく１７１ページのすまいるスクールについてお尋ねいたします。初めに、同和教育指導推進委員会と調査研究等受託事業についてお尋ねいたします。","respondent":"冠木指導課長","answer":"１点目の件ですけれども、私ども子どもたちにあらゆる差別や偏見はしてはいけないものだということで、当然学校でも指導しておりますし、あるいはご家庭でもそういった指導をしていただけるようにお願いをしていますけれども、子どもたちの世界というのは。","voiceIndex":22,"id":"exchange-009"},{"speaker":"鶴委員","kind":"質問・要望","question":"先日も私、総務費の質問で紹介させていただきました。このようなことも取り入れていただき、より一層の人権教育、人権尊重の態度育成に取り組んでいただきたいと思います。次に、マナーキッズ教室委託についてお尋ねいたします。マナーキッズ教室の内容と対象年齢、それとこの教室がいつから行われているのかについてお尋ねしたいと思います。短期の委託事業なのか、簡単で結構ですので、教えてください。","respondent":"冠木指導課長","answer":"始まったのは平成２０年からでございまして、今、幼稚園なども入りまして、順次学校数は増えているところでございまして、今、約３０校ほど取り組んでいるところです。","voiceIndex":24,"id":"exchange-010"},{"speaker":"鶴委員","kind":"質問","question":"今、お聞きした限りであっても、スポーツを通じてそうしたマナーを教えていく、非常に大事なことかなと思います。テニスを通じてというところを本当に率直にうれしく思いましたけれども、テニス以外のほかのスポーツにも展開していく予定はありますでしょうか。今後検討しながらとありましたけれども、教えてください。","respondent":"冠木指導課長","answer":"例えばサッカーなどの取り組みの中でも、リスペクトといいますか、選手同士がきちっとあいさつをして握手をするというような取り組みが行われておりますので、応用の範囲は広いかなと思ってあります。先ほどの検討の中でそういったところは議論になっております。","voiceIndex":28,"id":"exchange-011"},{"speaker":"鶴委員","kind":"質問・要望","question":"ほかのスポーツへの展開も含めて、より一層の充実をご検討いただきたいと思います。次に、経済活動体験学習経費についてお尋ねいたします。平成２１年の成果報告書の同費目のブランチには、スチューデント・シティとファイナンス・パークがそれぞれ記載されていて、平成２２年度に記載がないのは、八潮学園から品川学園への移設に伴う一時的な閉鎖で実施しなかったということでしょうか。","respondent":"冠木指導課長","answer":"これは委員のお話のように、この平成２２年度はスチューデント・シティとファイナンス・パークが引越しということで、八潮学園のほうから、今現在は品川学園のほうに来ておりますけれども、その関係で実施しておりません。","voiceIndex":30,"id":"exchange-012"},{"speaker":"鶴委員","kind":"確認","question":"私が確認する中では、平成１８年から導入されているかと思います。５年経過しましたが、この言われるところの進路選択や将来設計について、何か具体的な事例や報告はありますでしょうか。","respondent":"冠木指導課長","answer":"さらに品川区の納税者として育っていってくれるように、応援してまいりたいと考えています。","voiceIndex":32,"id":"exchange-013"},{"speaker":"鶴委員","kind":"質問","question":"そのものの目的は少しずつ見えてきているのかなと。そこでお尋ねします。日本では江東区豊洲と兵庫県西宮市にある子ども向けの体験型テーマパーク、キッザニアがありますが、ここはご存じのとおり、約８０の職種が体験できる施設です。当然規模の問題になりますけれども、将来的に体験できる職種を拡大する、そうした可能性はありますでしょうか。","respondent":"冠木指導課長","answer":"それで社会全体がつながって、自分たちの経済活動に生きてくるんだなと、生かされているんだなというような考え方から、お願いする企業の設定にしましても、そういった私どもの基本的な制度設計の中で業種を選んだりというところでご賛同いただいているですので。","voiceIndex":34,"id":"exchange-014"},{"speaker":"鶴委員","kind":"確認","question":"すまいるスクールについてお尋ねいたします。１０月９日に放送された日本テレビの朝の情報番組、「シューイチ」ですまいるスクールが紹介されたのを拝見しました。そこでお尋ねしますが、すまいるスクールの参加児童のうち、要配慮児、特別支援児の登録数と登録率、参加数と参加率を、それぞれ確認の意味で教えてください。","respondent":"齋藤庶務課長","answer":"区内には特別支援学校から来られているお子さんが７名いらっしゃいます。区内の小学校に８つの特別支援学校がありまして、９０人の方がすまいるスクールに登録されております。普通教室に通われていらっしゃいますが、介護等を必要とされている方が１８０名おります。","voiceIndex":36,"id":"exchange-015"},{"speaker":"鶴委員","kind":"質問","question":"平成２３年度の小学生全体の登録率が９,１１７人で７１％、参加率は今、３５.数％とご答弁いただきました。そこでお尋ねいたしますが、要配慮児、特別支援児の放課後対策として、すまいるスクールとしてどの程度の障害をお持ちの方を受け入れることができるのか、教えてください。","respondent":"齋藤庶務課長","answer":"登録にあたって、区の職員が必ず特別支援学校や特別支援学級に行って、支援のコーディネーター、養護教諭の方とお話し合いをして、すまいるスクールでの指導が対応できるかということを確認してお受けしているです。","voiceIndex":38,"id":"exchange-016"},{"speaker":"鶴委員","kind":"質問","question":"ちょっと専門的な部分になるかもしれませんけれども、医学的措置の詳細というか、わかる範囲で教えてください。","respondent":"齋藤庶務課長","answer":"具体的に申しますと、注射をするだとか、あとは一定の処置、家族ならできる処置、他人はできない処置、いろいろな病気によって程度が違いますので、それは個々のお子さんの状況を確認しながら、医学的な視点で相談、アドバイスをいただいて対応しています。","voiceIndex":40,"id":"exchange-017"},{"speaker":"鶴委員","kind":"質問・要望","question":"さまざま全体的なことも含めて今、見直しをされていると思いますけれども、またその中で受益者負担をどうするのかという議論もあるようですけれども、障害の程度にかかわらず利用ができる、そうしたすまいるスクールの体制を整備していただきたいと思いますが、ご所見を伺います。","respondent":"齋藤庶務課長","answer":"すまいるスクールはあくまで学校の現場で対応しているということがあります。物理的に特定の医療行為を伴うものにつきましては、なかなか学校施設では難しいということでございまして、可能な限り引き続き受け入れをしていきたいと考えています。","voiceIndex":42,"id":"exchange-018"},{"speaker":"鶴委員","kind":"意見","question":"逆に健常者の方も、今度はそうしたどりいみんぐが運営していただいているようなところにも足を運んで、そうしたことにもサポートしていくとか、そういったことも幅広く含めて、主の目的を外さない中で、そうした障害のある方もすまいるスクールに積極的に参加ができるような体制の検討を、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-019"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、１７４ページ、学校環境整備事業、１６９ページ、小中一貫教育推進経費、１６８ページの区教員経費についてお伺いさせていただきたいと思います。１７４ページ、学校環境整備事業で、関連しまして、校庭芝生化についてご質問させていただきたいと思います。それとまたそのグラウンドごとでどのくらいの年で更新をしていき、幾らぐらいの費用がかかるのか、わかれば教えていただきたいと思います。","respondent":"齋藤庶務課長","answer":"天然芝ですけれども、これは毎年、現時点で２５０万円ほどかけて養生しておりますので、養生を繰り返していくということです。土の場合は、１,３００万円から１,５００万円かけて、おおむね１５年を更新時期と見て、計画的に対応しています。","voiceIndex":46,"id":"exchange-020"},{"speaker":"大倉委員","kind":"質問・要望","question":"そして天然芝の身体的効果というかメリット、教育的な効果、そういった部分も教えていただければと思います。第一日野小学校や第三日野小学校、先ほどだと鮫浜小学校でしたっけ。限られた学校で天然、人工芝のグラウンドになっているということなんですが、なぜそこになったのか教えていただきたいと思います。","respondent":"齋藤庶務課長","answer":"第三日野小学校は地盤が池田山公園、ずっと下にあって水はけが悪いので、人工芝にすることで稼働率を高めたいということで考えております。","voiceIndex":48,"id":"exchange-021"},{"speaker":"大倉委員","kind":"質問・要望","question":"校庭に芝生と人工芝で今、学校の校庭で放射能測定とかをされておりますが、人工芝と土、天然芝で違いがあったら教えていただきたいと思います。校庭の放射能測定の結果と概要等を教えていただきたいのと、また仮にそうしたグラウンドが除染が必要になった場合は、どういった方法があるのかなというところと、区としてどのような対応をとっていくのかというお考えがあれば、教えていただきたいと思います。","respondent":"齋藤庶務課長","answer":"したがって、土壌について区のほうで入れかえる、あるいはかえなければいけないという事情はありませんけれども、放射線が高かった場合の対応につきましては、文部科学省から通知がございまして、土壌については２つ、表層の５cmを削って。","voiceIndex":50,"id":"exchange-022"},{"speaker":"大倉委員","kind":"質問・要望","question":"それと関連してなんですけれども、１７９ページの校庭芝生管理用備品購入等というのがあるんですが、これは６００万円ぐらいかかっていると思うんですが、これは何校でそのぐらいかかっているのかというか、１校だったら、これは毎年かかるものなのか、ちょっとそこだけ教えていただければと思います。","respondent":"和氣学務課長","answer":"これは芝刈機等を基本的に今後養生していただくために、今、ボランティアにやっていただいておりますが、そのための備品等でございまして、１回限りのものです。","voiceIndex":52,"id":"exchange-023"},{"speaker":"大倉委員","kind":"質問・要望","question":"続いて１６９ページ、小中一貫校教育推進経費に関連いたしまして、初日、款をまたいで入ってしまったんですが、武道必修についてお伺いをしたいと思うんですが、武道の授業の内容、今、どういった授業が行われているかを教えていただきたいのと、その目的というか、教育面としての武道の目的と、今までやってきた子どもに関する成果、子どもたちにどういった変化があったとかというのがもしわかれば。","respondent":"冠木指導課長","answer":"武道についてお答えいたします。内容ですが、小学校におきましては、柔道に取り組んでいる学校が２５校、剣道が１１校、相撲が２校です。中学校においては、柔道が１４校、剣道が２校、その柔道、剣道両方ともやれるという状況を整えている学校が１校です。","voiceIndex":54,"id":"exchange-024"},{"speaker":"大倉委員","kind":"質問・要望","question":"あいさつがちゃんとできるようにするという、どちらかというと技術的な部分というよりも、そうした礼節だったり精神的な部分なのかなという中で、なぜ今、柔道と剣道と相撲がありますが、その武道になったのかちょっと疑問に思いましたので、そこをお答えいただきたいのと、また指導者確保も基本的には教員ということなんですが、小学校だとそれでいいのかもしれないかなと思ったんですが。","respondent":"冠木指導課長","answer":"そんなところをバリエーションをいろいろと仕組みながら、この授業は進めていきたいと思ってありますけれども、当然地域の協力者であるとか、今、委員がお話しのスポーツ団体ともご協力をいただきながら進めてまいりたいと思ってあります。","voiceIndex":56,"id":"exchange-025"},{"speaker":"大倉委員","kind":"質問・要望","question":"中学校に関してもさまざま競技、小学校から続けていく中で、上手になったら、例えば部活に入ろうとか、地域の剣道教室だったり、柔道教室だったりに行こうという中で、そうしたところでぜひこれからも力を入れて取り組んでいただきたいなと思ってはいるんですが、例えば小学校に関しては、心の成長ということで取り入れているということですが、例えばそれが何で５年生なのか、例えば小３とか。","respondent":"冠木指導課長","answer":"国のほうの学習指導要領ですと、武道については中学生からということになっておりまして、そこを品川区としては小中一貫教育要領ということで５年生から取り組んでいるところでございまして、そういった中で、文部科学省とのいろいろな話し合いの中でも、指導する中身と。","voiceIndex":58,"id":"exchange-026"},{"speaker":"大倉委員","kind":"質問・要望","question":"これで武道のほうは終わりたいと思います。最後に、１６８ページ、区教員経費で、品川区で独自採用している区の教員のことについてお伺いさせていただきたいと思います。例えば採用後、働く現場が都と区の職員が同じで働くわけですから、そうした中で「ちょっとおまえ、何だ」という、そういった部分があったりするのかなと。そこで区の採用の待遇の違いがあるのかないのか教えていただきたいと思います。","respondent":"冠木指導課長","answer":"当然学校の中での仕事を一緒にやるわけですから、委員のようなお話は一切ございませんし、それでは仕事が回っていかないわけですので、学校の中で一致団結して子どもたちの教育にあたっているです。","voiceIndex":60,"id":"exchange-027"},{"speaker":"大倉委員","kind":"質問・要望","question":"私立の大学とかの面接対策とかもかなり行われていて、そうした中で、例えば実習に結構行っている人のほうが不利になったり、面接の練習をなかなか時間がとれなくてできないとかという方がいる中で、品川区としては、区の教員採用に関してどういった基準があるのか教えていただきたいと思います。","respondent":"冠木指導課長","answer":"そういったところで、人間性も豊かで力も持っている教員を採用してまいりたいと思ってあります。","voiceIndex":62,"id":"exchange-028"},{"speaker":"大倉委員","kind":"質問・要望","question":"そうした熱意がある方を採用しているということで、安心をしておりますが、ちょっとこれは款が変わってしまうかもしれないんですが、ちょっと仕事が増えている中ですが、国でも３０人学級というのを目指していると思うんですが、品川区としてもそうした教員の採用を増やして、３０人学級というのができるように目指していくのかなというところがあれば、ぜひお聞かせいただきたいのと、例えば人が増えると。","respondent":"和氣学務課長","answer":"この導入は３０人学級を目指してやっているものではございませんので、全く別物です。品川区の教育を充実させるために、品川区に意欲を持って働く教員を採用しているところで、５年をもって終了と考えています。","voiceIndex":64,"id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問","question":"私は、成果報告書１７５ページ、学校運営費、通学路の安全監視に関連してと、もう一つ同じ１７５ページで教育振興費、就学援助について伺いたいと思います。都市環境事業部長はそういう答弁でしたけれども、私どもは子どもたちが集まるところは安全を確保しなければいけない、調査が必要だと思うんですけれども、教育委員会は都市環境事業部長と同じような考え方なのか、伺いたいと思います。","respondent":"齋藤庶務課長","answer":"教育委員会といたしましても、環境課を中心した区長部局と連携しながら、対応については検討しているところで、考え方は同じです。","voiceIndex":67,"id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問・要望","question":"世田谷区と大田区であったら、大体品川区もあるのではないかというのが普通の感覚だと思うんですね。これは私は普通の対応だと思うんですけれども、区と同じ対応だということですと、ホットスポット探しというのが風評被害を広げるからやらないというお答えでしたけれども、なぜホットスポットを探すことが風評被害を広げることになるのか。教育委員会の立場でわかりやすく説明いただきたいと思います。","respondent":"齋藤庶務課長","answer":"都合、土壌検査も１００カ所近くで行っておりまして、品川区の地図、２２km2をプロットで、メッシュで落としましても、ホットスポットを探す必要があるという値は出ていない。したがいまして、私どもとしては、教育委員会といたしましても区長部局と同様の考えです。","voiceIndex":69,"id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問","question":"そこを調査して、雨水で流れてきて、水が蒸発したら凝縮されていたということでしたけれども、今の、例えば校庭ですと、大体真ん中あたりを調査するとか、そういうことが中心ですけれども、それで安全だと言っているのが、私はどうも理解できないんですけれども、例えばそういう雨水がたまりそうなところをなぜ調査しないのか、そこのところを伺いたいと思います。この違いは何なのか。","respondent":"岩田都市環境事業部長","answer":"先ほど庶務課長がお答えしましたように、基本的には２カ所の定点観測がベースになるわけですけれども、区はそれ以外に土壌およびプールの水の測定を全施設において行っているわけです。その結果が今月いっぱいで一巡しますので、全施設の測定が終了します。","voiceIndex":71,"id":"exchange-032"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、各所管のところで必要だというところは調査していくということだと。そうすると、区の教育委員会がどういう対応をするのか、どういう考え方なのかということを改めて伺いたいと思います。","respondent":"齋藤庶務課長","answer":"今の都市環境事業部長の答弁と全く同趣旨でございまして、先般の校長会でも、今度新しい機械が２台入る。必要に応じて、区が庶務課ではかる、場合によっては学校ではかるということで対応するということにしておりますので、区長部局、教育委員会とも見解は全く同じです。","voiceIndex":73,"id":"exchange-033"},{"speaker":"宮崎委員","kind":"質問","question":"必要なところを調査するということで、ぜひお願いしたい。こっちのほうでも出て、これとダブっていないだろうと思うんですけれども、そうすると、就学援助の基準以下の方というか、これはこの人数よりも生活保護を受けている方もプラスになるということだと思うんですけれども、それもあわせて伺いたいと思います。","respondent":"和氣学務課長","answer":"認定数は日々変わりますので、ここに書かれている数字が実数と考えていただくしかありません。転出入があります。認定が取り消しになる場合もあれば、途中から認定になる場合もありますので、これは実数というふうにお考えいただきたいと思います。平均的な数といえます。","voiceIndex":75,"id":"exchange-034"},{"speaker":"宮崎委員","kind":"質問","question":"一方、先生方のところでは、例えば給食費がなかなか集まらないとかという声も聞くんですけれども、そうすると、かなり就学援助を受けている方というか、またそれのボーダーというか、あるいは対象になっているけれども、あえて申請していないとか、そういう方もいらっしゃるんじゃないかと思うんですけれども、そこら辺の認識がどうなのかということを伺いたいと思います。","respondent":"和氣学務課長","answer":"ですから、私どもはボーダーの人で滞納になっている人がいて、就学援助を受けられるという方については、その場で課税の申告の指導までして就学援助を受けていただいて、給食費の未納を防いですので、結果未納率が０.０８％という大変低い数値に抑えられているです。","voiceIndex":77,"id":"exchange-035"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、この子どもたちの教育に関しての負担を増やしていかないという対応は、今年の予算特別委員会のときも、私ももっと無償化等を広げる必要があるのではないかという要望をしました。具体的にどういうふうになっているのか伺いたいと思います。それと小中一貫の標準服も援助をやっていきますけれども、あわせてほかの援助の拡大については、何かあるのかないのか伺いたいと思います。","respondent":"和氣学務課長","answer":"それから就学援助の拡大をという話ですけれども、これにつきましては、私どもは父母負担調査というのをやっておりまして、実際に幾ら各学校で払っているかというのを確認していますので、それとあわせながら、それを平均的に見ながら。","voiceIndex":79,"id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっと時間がないので、私がぜひ検討していただきたいのは、例えば特に卒業アルバム代ですと、子どもの多い、少ないで負担も変わってくる。こういうのはやっぱり不公平になってきますので、特に全員が対応する、関係するところの負担減、こうしたアンバランスのところの対応をぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-037"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は成果報告書の１７７ページの学校保健費と、１７０ページの教育指導費の市民科・各教科充実経費についてお伺いしたいと思います。成果報告書１７７ページの第４目学校保健費の児童・生徒健康管理費のうち、寄生虫卵検査についてお尋ねいたします。小学校費から６９万円が支出されておりますが、これはどのような検査なのか、具体的なご説明をお願いいたします。","respondent":"和氣学務課長","answer":"寄生虫は小学校１年生から３年生に対して実施をしてございまして、検査方法としましては、シールでやってあります。","voiceIndex":83,"id":"exchange-038"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最近、無農薬野菜だとか食の多様化によって、回虫だとか、俗にサナダムシという条虫、このような寄生虫は貧血だとか、倒れてしまうとか、栄養障害とか、激烈な症状を起こすので、こういう寄生虫というのは十分検査して駆虫することというのは非常に大切なことなんですが、先ほどお話ししたように、現在行われているぎょう虫の検査というのは、ほとんど無症状で。","respondent":"和氣学務課長","answer":"この検査につきましては、医師会ともしくは、学校医と相談をしながら今後どうしていくか決めてありますので、今のところは変更するという話もありませんし、必要ないというご意見は今のところいただいていないので。","voiceIndex":87,"id":"exchange-039"},{"speaker":"鈴木（博）委員","kind":"質問","question":"成果報告書の１７０ページのマナーキッズ教室についてお尋ねいたします。さらに具体的に言いますと、このテニスを行うことによって、あいさつとお礼を身につけさせるというお話でしたが、このマナーキッズ教室というのはテニスをするだけなんでしょうか。テニスをすることに始まってテニスをすることで終わる、要するにスポーツ教室と同じような形態の事業だと理解してもよろしいでしょうか。","respondent":"冠木指導課長","answer":"このマナーキッズの事業の流れといたしましては、当然テニスの中で相手方との握手であるかと、目と目を合わせてあいさつをする、そういう活動がありますが、その後で参加者を集めまして、講師はいろいろな方が入っておられますけれども。","voiceIndex":89,"id":"exchange-040"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"私もお子様相手に日々診療しているわけでありますが、非常に友達感覚というか、公と私事、公と私の区別をつけることができないお子様というのが非常に目につきます。そのような観点からの教育というのは、もっと充実させたほうがいいのではないかと私は考えるんですが、これに関して区のご見解、取り組みの仕方をお伺いしたいと思います。","respondent":"冠木指導課長","answer":"いろいろなご評価をいただきましたけれども、その中に意義をきちっと保護者に伝える、そういう活動もしているところでございまして、さらに充実させてまいりたいと思います。","voiceIndex":91,"id":"exchange-041"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今後ともご努力をよろしくお願いいたします。質問を終わります。","respondent":"和氣学務課長","answer":"原委員。","voiceIndex":93,"id":"exchange-042"},{"speaker":"原委員","kind":"質問・要望","question":"成果報告書の１６８ページ、教育委員会費、１７１ページのすまいるスクール、やはり成果報告書１７６ページの学校給食費、これに関連してお伺いしていきます。括弧して限界値２ベクレルと書いてあります。品川区が購入されたのは高精度とありましたけれども、これはゲルマニウムの半導体、ゲルマニウム半導体でなくてもいいんですけれども、給食の食材の数値確認ができるものかどうか、そこが１点です。","respondent":"和氣学務課長、岩田都市環境事業部長","answer":"ですから、ほかの区も実は本当に１回限りで終わりであるとか、ほとんどすべてが食べた後に検査をして、後から結果が出るですので、ご趣旨のことは、気持ちは非常によくわかりますが。最近、安い機材で数時間でできるものも出たようですけれども、やはりきちっとはかるには二、三日かかるということで、先ほどの学務課長のお答えのとおりになります。","voiceIndex":95,"id":"exchange-043"},{"speaker":"原委員","kind":"質問・要望","question":"ご丁寧なご説明ありがとうあります。ですから、これは都、国、その辺に再度強く要求をしていただきたいと思います。先ほど申し上げたように、教育委員会費とすまいるスクールについて伺います。実際に全国で今、１６０を超える箇所に広がっているという話も聞いております。それは小中一貫校だけではなくて、プラン２１、この辺まで広くなっても結構ですけれども、その辺のご見解をいただければと思います。","respondent":"冠木指導課長、齋藤庶務課長","answer":"後半の私ども品川区の教育の今までの流れと今後の展望といいますか、そういったところでの全体的なご質問と伺いましたけれども、小中一貫教育を平成１８年度から導入いたしまして展開してまいりまして、学力であるとか。したがいまして、正規職員１人、非常勤が１人、その他は民間のスタッフで対応しておりまして、常時１日当たり２３０人のスタッフですまいるスクールを運営しています。","voiceIndex":98,"id":"exchange-044"},{"speaker":"原委員","kind":"意見","question":"すまいるスクールからなんですけれども、やはり質と量、今、２３０人というお話だったんですけれども、ちょっと気になるのが臨時職員のところなんですけれども、臨時職員もそうですし、気になるのはもう一つ、先ほどの一つ目の教育委員の報酬ですね。それは何かといいますと、実際に品川区の教育に対する成果が上がっていないのであればそうではないという。この２点をお答えいただければと思います。","respondent":"齋藤庶務課長","answer":"今の最低賃金が８３７円です。２時間半、おおむね５時間来ていただいて、仕事の質の量としては見合いだと考えております。教育委員の報酬につきましては、他の行政委員とのバランス、勤務していただいている内容に応じて適切なものだと私どもは考えております。","voiceIndex":101,"id":"exchange-045"},{"speaker":"阿久津委員","kind":"質問","question":"私からは、１７２ページ、社会教育費、ＰＴＡ関係費から校庭開放についてまず伺います。続きまして１７７ページ、学校保健費、児童・生徒健康管理費について伺います。１点目の校庭開放について。ＰＴＡ関係費の２,８７２万円余のうち８６０万円余という大きな割合を占めている校庭開放ですが、どのような内容なのか教えてください。","respondent":"齋藤庶務課長","answer":"日曜日や夏休みなど、９時から５時の間、子どもたちが遊ぶ場所ということで提供させてもらっております。ただその見守り、サポートの仕事は各ＰＴＡにお願いしております。ＰＴＡに委託料としてお支払いしている金額がこの金額のほとんどになります。","voiceIndex":104,"id":"exchange-046"},{"speaker":"阿久津委員","kind":"質問","question":"もう一点、続けてお伺いするんですが、ＰＴＡの方へ報酬、協力費として支出しているものということだったんですが、これは１日当たりお幾ら支払われるのか、金額というのは学校ごとに違うものなのでしょうか。","respondent":"齋藤庶務課長","answer":"指導員の謝礼は、お一人当たり、半日は９００円、１日お願いする場合は１,８００円ということになっております。お支払いする金額は、半日を開放するか、１日中開放するか、各学校ごとに計画がありますので、計画数に応じて前払いをしているということになっております。","voiceIndex":106,"id":"exchange-047"},{"speaker":"阿久津委員","kind":"質問","question":"この校庭開放の運営にかかわることで、ちょっと細かいことでご相談を受けたものですから、本当に細かいことなんですが、ちょっと質問します。１点目なんですけれども、指導員への協力費の支払いと受け取りについてです。協力費を払ってしまえばそれは手を離れてＰＴＡ内部の話になってしまうのかもしれないんですが、このようなお悩み、教育委員会として把握をされていますでしょうか。","respondent":"齋藤庶務課長","answer":"基本的にはＰＴＡにお願いしている事業で、ＰＴＡの内部自律といいますか、ＰＴＡの中でご検討、解決していただくべきことだと考えています。ＰＴＡの皆さんとお話し合いをする場もありますので、いただいたお話を十分お伝えして、解決策を模索するように努めてまいります。","voiceIndex":108,"id":"exchange-048"},{"speaker":"阿久津委員","kind":"提案","question":"中にはこの協力費をＰＴＡ費として積み立てて使いたいと思っている方が多くいらっしゃると伺っています。そこでご提案なんですけれども、例えばＰＴＡの方が協力者として登録をする場合に、自分は協力費として受け取らないで、これを遊具等の購入に充てる、ＰＴＡ費として積み立ててほしいとい明白な意思表示があった場合に、この場合はＰＴＡ費の積み立ての流用というのは可能にならないんでしょうか。","respondent":"齋藤庶務課長","answer":"そして実績に応じて、校庭開放しない場合は返していただく、そういう財務会計の仕組みがありますので、直接ＰＴＡの会費へそのまま流用というのはちょっと難しいと思いますが、例えば受け取っていただいて、指定寄附、この学校の遊具を買ってくださいなど。","voiceIndex":110,"id":"exchange-049"},{"speaker":"阿久津委員","kind":"質問・要望","question":"続きまして１７７ページ、学校保健費、児童・生徒健康管理費、関連して脳脊髄液減少症の周知についてお伺いします。平成２１年第３回定例会で、我が会派の金野委員より、この病気について質問、要望しておりますが、改めて学校においての対応について伺います。お伺いしますが、教育委員会が把握している中で、本区には脳脊髄液減少症の児童・生徒がいるかどうか、お教えください。","respondent":"和氣学務課長","answer":"そこで私どもはそこを受けて、養護の先生を中心に、担任とも協力をしながら、授業であるとか、日常生活であるとか、それぞれの注意を払って、もしくは言動とかに注意を払って、差別が起こらないような形で対応してまいりたいと考えていますので。","voiceIndex":112,"id":"exchange-050"},{"speaker":"阿久津委員","kind":"質問","question":"私も平成１９年以来、お子様がこの病と戦っておられる患者団体の方たちと何度もお会いして、患者ご自身またそのご家族の方からお話を伺ってきた経緯があります。私が直接お話を伺った方のお話、これは品川区の方ではないんですけれども、その方の息子さんは、学校でいじめに遭って、同級生から突き飛ばされて壁に頭を打ちつけて、この病気を発症されました。病も気からですと。直近のデータで結構です。","respondent":"冠木指導課長","answer":"不登校のデータについては、３０日以上の欠席者ということを一つの基準として報告をしておりまして、平成２２年度ですと、小学校で４２名、中学校７・８・９年生で１２１名という報告をしております。","voiceIndex":114,"id":"exchange-051"},{"speaker":"阿久津委員","kind":"質問・要望","question":"その方が直接この病気かどうかというのは、安易に結びつけられるものではないと思いますけれども、そういう不登校の児童・生徒への対応として、病気の情報提供を行って、例えば医療機関への受診を勧めると、こういったきめ細やかな対応をお願いいたします。先ほど対応については今、しっかりとやられているということがありましたので、これは要望です。１６８ページ、学校ＩＴ化推進経費について。","respondent":"和氣学務課長","answer":"日々先生方がいろいろ集積したものが、そのまま例えば通知表に反映したりとか、指導要録に反映したりとか、テストの結果の集計がシステムでできたりとかということでいいますと、大変役に立つというふうになってございまして、これは実はほかの自治体がといいますか。","voiceIndex":116,"id":"exchange-052"},{"speaker":"阿久津委員","kind":"確認","question":"続いて児童・生徒たちが使用する電子黒板等のＩＣＴ化についてもまた伺います。これらはあくまでもツールであり、どう活用して指導に生かしていくのかということについて研究を重ねていると、そのようなご答弁をいただいておりますが、確認の意味で、学校の、特に子どもたちの学習で使用するこうした電子ツールの導入について、本区のご見解を教えてください。","respondent":"和氣学務課長","answer":"ツールとして使うための基本的な調べ学習の基本だとか、どうやって物事を組み立てていくかとか、そういうことを発達段階に合わせて使っていくことが、その発達段階を考えながら適宜にＩＣＴを使うということが重要だろうと私どもは考えてございまして。","voiceIndex":118,"id":"exchange-053"},{"speaker":"阿久津委員","kind":"質問","question":"練りに練られた学校ＩＣＴ化のロードマップというんでしょうか、来年度中に一定の方向を出されると今、ご答弁いただいたんですけれども、本区の言うようにわかったつもりになってしまうというのは理解できますし、本区としても、ＩＣＴ化というのを別に投げてしまったわけではなくて、真摯にこの課題に取り組まれているというのがよくわかりましたので、ビジュアルで理解しやすい。","respondent":"和氣学務課長","answer":"そういう意味で、そういうときに時を得て、子どもたちを遊ばせたり、地域の方に開放しておりますが、先日は映画会がここで開かれました。芝生の上に寝ころがって映画を見ようという、そんな形での取り組みもやっているところです。","voiceIndex":120,"id":"exchange-054"},{"speaker":"阿久津委員","kind":"質問・要望","question":"東京の中では一回芝生にしてまた戻す。手入れが大変で、通常の校庭に戻してしまったという例もあると聞いておりますが、第一日野小学校のシンボルとして、ぜひ続けていっていただきたい。できれば広げていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-055"},{"speaker":"向委員","kind":"質問","question":"私からは、成果報告書のページ数で申し上げますと、１６８ページの教職員住宅維持管理費と、１７１ページの帰国児童・生徒等適応指導費、時間があれば、教育費の一番最後、１８０ページの幼稚園の講師採用経費についてお尋ねしたいと思います。帰国児童・生徒等適応指導費とありますが、これは具体的に概要を教えていただければと思います。日本人の児童のみ対象としているのか、そのあたりをお願いします。","respondent":"冠木指導課長","answer":"この事業の対象になっているのは、日本人で海外からお帰りになった児童・生徒、それから外国籍であるんだけれども、日本の学校に通っておられる児童・生徒の中のご希望の方です。","voiceIndex":125,"id":"exchange-056"},{"speaker":"向委員","kind":"質問","question":"地域的に区内でどこの学校に偏っているというか、まんべんなく学校に１人、２人はいるものなのか、どこかの学校に１０人、２０人とか、そんなにいるとは考えにくいですが、そういう傾向があるのかもあわせて教えてください。","respondent":"和氣学務課長","answer":"それから学校別で多いところで言いますと、八潮学園が一番多くて、小学校段階で１７名、中学校段階で１１名、続きまして多いところで言いますと、日野学園が多くて、小学校段階で１４名、中学校段階で１４名、続きまして伊藤学園で、伊藤学園は中学校段階が多くて１３名。","voiceIndex":127,"id":"exchange-057"},{"speaker":"向委員","kind":"質問","question":"１番目が愛知県で、２番目が神奈川県、ちょっと少なくて３番目に東京都ということで、現状はそういった現状ということで、中国籍の方が多い、フィリピンの方が多い、韓国の方とか、しっかりと把握しながら取り組んでいかなければいけない事業だと私も認識をしております。コストの面以外とか、何か特別な理由があるのか、実績があるＮＰＯ法人なので委託されたとか、そういう経緯を簡単に教えてください。","respondent":"冠木指導課長","answer":"ＩＷＣ国際市民の会に委託をお願いし始めたのは、平成９年からです。それまでこういった子どもたちへの指導というところでの実績があった団体ということでお願いした経緯があります。ほかにはそれに匹敵するような団体は当時なかったと聞いております。","voiceIndex":129,"id":"exchange-058"},{"speaker":"向委員","kind":"質問・要望","question":"こういった帰国児童の数とか、実際、外国から来た日本国籍を持っていないほかの児童の数というのは、世界の情勢とか、過去にはおそらくバブルが崩壊した後に、海外の日本企業が閉鎖して数が減ったとかいう実情もあったように私も記憶しておりますし、本当に現場との定期的な意見交換とか、問題改善に取り組んでいっていただきたいと思うんですが、こういったミーティングとか。","respondent":"冠木指導課長","answer":"実は私も自分が区内の中学校の教員だった時分に、ミャンマーからおいでになったお子さんがいて、そのとき私もミャンマー語を幾つか教えてもらったんですけれども、やっぱり学校の先生方と日本語指導員との十分なコミュニケーションが必要なのかなと思ってあります。","voiceIndex":131,"id":"exchange-059"},{"speaker":"向委員","kind":"質問","question":"先日も別の歳出の際に、母子手帳をいろいろな言語で扱ってあるとか、そういったお話も伺っていますので、品川区にいろいろな国籍、日本人だけではなくて、いろいろなゆかりのある子どもを増やしていってほしいなと私も期待をしております。１８０ページになりますが、この幼稚園費の中の講師採用経費というのは、具体的にどういった経費なんでしょうか。教えてください。","respondent":"冠木指導課長","answer":"この幼稚園講師につきましては、例えば入学当初の子どもたちが入った４月当初、子どもたちのケアのために非常勤として採用したり、運動会の練習、あるいはプール、それから外出をするとき、それからまれにですが、幼稚園の先生が体調を崩されたときの補充という形で。","voiceIndex":133,"id":"exchange-060"},{"speaker":"向委員","kind":"質問","question":"この人数というのは大体どれくらい採用されていて、臨時ということなので、長期間というケースと短期間、数日間というケースで採用されることがあるのか、臨機応変の対応をされているとは思うんですが、そのあたりがわかれば教えてください。","respondent":"冠木指導課長","answer":"公立幼稚園は９園ございまして、それぞれが年間の指導計画を進めていく中で、その季節季節で必要になってくる人材というのを大体園長は把握しておりますので、直近の資料ではないんですが、平成２３年３月現在ということで。","voiceIndex":135,"id":"exchange-061"},{"speaker":"向委員","kind":"質問","question":"採用に関しては、何かしら試験があるとか、先生方の質の問題といったら言い過ぎかもしれないんですが、そのあたりはどのように保持されているんでしょうか。","respondent":"冠木指導課長","answer":"非常勤講師と申しましても、ほぼ教員と同じ仕事をやっていただくものですから、資格としては基本的に幼稚園の教諭の免許、あるいは保育士の免許等をお持ちになっている方で、例えば一度退職されて家庭に入っておられて、少し子育ても落ちついたのでもう一回仕事をしたいとか。","voiceIndex":137,"id":"exchange-062"},{"speaker":"向委員","kind":"質問","question":"続けて成果報告書１６８ページの教職員住宅維持管理費について少しお尋ねしたいと思います。いずれの建物も古いということでよく伺っております。ゆたか教職員住宅が昭和４８年、伊藤教職員住宅のほうが昭和６３年ということで伺っているんですが、ここ一、二年の事務事業評価を見ました。毎年決算で上がっている維持費については、どのような使い方をされているのかを簡単に教えてください。","respondent":"冠木指導課長","answer":"住宅の戸数ですけれども、ゆたか教職員住宅については、所帯用が１４戸、単身用が１２戸の２６戸です。伊藤教職員待機寮の一部分を教職員待機寮ということで使っているわけですけれども、そこは所帯用が６戸、単身用が６戸の１２戸です。","voiceIndex":139,"id":"exchange-063"},{"speaker":"渡部委員","kind":"意見","question":"成果報告書１６９ページ、プラン２１。毎回聞いています選択制のことについて１０分聞いてまいりますが、その選択制を聞くにあたりまして、今回も平成２４年度新入学時、これは小学校のほう、新入学児童用の学校案内を見させていただきました。完全に学校にお任せで、１回つくって、次にまたどういうふうにつくろうかと考えているのが、その辺だけ一つお聞かせください。","respondent":"和氣学務課長","answer":"今までは私どもである意味ではお仕着せといいますか、こういうフォーマットでやりなさいということで進めてまいったんですが、なかなか学校の伝えたいことをちゃんと伝えられない、もしくは学校がきちっと自分のことをアピールできないのではないかということで、今年。","voiceIndex":142,"id":"exchange-064"},{"speaker":"渡部委員","kind":"質問","question":"来年度、また出ましたら、来年度のこの機会にご質問します。そもそもこの通学区域というものが、この新たなもの、私も４年前から質問させていただいていますが、例えば通学区域が変わることがあったと思います。時代の流れ、子どもたちの増減等により。今の通学区域はいつから生かされているものなのか。逆にその前、２つ前変更されたのがいつぐらいなのか、わかれば教えていただけますでしょうか。","respondent":"和氣学務課長","answer":"通学区域は規則等で定めているわけではないので、一番古いものはいつ定まったかというのは、大体昭和３５年から昭和４５年の間に固まったという形でしか、申しわけございませんが、ご回答できません。","voiceIndex":144,"id":"exchange-065"},{"speaker":"渡部委員","kind":"質問","question":"この通学区域なんですけれども、伺いましたら、昭和３０年代から始まりまして、昭和６０年代にかけては途中いじりがあって、それ以来、二十数年このままということで、区内の人口動向を見てみますと、地域偏差というのが出てきています。学事制度審議会において今後の予測もされている中で、この地域は子どもが減っていくぞ、この地域は子どもが増えていくぞというような記載があった。","respondent":"和氣学務課長","answer":"特に今、子どもが増え続けているということがありまして、私ども学区域についても、見直しも含めて検討してしなければならない時期には来ているのかなと思いますが、人口動向がまだまだ定まってございませんので、慎重に考えていきたいと考えています。","voiceIndex":146,"id":"exchange-066"},{"speaker":"渡部委員","kind":"質問・要望","question":"荏原の一丁目１番、一丁目１番の１から４、その下、一丁目１番の３６から３８、これは第一日野小学校。しかもブロックが違う。指定校変更というので行けるんだというのも毎回伺っていてわかるんですけれども、選択して、あなたのブロックは選択できませよと戻って、また指定校変更するのではなくて、狭い品川区ですから、４つのブロックを僕は本当に外してもいいのではないかなと思います。前も伺いました。","respondent":"和氣学務課長","answer":"どうしても線を引きますとそういう矛盾が出てしまいます。これから人口の分布状況もありまして、学校が足りなくなってしまうというのが一番大変ですので、そこも考えながらブロック、学区域について、全般的な様子を見ながら考えさせていただきたいと考えております。","voiceIndex":148,"id":"exchange-067"},{"speaker":"渡部委員","kind":"意見","question":"地域は地域でなるべく自分たちの近所の学校に通ってもらおうと、地域は地域で逆に頑張っています。ある意味選択制が反面教師に、反面教師という言い方はおかしいんですけれども、あるがために近所の子どもたち、自分たちの近所の学校に行ってもらってと頑張っていますから、だんだん数が減ってくると僕は思っています。ぜひこの先、検討を進めてください。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":150,"id":"exchange-068"},{"speaker":"山内委員","kind":"質問・要望","question":"１６８ページの教育指導費の中から質問しますけれども、先日、台風１５号が上陸しました。その親御さんから、どういうことなんでしょうかということで私のほうに寄せられたものですから、そのあたりを教育委員会のほうに問い合わせました。これは台風が来るという予測のもと、そういった判断というものを教育委員会のほうで統一できないのかということをお尋ねさせていただきたいと思います。","respondent":"冠木指導課長","answer":"今回の台風１５号の対応について、学校の判断ということでございましたけれども、学校の判断は当然現場の校長が責任者ですので、優先されるという基本的な考え方は私どもも持ってあります。","voiceIndex":152,"id":"exchange-069"},{"speaker":"山内委員","kind":"意見","question":"現場の判断は大変重要かと思うんですけれども、それはそれでわかるんです。そうなると、やっぱりそこは保護者の方も何でというような、それが説明がちゃんとできればいいんですけれども、説明がされないと、何でうちの学校だけ休校なのかな、何でうちの学校の子だけ午前中登校なのかなという、その統一がされないというのは、私はあまりいい傾向ではないのではないか思うんだけれども、どうなんでしょうね。","respondent":"冠木指導課長","answer":"先ほどもお答えいたしましたが、各学校それぞれの立地条件といいますか、それから通ってくるお子さんの通学範囲、通学路の状況が全部違いますので、もちろん私ども教育委員会として、子どもたちの安全を第一に指示はしますが。","voiceIndex":154,"id":"exchange-070"},{"speaker":"山内委員","kind":"質問","question":"そうなりますと、現場の判断ということであれば、これはまた逆の考え方をします。ほかは教育委員会からの指示のもと、その学校が午前中だけ登校されたということであるのならば、今、課長がおっしゃる現場を第一に優先的に考えるということであれば、すべての学校の指示を学校長の指示のもとやっていくという、そういった形での統一というのはできないのですか。","respondent":"冠木指導課長","answer":"常々校長には臨機応変にその場その場できちっと判断ができるように指導していますけれども、私どもとして、現場を預かる校長ももちろんですが、教育委員会としても子どもたちの安全の確保ということは重要なことですので、一定の指示、基準といいますか。","voiceIndex":156,"id":"exchange-071"},{"speaker":"山内委員","kind":"質問","question":"学校側と教育委員会側との意見の統一というか、そういうのはどうなっているんですか。","respondent":"冠木指導課長","answer":"今回の台場地区の学校におきましても、五反田地区の学校にいたしましても、事前に私ども協議をして、一定の方向性を校長と共通理解した上で判断をしています。","voiceIndex":158,"id":"exchange-072"},{"speaker":"山内委員","kind":"質問","question":"戻ります。休校を判断した学校、それから午前中だけの登校を判断した学校、これは教育委員会としっかりと連携をしたもとで、今回、すべての判断が下されたということでよろしいのか、最後にそこだけ伺います。","respondent":"冠木指導課長","answer":"委員のおっしゃるとおりです。","voiceIndex":160,"id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"成果報告書の１６９ページ、小中一貫教育推進経費のところでお伺いします。小中一貫教育について疑問がたくさんありますので、幾つも質問しますが、答えてください。この理由と、子どもの成長発達に合ったものなのかどうか、これが１点です。中学校教育を小学５年生まで引き下げていることについて、内容を教えていただきたいのと、あと小学校段階で教科担任制や定期テストが必要な理由をお聞かせください。","respondent":"冠木指導課長","answer":"これは中学生だけではなくて、５年生、６年生の段階からそういった子どもたちに勉強の手法も含めて学ばせていくということが必要であろうというところで、定期テストを５年生、６年生で実施しています。","voiceIndex":163,"id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先日、発達心理学の複数の先生のお話を伺ってきたんですけれども、この中で強調すべきは、本来、小学校、中学校は別々の学校であり、ギャップがあり、戸惑いがあるのは当然であると。私はこの品川区が小学校と中学校を区切らないで、続けて連続をしていくということが、今、お話しした発達論から見てどうなのかなと思っているんですが、この指摘に対しての見解をお聞かせいただきたいと思います。","respondent":"冠木指導課長","answer":"そして子どもたちが中学校に入って授業を受けるときに、先生が変わることによって適応できないという状況も過去にはあったわけですから、そういうことではなくて、５年生から教科担任制をやることによって、社会に出ていけば、行ったところ。","voiceIndex":165,"id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問・要望","question":"５、６年生に中学生らしさを早期に求めるのではなく、小学生時代を小学生らしく活動を行う、このことが大切だと思っています。発達論から見て、４・３・２制、いろいろ考えはあると思いますけれども、成長発達に合っていない面もあると思います。いろいろな考えが出ているんだと思います。そういった意味では多くの人の意見を聞きながら、立ち止まって見直していく必要があると思いますが、いかがでしょうか。","respondent":"冠木指導課長","answer":"品川区では、入学するお子さんについても、他区では知りませんけれども、非常に増えている。品川区の教育に魅力を感じて、品川区に越してきていただいている保護者の方もかなり増えているという状況もありますので、私たちは自信を持って進めてまいりたいと思います。","voiceIndex":167,"id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問","question":"この間、ちょっと気になるのが保護者の評価です。区教育委員会のアンケート、学校教育施設に関する保護者アンケートの中では、義務教育を４・３・２制にすることについて、半数以上が否定的な意見を持っています。小中一貫教育はよい取り組みと思うかというところも、やっと半分の支持といったところでは、親の理解が進んでいないと思いますが、この点はいかがでしょうか。","respondent":"冠木指導課長","answer":"そういった親御さんの声も含めて、私どもの努力は報われつつあると感じております。","voiceIndex":169,"id":"exchange-077"},{"speaker":"金野委員","kind":"確認","question":"私のほうからは１７５ページの学校図書館運営費、まずこちらからお聞きいたします。ここに関連して、学校で今現在、行われているということを確認したいんですが、朝の読書運動ですね。こちらは現状どのようになっていますでしょうか。どの程度今、実施をされていて、例えば時間とか、曜日だとか、小学校、中学校の現状をまず教えてください。","respondent":"冠木指導課長","answer":"少し範囲を広くしまして、全校一斉の読書活動という形でお答えいたしますけれども、これは小学校、中学校とも全校やっているところです。その中で、朝の読書活動に取り組んでいる学校は、小学校は２７校、中学校は７校です。","voiceIndex":172,"id":"exchange-078"},{"speaker":"金野委員","kind":"質問","question":"今、時間と曜日ともどれぐらい行われているのかというのもお聞きしたんですけれども、次の質問と一緒にお答えください。時間と曜日をお聞きしなければちょっとわからないんですが、現状されている日数、時間帯、それによっては朝の読書を増やしていかなければ、あるいはとる時間を生み出していかなければと思うんですが、いかがでしょうか。","respondent":"冠木指導課長","answer":"は先ほど答弁漏れがございましたので。朝の読書に取り組んでいる２７校、中学校７校については、朝礼のある曜日は別としまして、そのほかの曜日については実施をしているです。","voiceIndex":174,"id":"exchange-079"},{"speaker":"金野委員","kind":"質問・要望","question":"朝の時間１０分から１５分、これは大変貴重な時間なので、学校運営の中でも、学校生活の中でもなかなかとりにくいというのはある程度理解ができるところかなと思いますが、何とかこれは頑張っていただきたいというところであります。そこら辺、学校ではどんなふうに本の選定というのはされているのでしょうか。","respondent":"冠木指導課長","answer":"先ほどお答えした後半の部分で、子どもたちの考える力をつけていかなければいけない。","voiceIndex":176,"id":"exchange-080"},{"speaker":"金野委員","kind":"質問","question":"続きまして１７０ページの特色ある教育活動経費、こちらをお聞きします。こちらは各学校の独自性を生かした活動として、各学校が必要と思われる教育活動をされているとイメージをしているわけですが、成果報告書では１１項目の活動が記載されていて、学校数も記載されているところもあればというところなので、これはどれがどういうふうに学校の特色なのか、この仕組みはどうなっているのでしょうか。","respondent":"冠木指導課長","answer":"特色ある教育活動ということでまとめたもので、ちょっとわかりづらい部分があったのでおわびを申し上げますが、考え方としては大きく３つございまして、１つは学校がそれぞれの学校の特色化を出していくということで、こんなことをやりたいというご提案を教育委員会が承りまして。","voiceIndex":178,"id":"exchange-081"},{"speaker":"金野委員","kind":"提案","question":"３パターンがあるということで、それでは自己提案型と言っていいんでしょうか。こちらはいわゆる予算的なものなんですけれども、上限というのはあるんでしょうか。活動によってはさまざま費用がかかるものもあるでしょうし、そうじゃないものもあるでしょうし、一概に予算の条件というのはあれでしょうけれども、そういうのはある一定のものがあるんでしょうか。","respondent":"冠木指導課長","answer":"その上で私どもが事務局、それから課長の面接、最終的に教育長の面接まである場合もあるんですけれども、そういった中で効果が上がる部分について、私どもで採用していくです。スタートはお金の部分についても提案をいただいております。","voiceIndex":180,"id":"exchange-082"},{"speaker":"金野委員","kind":"提案","question":"面接を経て、採用されたものに対しては予算を出してくださるというところで、わかりました。ですので、できるだけこの自己提案型の学校がやりたいというところには、ぜひ協力をしていただいて、面接を経てと段階を少し軽くしていただいて、活動の幅を広げてあげていただきたいと、このように要望して終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":182,"id":"exchange-083"},{"speaker":"渡辺委員","kind":"質問","question":"私は、１７０ページのまちの人々に学ぶ授業経費と、今ありました特色のある教育活動経費の中の有識者講演のところで伺いたいと思います。平成２２年度、まちの人々に学ぶの予算の内訳で、授業経費のところで、件数あるいは何人か、１回当たりの費用の基準がどのようになっているのか、この点を伺いたいのと、有識者の講演というのは、どのような形のものだったのか教えてください。","respondent":"冠木指導課長","answer":"まちの人々から学ぶ事業というのは、基本的に１回３,０００円ということで、大体各学校２０回程度のご案内をしています。件数につきましては、小学校が平成２２年度におきましては６２９回、中学校が２３７回、小中一貫校が１４０回の実施をしています。","voiceIndex":184,"id":"exchange-084"},{"speaker":"渡辺委員","kind":"提案","question":"その中で今、提案事業でご説明のありました特にキャリアのある方の活用、あるいは専門性の方という中で、こういった総論はまちの人々だと思うんですが、制度自体に段階とか区分けが、発展したがゆえにそろそろ必要になってくるのかなと思うんですが、この提案型を含めて、今どのようなお考えを持っているのか教えてください。","respondent":"冠木指導課長","answer":"今の制度で行きますと、そういった場合には、私どもの例えば研修会的な実施をする場合には、講師謝礼という形で基準に従ってお支払いをしている。これはそうすると、まちの人の事業のお支払いする額よりも一定程度高いお金をお支払いできるというふうに思ってあります。","voiceIndex":186,"id":"exchange-085"},{"speaker":"渡辺委員","kind":"質問・要望","question":"大事なことを言い忘れました。というのは、その具体的な施策として、今、このまちの人々以外にも、スチューデント・シティやファイナンス・パーク、すべて先がけて品川区が取り組んできた理念に通ずると思っているので、その確認をしたいと思います。それを今後どのように、そういう世の中の流れというんですか、進んでいくのか伺いたいと思います。","respondent":"冠木指導課長","answer":"これからも引き続き地域の人であるとか、あるいは企業の方々のご協力を得ながら進めてまいりたいというふうに思ってあります。","voiceIndex":188,"id":"exchange-086"},{"speaker":"渡辺委員","kind":"確認","question":"そういう中で、現場の様子をちょっと確認したいんですが、今そういう中で、受け入れる学校サイトがある、そしてそういう専門性、法律や経済、環境などもありますが、何かしたいんだという思い、提供する側、申し出をする側、この２つの関係が大事になってくる中で、見聞きしたり、あるいは今、考えられる課題として、例えば授業時数や組み立て、時期によるもので。","respondent":"冠木指導課長","answer":"いざやってみるとなかなか難しいというふうにお感じいただいたというのは、非常に私としても、逆に言うと心強いお言葉をいただいたなというふうに思ってあります。","voiceIndex":190,"id":"exchange-087"},{"speaker":"渡辺委員","kind":"質問","question":"仕組みの点で最後に伺います。それぞれ個別に弾力性を持って対応している、そういう中で、教育委員会がすべきことという視点の中で、判断は各学校がされるとして、その一歩前、実施前の段階で、今までもされていると思います。現在も校長連絡会等も含めてやっていると思います。ただ、それを制度化する時期も来ているのかなと思うので、このお考えを最後に伺いたいと思います。","respondent":"冠木指導課長","answer":"こういった取り組みを始める、そしてそれを深めて続けていくというのは非常に大事なことだと思いますので、それにはやはり学校が何を求めて、子どもたちにどういうことを伝えなければいけないか。","voiceIndex":192,"id":"exchange-088"},{"speaker":"高橋委員","kind":"質問・要望","question":"よろしくお願いします。１７０ページの全国学力調査の全校実施、それと、１７３ページ、学校教育費。それから、学校教育費でいいんだと思うんですが、全般、教員の話になってしまいますが、小中学校の教員の人事権を２３区へという要望を出しているということなんですが、その人事権を置くということへの必要性、重要性と、それへの現在の展望をお尋ねいたします。","respondent":"冠木指導課長","answer":"全国学力調査については、ご存じのように、平成２２年は抽出調査で行われました。品川区は抽出されなかった学校についても予算措置をしていただきまして実施をしたところです。状況ですが、そういう状況ですので、これは全国的に順位とか、そういうことは出ません。","voiceIndex":195,"id":"exchange-089"},{"speaker":"高橋委員","kind":"質問","question":"考える力、発展する力云々というお話がありましたが、そういったことの流れの中で、日野学園が夏に休業中の勉強合宿をされているということなんですが、これ、予算上ちょっとどこに出てくるのかわからないのですが、そのことで、その費用はたしか大学生などお手伝いの方の費用だったような気がするんですが、それは日野学園の正規の授業以外のいわゆる力をつけるためのものだと伺っています。","respondent":"冠木指導課長","answer":"ほかの学校の学力向上策、勉強合宿について先に申し上げますけれども、勉強合宿については、この日野学園の実施状況については、かなり成果が上がっている、保護者の声も大きいと、評価も高いという状況ですので。","voiceIndex":197,"id":"exchange-090"},{"speaker":"高橋委員","kind":"質問","question":"それをして正規の授業プラス力をつけるための日野学園のほうでやられている、そのほかの中学校で、今、広げるというお話がありましたが、合宿ではなくて、夏休みに正規の授業ではなくて先生が声をかけて補習をしたりとか、あるいは学校として組織的に中学校は今週１週間は英語と数学と国語、１時間ずつやるとか、そういった夏季講習というか、補習についての取り組みが組織的に行われているところや。","respondent":"冠木指導課長","answer":"合宿以外のところですけれども、これは小中学校全校で、今、中学校というお話でしたけれども、小学校も含めて全校でサマースクールを実施しておりまして、授業時数以上の部分で取り組んでいるところです。","voiceIndex":199,"id":"exchange-091"},{"speaker":"高橋委員","kind":"質問・要望","question":"受験生チャレンジ支援、東京都の施策で、福祉部局でやられているもので、中学３年生、高校３年生が塾に行ったりする費用を借りられると。品川区では、就学援助を受けている方が中学校でいうと３０％を超えているというところから、このような受験生チャレンジ支援貸付事業を中学校のほうでぜひ生徒や保護者の方に周知していただきたいと思います。","respondent":"和氣学務課長","answer":"この制度については生活福祉課のほうでやっていますので、生活福祉課を通じまして各学校に周知をしています。","voiceIndex":201,"id":"exchange-092"},{"speaker":"高橋委員","kind":"質問・要望","question":"書類はちょっとどこで配るかわかりませんが、受付のほうは福祉系のところでやられているということなので、すみません、ちょっと款がまたいでしまったかと思いますが、そういったことで、学力の格差につながらないような方策が幾つかそうやってありますので、学校のほうでフォローしていっていただきたいと思います。","respondent":"平澤生活福祉課長","answer":"受験生チャレンジ支援貸付についてお答えいたします。本年度から名称が変わりまして、受験生チャレンジ支援貸付となりましたが、８月末現在の実績で５５件の申請がございました。","voiceIndex":203,"id":"exchange-093"},{"speaker":"吉田委員","kind":"質問","question":"成果報告書の１７７ページ、学校保健費の歯磨き指導指導法研究委託についてと、１７１ページの和楽器による音楽教育経費と、できれば、１７１ページのすまいるスクールについてお尋ねしてまいります。初めに、１７７ページ、歯磨き指導法研究委託ですが、小学校費のみですけれども、中学校費にはありませんが、そのわけを教えてください。","respondent":"和氣学務課長","answer":"この事業につきましては、小学校２校を今対象にしまして実験的にやっているですので、小学校費だけになっているところです。","voiceIndex":206,"id":"exchange-094"},{"speaker":"吉田委員","kind":"質問","question":"区内の歯科医師の方数人にお話をお伺いしてまいりましたが、小学校１年生から中学１年生の間は、永久歯と乳歯が混在して、とても歯が磨きにくいと。特に生え立ての永久歯は虫歯になりやすいとお聞きしてまいりました。中学校二、三年になりますと、統計的に全く虫歯がないお子さんと、虫歯ばかり多いというお子さんに二分する傾向があるというお話もお伺いしました。そのようなことをどのようにお考えか。","respondent":"和氣学務課長","answer":"これまでは学校歯科医が学校で講演をしたりとか、個別指導をしたり、歯科健診のときにお話をしてくださったりしていたんですが、特にこの小学校の歯磨き指導というのは、２校で毎日５分間、子どもが全員一斉に歯磨きをするという、そういうことを実施して歯磨き習慣をつける。","voiceIndex":208,"id":"exchange-095"},{"speaker":"吉田委員","kind":"質問・要望","question":"小学校で試験的というお話ですけれども、できれば中学校でも歯磨き指導法の研究委託を取り入れていただきたいと。やっぱり健康は食からとも言われておりますし、忘れがちな歯の大切さを学校という集団の中でしっかりしたプロの歯周ポケットのブラッシングの仕方などをこれからご指導していただきたいと思いますが、ご意見をお願いします。","respondent":"和氣学務課長","answer":"さらに歯科医師会とも相談しながら、いい啓発方法について考えてまいりたいと考えていますし、施設的にも鏡などを増やして、歯磨きができる環境を整備しています。","voiceIndex":210,"id":"exchange-096"},{"speaker":"吉田委員","kind":"質問・要望","question":"前向きなご答弁ありがとうあります。楽器の種類や実施方法などの検討とありましたが、私、個人的なんですけれども、琴は選択はとてもいいんじゃないかと考えています。小さいお子さんでも弦をしっかり押さえれば音階にもなりますし、ここでお聞きしたいのは、各学校を回していらっしゃるみたいなんですけれども、その期間を教えていただきたいんです。お願いします。","respondent":"冠木指導課長","answer":"和楽器の指導で、琴であるとか、鼓であるとか、そういったものを巡回をしていくという形をとらせていただいておりまして、期間については、１年を通して巡回をしていくという形をとってありますので、特にその一定の期間というのは。","voiceIndex":212,"id":"exchange-097"},{"speaker":"吉田委員","kind":"質問","question":"３時間という音楽の時間でやっていらっしゃるそうなんですが、私はとても短いなと思うんですよね。せっかく日本の伝統に触れるチャンスですので、１校１校もう少し長く時間を置いていただきまして、お子さんができたという少しの達成感を感じてもらえたらいいなと私は思っておりますが、その辺はいかがでしょうか。","respondent":"冠木指導課長","answer":"ですから、この和楽器の授業で琴の授業については、これは基本的なベースということで各学校進めてまいりますけれども、そこから発展する部分については、また別の応援の仕方があろうかなと考えておりますので、委員のおっしゃるように。","voiceIndex":214,"id":"exchange-098"},{"speaker":"吉田委員","kind":"質問","question":"一応、琴のお値段なんですけれども、大体９万円ぐらいから１５０万円ぐらいですよね。頑張ってください。すまいるスクールについてご質問いたします。すまいるスクールは学童クラブを発展させたものとお伺いしておりますが、改めて学童クラブとの違いや特徴などを教えていただけますでしょうか。","respondent":"齋藤庶務課長","answer":"特徴ですが、教育的な要素ということを多分に含んでおりまして、勉強する時間、地域と連携したお茶やお花、将棋、囲碁といったような講座を設けまして、伝統文化を子どもたちに伝えているです。","voiceIndex":216,"id":"exchange-099"},{"speaker":"吉田委員","kind":"意見","question":"たしか学童クラブでは、国の基準で１人当たりの占有面積がありまして、定数の弾力化は難しいと認識しておりますが、すまいるスクールでの１人当たりの占有面積はどうなっているのか、その点はクリアされているのかをお教えください。","respondent":"齋藤庶務課長","answer":"ただ、実際に参加しているお子さんの数で割り返すと、３８校中２１のすまいるスクールで達していると。学校ですので、グラウンド、体育館、特別教室も活用しておりますので、この基準を大まかな上ではクリアしているというふうに考えております。","voiceIndex":218,"id":"exchange-100"},{"speaker":"吉田委員","kind":"質問・要望","question":"すまいるスクールは、親にとって大人の目があり、防犯カメラや電子錠など守られた場所で安心して子どもを預けられるところなので、これからも頑張っていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-101"},{"speaker":"本多委員","kind":"質問・要望","question":"学校改築、完成したときに、日野学園のときに近隣に配慮し過ぎて、設計変更もしたり、完成したら今度は廊下側の窓をあかないようになど、近隣に配慮しまして、今年の夏、すごく暑くて、去年もそうですが、児童・生徒に熱中症が出てしまって、その対策はもうやっていただいて窓があくようにはなったんですが、近隣に配慮し過ぎだなという感がありますので、今。","respondent":"冠木指導課長、齋藤庶務課長","answer":"しかしながら、そういった状況があったことは私も確認をしていますので、そういった部分については、引き続き、これ、未来の子どもたちですので。第三日野小学校で、南校舎、道路側の窓、これは近隣の方からプライバシーを配慮してほしいということで、目隠しのシート張りをしております。品川学園、渡り廊下があります。ここの渡り廊下を同様な理由で窓を少し小さめにしています。","voiceIndex":222,"id":"exchange-102"},{"speaker":"本多委員","kind":"質問・要望","question":"教科書なんかにつきましては、品川区小中一貫教育要領も平成２２年５月１日に改正されて、歴史や我が国の領土問題が明記されておりますので、大変充実してきているなと思いますので、ぜひその辺も考慮しながら進めていただきたいと思うんですが、あと、出版会社も含めまして、ニッポニアニッポンというトキの生息のこととかが、最近出なくなってしまったのが非常に残念だなと。","respondent":"冠木指導課長、齋藤庶務課長、安藤文化スポーツ振興課長","answer":"それからあと、いろいろと教科書のことであるとかご意見をいただきましたので、踏まえて対応してまいりたいというふうに思います。この件につきましては、教育委員会では所管しておりませんので、どの学校が一般開放できていて、できていないかは私どもでは把握しておりません。ただいまのグラウンドの件に関しまして、一応、私ども地域スポーツ開放をしている関係上、そういう近隣との関係で摩擦といいましょうか。","voiceIndex":225,"id":"exchange-103"},{"speaker":"本多委員","kind":"質問","question":"学校のマナーのことで、１つ質問させてください。私、ＰＴＡのある方からお手紙をこの平成２２年度のことでいただきました。それで、帰るときに、「校長先生、ありがとうございました」と言って帰るんですね。それで、校長先生がかわいそうだというお手紙をいただきました。これは全校の校長に教育委員会からフォローするべきだと思うので、その必要性を答えてください。","respondent":"齋藤庶務課長","answer":"今初めてお聞きいたしました。事実として把握してございませんでした。同様なことについては、今後対応してまいろうと思います。","voiceIndex":229,"id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、成果報告書１７６ページの学校給食費についてお伺いしたいと思います。区としても、先日の６月の請願審査の中では学務課長が、手づくり給食を基本とする姿勢に変更は全くないということで答弁されていますけれども、全面委託となったこれからも完全手づくりを守っていくということで確認させていただいていいか、このことをお聞かせいただきたいと思います。","respondent":"和氣学務課長","answer":"給食の調理代行というのは、調理を代行するだけであって、私どもの給食に対する考え方を変えるものではございません。このため、基本的に手づくりということについては遵守するということで契約をしています。","voiceIndex":232,"id":"exchange-105"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"完全手づくりでこれからもいきますよということは、どこかに明記されているかどうかというのをちょっとお聞きしたいんですが。","respondent":"和氣学務課長","answer":"契約の際にも、手づくりでいくというのは条件に入ってありますので完全手づくりでやる。ですから、逆に言いますと、調理代行が勝手につくってもらっては困るということです。私どもが指示したとおりにつくっていただく、そのことが前提で契約しています。","voiceIndex":234,"id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"完全手づくりということが明記されている。これから先も完全手づくりというのは担保されていくということで確認させていただいてよろしいですね。","respondent":"和氣学務課長","answer":"調理の手順書も含めまして私どもは調理代行に提供していますので、いつ、どういうふうにだしを入れなさいも含めまして細かく指示をしていますので、手づくりでやっていくことに変わりございません。","voiceIndex":236,"id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう中で、栄養士からの指示というところで学校給食の調理がされるわけですけれども、そのところで直営であれば調理師がそこをチェックできるというところが、この民間委託というところでは、栄養士の指示をそのまま受け入れるということになるので、栄養士がそこのところをしっかりと守っていくというところがないと、なかなかそこの担保というのが難しいのではないかなと思うんですけれども。","respondent":"和氣学務課長","answer":"この料理はこうつくりましょう。それから、栄養士も含めて反省会をやって、献立反省会等もやります。実際にあと、栄養士がいないところは栄養補助職員とか、他の職員が実際に確認もします。ということで、担保はできるというように思っております。","voiceIndex":238,"id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"足立区の例では、１４年かけて全校が民間委託されたところで、委託料を削減するという交換で、献立を複雑にしないですとか、手づくりのジャムやカスタードクリームとかはつくらないとか、手のかかった献立を変えていくというような、そういう交換条件が出されたということなんですけれども、そういうことは品川区ではこれからはされないということでよろしいでしょうか。","respondent":"和氣学務課長","answer":"ご心配のようですが、しないという前提で進めてありますので、繰り返しの答弁になってしまいます。","voiceIndex":240,"id":"exchange-109"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、これ、学校給食における食中毒の手引きというのを見ましたら、学校栄養職員を衛生の管理責任者とすると、現に栄養職員がいないところは、調理師資格を有する学校給食の調理員等というふうなことでなっているんですが、この衛生の管理者というところ、栄養職員がいないところの管理責任者というのは、品川区ではどうなっているのでしょうか。","respondent":"冠木指導課長、和氣学務課長","answer":"現在の学校栄養士の数ですけれども、小学校が１５名です。それから中学校が７名です。国基準では３校に１名という基準なんですが、東京は２校に１名という基準でやらせていただいて、私どもはそれで栄養士が２校をしっかり見ていただいて、それ以外に非常勤職員なり、栄養補助職員を十分活用して。","voiceIndex":242,"id":"exchange-110"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、学校栄養職員のいない学校というのは、この衛生の管理責任者というのは、実際はいないということになるのでしょうか。","respondent":"田村教育次長","answer":"先ほど来、学務課長がお話ししているのは、栄養士は２校に１校配置、それで、給食業務が調理代行に来年４月に全校委託しますので、区の職員で、給食経験があって、さらに栄養士資格を持っている方もいますので、それを給食業務補助という形で。","voiceIndex":245,"id":"exchange-111"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私が見ているのは、これ、学校給食における食中毒防止の手引きということなので、学校給食のことについて書かれているものだと思うんですけれども、ということは、栄養職員がいないところは、かわりに調理師をされていた方が配置されて、そしてそういう業務を行っているということで考えていいのでしょうか。","respondent":"田村教育次長","answer":"２校に１校の栄養士の指示に基づいて、給食業務の人がその対応をしているという形です。","voiceIndex":247,"id":"exchange-112"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今は過渡的なところでそういう形で配置をされていると思うんですが、２３区の中でも民間委託されたところは、すべて栄養士が配置されているということで聞いているんですけれども、そういう点では、本当にしっかりと民間委託業者を安全な給食を子どもたちに提供するというところで衛生管理をしていくという点で、そういう仕組みが必要なのではないかと思うんですけれども。","respondent":"和氣学務課長","answer":"既にもう残り４校になるぐらい代行は進んでおりまして、その中でしっかり衛生管理していますので、今の体制をさらに充実させるという形で対応したいと思います。","voiceIndex":249,"id":"exchange-113"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう１つお聞きしたいのが、この民間委託を導入するに当たっては、財政効率ということを１つの大きな導入の理由ということで述べられていたと思うんですが、先日の６月の議会のところの議事録を読みましたら、学務課長の答弁で、委託にした場合、シミュレーションでは１校当たり２億円以上の安上がりになるということがありますということで言われているんですけれども、これ。","respondent":"和氣学務課長","answer":"申しわけございません。誤りです。失礼いたしました。１校２億円ということではなくて、最終的に平成２４年度で３億３,０００万円ほど経費が削減できるということで、途中経緯が全校で２億円を、私、１校２億円と言ってしまいまして、大変失礼いたしました。","voiceIndex":251,"id":"exchange-114"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結局は、全校で導入した場合は、３億３,０００万円ぐらいの予算の削減になるということでしょうか。それが二四、五％ということになるのかについてもお聞かせいただきたいと思います。","respondent":"和氣学務課長","answer":"実際いろいろな経費がかかっていますので、単純には差し引きはできないと思いますが、おおむね３億３,０００万円ほど経費を浮かすことができたというふうに考えております。","voiceIndex":253,"id":"exchange-115"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、チーフやサブチーフでも二十数万円とか、パートの方ですと、本当に１０万円前後という、そういう賃金で働かざるを得ないというところで、これが今、不景気だから成り立つという部分があるんじゃないかなと思うんです。そういう点では、ぜひとも私はそういう中でも質を落とさない基準をしっかりと守るというためにも、直営をこのまま一部残していただきたいと思うんですが、いかがでしょうか。","respondent":"和氣学務課長","answer":"現在、順調に代行が進んでおりますので、このまま経緯したいというふうに考えております。","voiceIndex":255,"id":"exchange-116"},{"speaker":"山元委員","kind":"質問・要望","question":"私のほうは、１６９ページの教育指導費の中の教育センター運営費、そして１７３ページの社会教育費の中の図書館経費の中でお聞きしたいと思います。初めに、１６９ページの教育センター運営費ですけれども、その中に維持運営費、また教育相談事業費、そして調査研究事業費というふうに載っておりますけれども、この内容を教えていただきたいと思います。","respondent":"冠木指導課長","answer":"それから調査研究につきましては、教員向けの実技研修であるとか、教育相談研修を実施しておりますので、そのお金ということになります。","voiceIndex":258,"id":"exchange-117"},{"speaker":"山元委員","kind":"質問・要望","question":"実際この相談内容というんですか、具体的にどういうことが相談されたのか、また、どういう方たちが来たのか、世代別で中学生の方たちなのか、そういうことも教えていただきたいと思います。近年、傾向性として、こういう問題のご相談が多いということがあれば、またそちらも教えていただきたいと思います。","respondent":"冠木指導課長","answer":"この２,６６４件というのは延べ件数ですので、登録件数、主訴別ということでご案内してまいりたいと思いますけれども、学校生活にかかわる相談については４５.２％、それからご本人の性格であるとか、行動についてのご相談が約３０％、それから、家庭生活であるとか、知能。","voiceIndex":260,"id":"exchange-118"},{"speaker":"山元委員","kind":"質問・要望","question":"実際、７人の先生方がいらっしゃるということですけれども、その先生たちというのは、どういう方たちなのか教えていただきたいということと、あと、このご相談なんですけれども、１組というんですか、その相談時間というのでしょうか、そういう時間がどのぐらいとっているのか。大体１日平均どのぐらいの方が相談にみえるのか。","respondent":"冠木指導課長","answer":"臨床心理士を目指して、少しまだ臨床時間が足りないという若手の方も若干混ざっておりますが、基本的に臨床心理士ということで対応しています。相談の時間は、これは長ければいいというものではございませんので、基本的に４０分程度が基本になってくるかなと思います。","voiceIndex":262,"id":"exchange-119"},{"speaker":"山元委員","kind":"質問・要望","question":"１日の人数聞きましたけれども、この先生方のローテーション、７人の方たちのローテーションというんですか、それは７人の中で１週間しているかと思うんです。その辺のローテーションを教えていただきたいということと、月平均お一人がどのぐらいご相談に当たるというか、会場にいらっしゃるのか教えていただけますでしょうか。","respondent":"冠木指導課長","answer":"勤務の考え方としては、中にお二人は月１６日勤務していただいておりますので、大体週４日入っていただく方がお二人、それから、週３日入っていただく勤務の方がそのほかという形になっています。","voiceIndex":264,"id":"exchange-120"},{"speaker":"山元委員","kind":"質問・要望","question":"ちょっと計算すると、かなりの高価な、時間で計算すると高額な報酬になるかなと思いました。大変なお仕事かと思いますけれども、その分ぜひ希望のあるアドバイスをしていただきたい、そのように思います。１７２ページの社会教育費の中の図書館経費について伺いたいと思います。その反面、資料整備費が予算に対して今度は半分近くの金額になっていますが、その辺の内容も教えていただきたいと思います。","respondent":"中元品川図書館長","answer":"予算編成の段階で１カ所に固まって入っておりました印刷費等をそれぞれの事業に応じたところに振り分けさせていただいて、今後の予算編成におきましては、児童サービスで使うものについては児童サービスのところで、そのそれぞれの事業で管理をしていこうということで。","voiceIndex":266,"id":"exchange-121"},{"speaker":"山元委員","kind":"質問・要望","question":"そのときの館長からは、とってもメリットはあるけれども、検討していきたいと、そのようなお話がありましたし、また、要望がないという、そんなお話も出ました。実際、１年たって、利用者の方からそういう希望といいますか、そのような意見が入っているかどうかを教えていただきたいと思います。","respondent":"中元品川図書館長","answer":"今般、文化庁のほうから、９月１日決定で電子書籍の流通と利用の円滑化に関する検討会議というところから、図書館と公共サービスのあり方に関する事項というまとめが出されておりまして、今後、公共図書館においても、ただ、今後は電子書籍の発行元との利害調整とか。","voiceIndex":268,"id":"exchange-122"},{"speaker":"山元委員","kind":"質問","question":"過日、プレス発表に、大井町でもサービスコーナーで本の出し入れがあるかと聞きましたが、今後その計画がありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":270,"id":"exchange-123"},{"speaker":"西本委員","kind":"質問・要望","question":"最後に、教育指導費に入るのでしょうか、防災訓練についてお聞きいたします。ここの伊藤学園なんですけれども、つくった際には一般開放を視野に入れているわけですから、来場する規模なども当然考えられた設計になっているはずと思っておりました。しかしながら、現在はモラルが悪いということなのでしょうか、この伊藤学園は、駐輪場は一般開放の方たちのためのものではありません。","respondent":"齋藤庶務課長","answer":"ただ、伊藤学園につきましては、狭隘な敷地でしたので、三、四十台、職員用の駐輪場しか確保できなかったです。設計上、伊藤学園につきましては、一般開放用の駐輪場も見込んでの設置が困難だったです。","voiceIndex":272,"id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"締め出ししているわけですから。ですから、もうちょっとやり方はあるんじゃないかなと思うんです。それならば、じゃあ、今後、学校建設、今もずっとやっていっていますけれども、これからも含めて、学校建築の場合、どういう考えをされるんですか。一般開放するという上で、敷地内にとれないから、じゃあ、一般開放のときの自転車置き場はつくらないという方向なんでしょうか。","respondent":"齋藤庶務課長","answer":"来年度竣工する豊葉の杜学園では、５５台ぐらい一般開放用の駐輪場は予定しております。","voiceIndex":274,"id":"exchange-125"},{"speaker":"西本委員","kind":"質問","question":"それならば、今の考え方、それを、今建設しているところ、それから伊藤学園も含めて、はっきりと地域の方に言うべきだと思います。そうしないと、学校の対応が大変です。伊藤学園はこういう台数しかないので、一般開放のための自転車は使わないでくださいというところまで言わないと納得しないと思います。その件は、これからの方法についても同時にお伺いします。","respondent":"齋藤庶務課長","answer":"品川区２２キロ平方メートルということは、ディズニーランド２２個分です。３個分に１つは温水プールがあります。歩いても、泳いでも、ぜひ健康づくりということにご理解いただきたいというのが教育委員会としての考えです。","voiceIndex":276,"id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"これは非常に問題あるなというふうに思っています。職員のためのということも、あいているじゃないかと言われますよね。地域の方は、土日あいていたら使わせろというふうに言いますよ。そこも含めて、折り合いがつくような方法がもしもあるのだったら、今後ぜひ考えていただきたいなというふうに要望します。危険性と節電の関係、これからの考え方はどのような考え方でやっていきますか。","respondent":"和氣学務課長","answer":"私どもとしましては、今回、節電をしっかりやってくださいということですが、危険な場所はつくらないでほしいというお願いをしたんですが、どうも学校が一生懸命やり過ぎてしまって、私ども、実際に見に行って危ない箇所については電気をつけるように指導してまいりました。","voiceIndex":278,"id":"exchange-127"},{"speaker":"西本委員","kind":"質問・要望","question":"防災訓練、これ、答弁いただけるかどうかなんですが、今、防災訓練をすると、教えの中に机の下に隠れなさいと言うんですけれども、机がなかったらどこに行くのということで、非常に周りの環境を見た上での防災訓練という、そういう指導の方法がやっぱり必要だというふうに、今、マスコミ等でも騒がれているところですが、その防災訓練について、改善するのか、その一言だけお願いします。","respondent":"冠木指導課長","answer":"今回の３月１１日の大地震を受けまして、各学校全校で防災訓練の見直しをしたところです。","voiceIndex":280,"id":"exchange-128"},{"speaker":"伊藤委員","kind":"確認","question":"質問に入る前に、午前中の沢田委員の答弁の確認で、日本固有の領土の確認という話がありました。それが区教育委員会の見解だと聞きました。ならば、なぜそう明記する教科書を選ばなかったのか、その理由を端的に教えてください。お願いいたします。","respondent":"冠木指導課長","answer":"これは教育委員会の責任と権限において、それぞれの教育委員がそれぞれの見識でご判断されたというふうに思ってあります。","voiceIndex":284,"id":"exchange-129"},{"speaker":"伊藤委員","kind":"質問・要望","question":"１点、先ほど中学生という話が出たんですけれども、この事業の本来の目的は、小学校の中で基本的な習慣を身につけて、それで自動的に中学校でもそのことをしていくということがメーンであると思っていますので、安易に中学生に拡大するというよりは、むしろ小学生のレベルできちんと歯磨きをする習慣をつけていくべきだと思うんですが、そのことについての答弁をお願いいたします。","respondent":"和氣学務課長","answer":"しかも、このモデル事業につきましては、集団でみんなで見合いながらやるというところで、しっかりと、逆に言うと、歯磨きを楽しむということも含めまして教えているところですので、ここで得られた知見をさらに拡大しながら。","voiceIndex":286,"id":"exchange-130"},{"speaker":"伊藤委員","kind":"意見","question":"それで、生徒指導対策費に関連してということになると思うんですが、３月１１日のときに、荏原平塚学園と、それから三木小学校がディズニーランドに行っていました。だから、３・１１でこれだけの教訓を得たわけなんだから、やっぱりそのことについては品川区の教育委員会としては１つのマニュアルなり、方向性を示していくべきだと思うんですが、お答えをお願いいたします。","respondent":"冠木指導課長","answer":"委員のご指摘のように、３・１１のときには、複数の学校が校外学習に行っておりまして、それぞれがその場その場で判断を求められるという状況がございました。今の三木小学校であるとか、荏原平塚学園についても同様です。","voiceIndex":288,"id":"exchange-131"},{"speaker":"伊藤委員","kind":"質問","question":"最終的な判断はもちろん現場に任されていることはわかるんだけれども、だけれども、品川区の教育委員会としては、地震や台風のときにはこうすべきであるとか、それから、その後のさまざまな事由が生じた場合には、生徒児童の安全を確保するために、基本はこうですよと、具体的な現場の責任は学校長で対応してくださいというようなことをしっかりと、これをもとにしてまとめていくべき。","respondent":"冠木指導課長","answer":"３・１１のときの校外学習ももちろんですけれども、各学校の対応にはさまざまな教訓がございましたので、今、委員のお話のような、それをどういった形で学校に伝えていくかというのは、私たちの１つの責務であるというふうに考えてありますので。","voiceIndex":290,"id":"exchange-132"},{"speaker":"伊藤委員","kind":"質問","question":"だけれども、学校の立地条件であるとか、それから、その学校がどういう地形的な状況があるかということについては、当然一概に言えないし、千差万別なんだから、その最終的な判断は学校長に任せるとしたとしても、もう少し言いますと、地域別にした基本的なマニュアルなりを具体的に落とし込んでいかないと、この３・１１の教訓はより生かせないということを痛感するんですが、いかがでしょうか。","respondent":"冠木指導課長","answer":"例えば、今回、帰宅困難ということもありまして、引き渡しの問題がありました。それに対応して代理人の引き渡しまで保護をする旨、そういったマニュアルを整備し直した。あるいは、引き渡しの場所については、いつもはグラウンドだけだったんだけれども、今度は教室でやりますよ。","voiceIndex":292,"id":"exchange-133"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"私のほうからは、１６９ページ、品川区研究学校について、それと１６９ページ、スクールカウンセラー派遣費、１７０ページ、１～６年生の英語科経費、そしてちょっとページ数がわからなかったんですが、性教育について、主に子宮頸がんワクチンについての教育についてお伺いします。よろしくお願いします。","respondent":"冠木指導課長","answer":"そこからそれぞれの学校の取り組みなども入れまして、研究テーマを設定して研究をしていただいているところですけれども、やはり私ども品川区がこれまで小中一貫教育を進めてまいりまして、より具体的で。","voiceIndex":295,"id":"exchange-134"},{"speaker":"石田（慎）委員","kind":"質問","question":"１点、小中一貫校のグループでやられるということで、これは小中一貫校は小中一貫校で１校というふうになっていて、要は、予算の時期では、小学校が１０校ですね。それが１８校になっていたりしているので、その点をお伺いしたいので、そこを改めてお聞かせください。よろしくお願いします。","respondent":"冠木指導課長","answer":"考え方として、平成２２年度の研究学校として載っているのは、平成２１年、平成２２年の２年間の指定の後半部分の学校と、それから平成２２年、平成２３年の前半部分の学校があるということで、そこで相違は出てまいります。","voiceIndex":299,"id":"exchange-135"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"国が補助金をなくしても、区としてこれをやるべきだという強い気持ちでやられたと思いますので、ぜひ進めていただきたいと思います。この理由をお知らせください。それと以前、スクールカウンセラーについて、増員をしたほうがいいのではないかと、その必要性を考えれば、増員を行うべきではないかという要望をしましたところ、増員はしない方向だというご答弁でした。改めて区の見解をお聞かせください。","respondent":"冠木指導課長","answer":"ただ、人数を多くしてカウンセリングを同じ方について何回も何回もやるということが、それが果たしてカウンセリング効果が出てくるかというところについては、やはり一定期間置きながら、１週間なら１週間置いてカウンセリングを継続していくという手法のほうが。","voiceIndex":301,"id":"exchange-136"},{"speaker":"石田（慎）委員","kind":"質問","question":"わかりました。教育センターにも相談員がいる。よろしくお願いします。次に、１～６年生の英語科経費について。これも平成２１年度と平成２２年度の決算で約１５０万円の差がありますが、その辺の理由と、外国語指導助手、いわゆるＡＬＴですか、この方たちの雇用形態はどのようになっているのかお知らせください。","respondent":"冠木指導課長","answer":"お金の差異については、これは実績差ということでございまして、実績が多かった、少なかったということでの差です。ですから、前年の実績にあわせて委託契約していますので、そういった意味での差ということでご理解いただきたいと思います。","voiceIndex":303,"id":"exchange-137"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"決算の差が実績によるものだということですが、そうすると、平成２１年度と平成２２年度を比較したときに、平成２２年度のほうがこの英語教育についてより取り組んだという認識でいいのかお答えいただきたいのと、この委託契約でありますが、この委託契約の契約の内容についてお伺いしたいんですが、現場で実際に教えていただいている外国語指導助手、ＡＬＴの方に対して。","respondent":"冠木指導課長","answer":"１つ目の実績につきましては、当然、年度が変わりまして、平成２２年度のほうが子どもたちの数が増えていますので、学級増になってありますので、確実に増えているです。そこも含めてご理解いただければと思います。","voiceIndex":305,"id":"exchange-138"},{"speaker":"石田（慎）委員","kind":"質問","question":"委託契約、外国語指導助手の雇用形態について、これは担任の方が教育現場において、その場でやっぱり指示をしたいというときもどうしても出てくるのかな、そんな中で、指示ができない理由の１つとして、雇用形態が委託において契約をしているから、実際に現場で指導ができないという中で、やっぱり教育現場においては、直接ＡＬＴに指示をする必要性があると思うんですが、この雇用形態を変えて。","respondent":"冠木指導課長","answer":"この問題については、非常に悩ましい状況があることは事実でございまして、私も教員の出身なので、今委員のおっしゃるような状況というのがあってこそ、子どもたちの力がついてくるということも１つ認識としてはありなのかなと思ってあります。","voiceIndex":307,"id":"exchange-139"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ぜひさまざまな視点で考えていただきたいと思います。平成２２年度、中学一、二、三年生、平成２３年度は７年生となっておりますが、学校における教育、まずどういう病気で、ワクチンはどういうものなのかなど、子どもに、また親御さんにも知ってもらうことが大事だと思います。保健所との連携も含め進めていただきたいのですが、区の見解をお知らせください。","respondent":"和氣学務課長","answer":"ところが、前日、大震災ということで、急遽中止になりまして、残念ながら開催できませんでした。その代替で、今、日程を調整しているんですが、なかなか日程調整がつかないのですが、保護者向けの講演会を開催したいと考えています。","voiceIndex":309,"id":"exchange-140"},{"speaker":"武内委員","kind":"質問・要望","question":"私は、１６８ページの教職員研修、１７０ページの市民科、１７５ページの学校運営費でお伺いします。例えば今、学校の中で市民科の授業で防災を取り上げていらっしゃるということで、また、３・１１以降、この市民科の中で、この３・１１を踏まえて、何か子どもたちへの教育、対応というんですか、これが変わったところがあれば教えていただきたいと思います。","respondent":"冠木指導課長","answer":"今回、３・１１を受けまして、各学校が避難訓練の形であるとか、マニュアルをよりよいものに変更いたしましたので、それにあわせた避難訓練を、今、随時実施しています。","voiceIndex":312,"id":"exchange-141"},{"speaker":"武内委員","kind":"質問","question":"伊藤学園での宿泊、以前は荏原第三中学校時代にもあったと聞いていますけれども、そういった実際に即した非常にいい取り組みだとは思います。釜石の奇跡。学校にも本当に負担がかかりますけれども、やっぱり今回の釜石のものを見たときに、学校で教えられたことを小学生、中学生が守ることで地域の人の命まで救ったという、これをぜひお願いしたいと思うんですけれども、それを一言お聞きしたいと思います。","respondent":"冠木指導課長","answer":"釜石の奇跡につきましては、私もいろいろ勉強していますので、そういった部分についても学校のこれからの指導に生かしていきたいというふうに思ってあります。なお、学校においては、登校直後であるとか、朝の始業前などの避難訓練なども、今、実施をし始めているところです。","voiceIndex":314,"id":"exchange-142"},{"speaker":"武内委員","kind":"提案","question":"ぜひよろしくお願いします。実は私、平成１６年の予算特別委員会で、子どもたちに対するヘルメットの配付を提案しまして、当時はあまりピンと来なかった部分もありました。今回の３・１１の大震災を受けまして、今年の３月１６日の予算特別委員会で改めてこれを提案しまして、そのときに市川教育次長だったんですが、いろいろな角度から検討しますということで第２回定例会、大変うれしく思っているんです。","respondent":"和氣学務課長","answer":"ですから、実際、訓練でも子どもたちはヘルメットをかぶって、地域に貢献するんだというような意識を持たせながら訓練をしたりもしています。","voiceIndex":316,"id":"exchange-143"},{"speaker":"武内委員","kind":"質問","question":"この方が、中にはこういうお話がありました。そうした中で、確かに今、品川区、中学校までお配りになったということは、ほかから見ると非常に先進的にやられて評価はするんですけれども、小学生についても、ぜひ早急にこれは検討してもらいたいと思うんですけれども、いかがでしょうか。","respondent":"和氣学務課長","answer":"先ほど申し上げたような趣旨で配ってありますが、防災用の頭巾については、さっきの火災の問題とか、いろいろ対応もできますということで、総合的に研究させていただきたいと思ってあります。","voiceIndex":318,"id":"exchange-144"},{"speaker":"松澤委員","kind":"質問","question":"２点お聞きしたいと思います。１点目は、成果報告書には書いてありません。学級編制について。「お父さん、お父さん、小学校ね、３５人学級になったんだよ」と言われました。ちょっと中学校まではわからなかったので、どうも聞いてみると本当らしいと、学級が増えたところがあるというので、それについて、小学校、中学校、法律的にも含めてどういうことで学級編制が変わったのかについてお教えください。","respondent":"和氣学務課長","answer":"それ以外に、東京都のほうが、中一プロブレムへの対応ということで、中学校１年生に関しては３９人ということで学級編制をする、３９人で１名の教員をということでやってありますので、それが中学校でもクラスが増えたという例になります。","voiceIndex":321,"id":"exchange-145"},{"speaker":"松澤委員","kind":"質問・要望","question":"小学校は３５人学級を選択してもいいということで、そうすると、また今、２年生も予算要望している。聞いたところによると、２年生でも予算要望する前からもう２クラスになっているところもあるように聞いているんですけれども、これ、来年度はどうなるのでしょうか。１年生が２クラスに増えたところが、来年また、１年生はなるけれども、２年生になったらまた戻すのでしょうか。","respondent":"和氣学務課長","answer":"失礼いたしました。それから、来年度に関してですが、一応、今の文部科学省の概算要求の一番の要求が、２年生も３５人学級にするための教員の増員ということになってありますので、国としても３５人学級にするということで動いているというふうに認識しています。","voiceIndex":323,"id":"exchange-146"},{"speaker":"松澤委員","kind":"質問・要望","question":"ですから、私が言っているように、１年も２年も、そうすると、今、２年もするなら、３年になったらまた単学級に戻すんですかという話になります。これを見ていても、１０５人というと３学級、１０５人を超えると４学級、そんな学級が１年、２年、４年、５年とある学校もあるんですけれども、これをどう対応するのか、しっかりとしたお答えをいただきたいと思います。","respondent":"和氣学務課長","answer":"ということで、私ども学務課、庶務課、指導課、３課で常に数を検討しながら、実際にシミュレーションをして、教室が足りるか足りないか、そのためにどう対応すればいいか、今のあき教室をどのように改造していくかとか、人口推計自体も、実はだんだん増えていって。","voiceIndex":325,"id":"exchange-147"},{"speaker":"松澤委員","kind":"質問","question":"そうしたら、その話は教育委員会の中ではもうしっかり事前に打ち合わせができているんだなというふうに感じたんですけれども、やはりそうすると、一般の学校でも、どこでも選択できますよという中で、超えそうなところはそれとなく学区以外のところから来ないでくださいとか、そういうふうな形で指導していくようになるのだろうというふうに思うんですけれども、その辺はしっかりと言えないですか。","respondent":"和氣学務課長","answer":"もう１つは、１つやったのは、昨年の品川学園、城南第二小学校、非常に増えていますので、品川学園の順位に上げたというのが１つ対策は講じてありますが、そういうことも考えながら、基本的に子どもたちに混乱をもたらさないように。","voiceIndex":327,"id":"exchange-148"},{"speaker":"松澤委員","kind":"質問・要望","question":"本当に今、学校にばらつきがあって、１学級２０人いない学級も、単学級の学校もありますので、その辺しっかりと教育の中で、学校の特色を出して選択できるような形にしていただきたいと思います。どうして書いていないのか。スチューデント・シティとファイナンス・パークの役割と、そして子どもたちにとってどのような役に立っているのかについて教えていただきたいと思います。","respondent":"冠木指導課長","answer":"平成２２年の決算書に載っていないのは、この年、八潮学園、それから城南中学校から品川学園のほうに引っ越しを、移動の事業をして、この年は子どもたち、ちょっと行けませんでしたので、それはまた今年から再開しましたので、そんな形で対応しています。","voiceIndex":329,"id":"exchange-149"},{"speaker":"松澤委員","kind":"質問","question":"大変失礼しました。子どもたちがこれに通う曜日というものは、どういう日を選んでやっているんでしょうか。普通の授業時間内にやっているのか、あるいは土曜日、日曜日も含めてやっているのか、その辺をお聞きしたいと思います。","respondent":"冠木指導課長","answer":"その前に学校で勉強を８時間ほどいたしまして、それで実際に品川学園のスチューデント・シティで６時間かけて授業をしまして、学校に戻ってまた振り返りの学習を１時間するという計画になってあります。","voiceIndex":331,"id":"exchange-150"},{"speaker":"松澤委員","kind":"質問","question":"こんなこともやはり学校が地域に開かれた、地域と一体となったきずなを深めるなんていう合い言葉ではないんですけれども、あるんですから、しっかりその辺も見てやってほしいと思うんです。その選び方について、当然、教育委員会ではわからないと思いますけれども、この辺、学校との連携はどのような話し合いをしているのかについて、１点お伺いしたいと思います。","respondent":"冠木指導課長","answer":"スチューデント・シティ、ファイナンス・パークの日程については、私どものほうから学校のほうに予定をお知らせする中で、学校のほうの希望も聞いて調整をしていますけれども、先ほど、引っ越しということがございました関係で。","voiceIndex":333,"id":"exchange-151"},{"speaker":"須貝委員","kind":"質問","question":"私は、教育指導費と教育費全般についてお伺いしたいと思います。品川区、公立中学校の中学３年生の進学実績についてお伺いいたします。教育委員会では、偏差値の高い都立高校や私立高校の進学校への進学実績が上がったという成果を言われているようですが、これは事実でしょうか。","respondent":"冠木指導課長","answer":"そういった子どもたちそれぞれの将来設計であるとか考え方、そういうようなところも含めまして進路指導していますので、そういった意味では、子どもたちの考えがより深まって進学をしている子どもたちは確実に増えております。","voiceIndex":337,"id":"exchange-152"},{"speaker":"須貝委員","kind":"質問","question":"中学３年生になると、その実態は本当に顕著にあらわれて増えております。学校の勉強だけでは不十分であり、到底私立や都立の進学校を受験する力が身につかないというお話を私はよくお聞きします。特に学力レベルが高い進学校へ行くには、高いレベルの教育をしている民間の塾で学ばなければ合格できないのが現状だと思いますが、この辺について何か見解をお聞かせください。","respondent":"冠木指導課長","answer":"しかしながら、品川区が今取り組んでいる教育によって、先ほども経済の学習であるとか、そういったところも出てまいりましたけれども、そういったことで、子どもたちがきちっと将来設計を描けるようになっている。","voiceIndex":339,"id":"exchange-153"},{"speaker":"須貝委員","kind":"質問","question":"中学３年生になると、大半の生徒が私立高校か都立高校を一般入試である受験をします。ですが、高レベルの問題は、品川区の公立中学校では教えていない問題が出題されています。ならば、受験する子どもたち、公立中学校でも公教育を塾が支えるということではなく、民間の塾と同様に、受験対策の勉強を教えるべきではないんですか。その辺についてご見解をお聞かせください。","respondent":"冠木指導課長","answer":"これについては、当然、私どもと同じ仕事をしている指導主事が十分に学習指導要領にのっとった問題であるかというのを確認している問題ですので、今委員のご指摘になったような事実はございません。確実に子どもたちに中学校で教えている中から出題がされているです。","voiceIndex":341,"id":"exchange-154"},{"speaker":"須貝委員","kind":"質問","question":"今、そういうふうにおっしゃいましたが、現実、私もいろいろな受験生にヒアリングさせていただきました。はっきり皆さん、こう言っていました。できませんと。ちょっとその辺。要は、習った問題が出ているということを、そうやって簡単に言うということは、ちっともそれを見ていないということではないですか。もしそれができるなら、もっと多くの子が受験して合格できてしまうんじゃないですか。違いますか。","respondent":"冠木指導課長","answer":"私が責任を持って、当時の各学校の試験問題については確認をしています。ですので、切り口は違います。ですから、ふだんの学習、基礎のトレーニングだけで解けるかといえば、それは選抜試験の一環がありますから、解けないという、難しいと思われるお子さんもいるかもしれません。","voiceIndex":343,"id":"exchange-155"},{"speaker":"須貝委員","kind":"質問・要望","question":"ちょっと見解が違うので、本来なら、もっと私は、指導課長、もっと子どもたちと向き合ってほしいと思います。でも、現実は、やはり一般入試ではほとんどいません。それが実情だと思います。それについてちょっとご意見を聞かせていただきたいのと、また、民間塾は進学指導をする資料をきちっと持っております。今の教員は、何を根拠に進学指導するんですか。それについてちょっとご見解をお聞かせください。","respondent":"冠木指導課長","answer":"だから、子どもたちは宝なのであります。ですから、そういった意味で、中学校の教員は全力を挙げて進路指導しておりますので、塾について私はコメントする立場にありませんけれども、それはご家庭の判断ですけれども、学校の教育は十分に機能しています。","voiceIndex":345,"id":"exchange-156"},{"speaker":"須貝委員","kind":"質問・要望","question":"何度も申し上げますけれども、そういうことをいつまで言っていたら、本当の子どもたちの教育の実態を見ていないじゃないですか。見られないですよ。いつまでもそうやってきれいごとを言ってどうするんですか。そういう子どもたちが上げているというのが事実じゃないですか。学力をつけさせることが先じゃないですか。そして、学力がついていなかったら、結局、就職できないじゃないですか。","respondent":"冠木指導課長","answer":"他区に負けない、他区以上の区の非常勤講師であるとか、習熟度別学習コースであるとか、学習支援のボランティアであるとか、そういうようなところを各学校に配置しまして、少人数の指導展開をして、そういった子どもたちについても十分に対応しています。","voiceIndex":347,"id":"exchange-157"},{"speaker":"須貝委員","kind":"質問","question":"みんな子どもたちは、できれば学力をつけて、授業も楽しくやりたいと思っていると思います。見回ってみたら、やっぱり解けない子もいます。今はどうですか、立たすこともできない、座らすこともできない、強く怒ってもいけない、こんな状態で学力が子どもたちがちゃんとつくんですか。そして中３になったら、いや、全然解けません。やっぱりきちんと競争社会と向き合うべきじゃないでしょうか。","respondent":"冠木指導課長","answer":"いろいろとご意見をいただきましたけれども、競争社会と向き合っていくということについては、私もその考えは１つあるかなと思います。","voiceIndex":349,"id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"今、実際、ご夫婦共稼ぎ、皆さん大変なんですよ。地域でもその子たちの悪い行動とかがあったら注意もします。もし何だったら、極秘でも、極秘ではできないのだろうけれども、１回模擬テストをやってみてくださいよ。なんでその本当の力を、皆さんの実力というものを１回把握しようとしないんですか。なぜですか。怖くて出せないのかわからないですけれども、それをしっかり申し上げて終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":351,"id":"exchange-159"},{"speaker":"南委員","kind":"質問","question":"１７１ページの保幼少連携推進経費に関してお尋ねしたいと思います。保幼少連携事業の目的、どのような内容で実践しているのか、参加状況、事務事業概要には「希望するところ」となっておりますけれども、参加状況がどうなっているのかについても伺います。","respondent":"冠木指導課長、吉岡保育課長","answer":"この事業につきましては、私どもが保育課と共同でつくりましたジョイント期のカリキュラム、これをぜひ品川区内の公立の、幼稚園は教育委員会の部分もありますけれども、あと保育園、それから私立の保育園、幼稚園にもご協力いただいて。保幼少交流事業の実績ですけれども、平成１９年度にモデル実施を始めまして、翌年度からは全区立保育園、幼稚園、それから小学校で実施しているところですので、それぞれの学校、幼稚園、保育園、交流をしていますので。","voiceIndex":353,"id":"exchange-160"},{"speaker":"南委員","kind":"確認","question":"そうすると、「希望するところ」というふうにはなっているものの、すべての公私立保育園、すべての公私立幼稚園、そして小学校ということで考えていいということですね。ちょっとそこを確認したいと思います。それから、それぞれの担当者が事前準備をしないとこれはできないというふうに思うんですけれども、その事前準備についてはどういうふうになっているのかについても教えてください。","respondent":"吉岡保育課長","answer":"基本的に今申し上げましたように、公立の幼稚園、保育園については、全園がそれぞれの小学校と交流をしていますので、平成２２年度の実績としては、公立の保育園は４０園、それから公立の幼稚園は９園ということで実施しています。","voiceIndex":356,"id":"exchange-161"},{"speaker":"南委員","kind":"質問","question":"地域の取り組みにちょっと話を伺ったので紹介したいと思います。一貫校と４つの公私立の保育園、１つの公立幼稚園、ですから、就学前の施設は５園、あと一貫校、小学校部分だと思います。したがって、こういう実態があるということをどこまで承知をして教育委員会サイドも、それから子育て支援課サイドも、どこまでつかんでこの事業を推進しているのかということについて伺いたいと思います。","respondent":"吉岡保育課長","answer":"今、委員がおっしゃられた事例が、どの学校あるいは保育園、幼稚園で、いつ起きた事例かは承知しませんけれども、一つ一つの事業を実施するに当たっては、小学校側の教員、それから保育園側の保育士、幼稚園の幼稚園教諭、それぞれが事前に十分な打ち合わせをし。","voiceIndex":358,"id":"exchange-162"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、連携推進ということで、そういう保育園の中で全面的な発達を求めてきた、そういう営みがこういうことで途切れさせてしまってはならないという心配をするわけで、私はですから、この時間と子どもたちの思いを、やっぱり期待を裏切ってしまうような、そういう場面があちこちあるのであれば、やっぱりやる必要はない、こういうふうに思いますけれども、保育園や幼稚園の中での指導員の。","respondent":"吉岡保育課長","answer":"さまざまなお話ございましたけれども、調査をしろというお話もありましたが、そもそも、そうすると、委員は、これをどういうふうにお知りになって、どういうふうに実態を把握されたのかということが私はよくわかりませんけれども、基本的には、何回も申し上げているように。","voiceIndex":360,"id":"exchange-163"},{"speaker":"南委員","kind":"質問・要望","question":"私は、やっぱり６年生のお兄さんやお姉さんが、小さな子どもに対してはきちんとした成功する、そういう場面を提供できることが大事だと思うんです。就学前の子どもにとっても、そういう姿を見て、期待やあこがれが広がっていくと思うんです。もっと一人一人の年齢に合ったやり方、そこをしっかり保育園でやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":362,"id":"exchange-164"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほど、会派の向委員から、帰国児童生徒等適応指導費で、ＩＷＣの実績を評価して、さらに推進してほしいという要望がありましたけれども、これについて、私もそのことについて適正な運営費をということで、一昨年はアップしていたと思うんですけれども、今回の決算書では、前年度よりも５００万円ほど決算額が減少しているので、その理由をお伺いしたいと思います。","respondent":"和氣学務課長、冠木指導課長","answer":"日光光林荘の放射能ですが、私みずからはかってまいりました。日光と同等の数字が確認できました。ＩＷＣの適応の経費ですけれども、一昨年につきましては、対象のお子さんの数が通常の１.５倍おられまして、急遽その対応をしたということで、その前の年の決算は、少し数字的には高くなってあります。","voiceIndex":364,"id":"exchange-165"},{"speaker":"井上委員","kind":"質問・要望","question":"わかりました。すまいるスクールなんですが、専任指導員は、今、各学校１名正規職員があると思いますが、職員の資格と平均年齢を伺います。生ごみのところでは、学校給食の廃食油リサイクル、現在どのように行っているのかお伺いします。図書館経費では、図書館で図書司書の配置をされているのは、１０館のうち何館あるのか教えてください。","respondent":"齋藤庶務課長、和氣学務課長、中元品川図書館長","answer":"すまいるの正規職員の平均年齢ですが、今年の４月１日現在で５２.６歳になります。全部で４０人いる中、５２.６歳です。廃油についてのお尋ねにお答えいたします。ただし、委託職員の中に何割か司書の者がおりまして、こちらで特に司書資格を求めているわけではございませんが、現在。","voiceIndex":367,"id":"exchange-166"},{"speaker":"井上委員","kind":"質問・要望","question":"図書館のところは、３割程度ということで、私が伺ったのは、１０館中何館に図書館司書が配置されているのかということでしたので、明確にお答えをいただきたいと思います。","respondent":"中元品川図書館長、和氣学務課長、齋藤庶務課長","answer":"失礼いたしました。正規職員の２人の司書については、品川図書館に配置があります。せっけんの件は、前にもご質問ありましたので存じ上げてありますが、今のこの廃油については、しっかりとリサイクルされてありますので。これは人事施策の問題ではありますけれども、平成２０年の本会議で、すまいるスクールの正規職員は、事業運営の要であり、学校と地域との調整役だと。","voiceIndex":371,"id":"exchange-167"},{"speaker":"井上委員","kind":"質問・要望","question":"図書館なんですけれども、１０館に必ず１人がいるということで安心しましたけれども、ここのところはしっかりと継続していただきたいし、あと、図書館でレファレンス業務や、いろいろな企画で地域の生涯学習の拠点になっていただきたいというふうに思いますので、そういったところでこれから工夫をされていこうと思うことがあったら教えてください。","respondent":"和氣学務課長、中元品川図書館長","answer":"先ほどと繰り返しになってしまいますが、基本的に私どもは今の方式で十分リサイクルはできておりますし、その中で子どもたちにもリサイクルの教育をしていますので、そういうお考えもございましょうが。ただ、その中で品川図書館本館には視聴覚ホールなどありますので、そちらで地域の方向けの講演会を無料で実施したり、映画会を実施したりということで、今後も引き続き努力してまいりたいと思ってあります。","voiceIndex":375,"id":"exchange-168"},{"speaker":"井上委員","kind":"質問","question":"図書館なんですけれども、今、子どもたちが遊べるスペース、本が読めるスペースを確保していただいているのはよくわかるんですけれども、そこが場所的な面積の関係で、そこはあっても迷惑がかかるということで、なかなか利用ができないという中で、杉並区では時間を分けて使うというようなこともやっていますが、そういったことの検討はいかがでしょうか。","respondent":"中元品川図書館長","answer":"今委員おっしゃったのは、杉並区で始められたあかちゃんタイムのことかと存じておりますが、こちらも検討してまいりたいと思います。","voiceIndex":378,"id":"exchange-169"},{"speaker":"若林委員","kind":"質問・要望","question":"１６９ページの品川区教育会助成金、これは私、あまり存じませんので、この教育会とはどういう団体なのか、あと、助成金の内容なんかもお聞かせいただきたいと思います。それからあわせて、見比べますと、予算に対していわゆる５７％の執行にとどまったということですので、その内容とともに、この原因も教えていただきたいと思います。それから、１７１ページの特別支援教育費です。","respondent":"冠木指導課長","answer":"サポート経費のほうは、巡回相談ということで各学校を回らせていただいて対応させていただいて、気になるお子さんについて確認させていただいているんですが、そこのスタッフの医師が減ったということで、額のほうは下がったです。","voiceIndex":381,"id":"exchange-170"},{"speaker":"若林委員","kind":"質問・要望","question":"教育会の詳しい話はちょっと聞けませんけれども、同額を補助するということは、会員の会費が例えば１００万円になったら１００万円を補助する、２００万円になったら２００万円を補助するということでどんどん膨らんでいく、また逆に減っていくという。それを確認します。特にこの教員のスキルアップについて、平成２２年度等どのようなことをされているかお聞きしたいと思います。","respondent":"冠木指導課長","answer":"ＮＰＯと委託の契約を交わす中で、介助員もいるんですけれども、学習支援員の研修、これについても充実をするようにということで、私どもと委託の前に調整して対応しているところでございまして、そういった事例については幾つか私ども知っておりますけれども。","voiceIndex":383,"id":"exchange-171"},{"speaker":"若林委員","kind":"質問・要望","question":"そうすると、先ほど、英語科のＡＬＴのお話でもありましたけれども、雇用形態の問題が１つ横たわっているのかなというふうに、さっきの質疑を聞いていて思ったんですが、ここら辺の改善について、ＡＬＴとともに、もしそういう事実があれば、学習支援員の雇用形態についても、またぜひそこの中で課題に取り上げていただきたいということの要望が１つと、あと。","respondent":"冠木指導課長","answer":"学習支援員の委託契約の問題につきましては、私どもも課題の１つととらえております。引き続き検討している部分です。それからもう１つのほうにつきましても、十分な対応をしてまいりたいというふうに思ってあります。","voiceIndex":385,"id":"exchange-172"},{"speaker":"須藤委員","kind":"質問","question":"ページ１６８の教育指導費に関連して質問しますが、その前に、今までの委員の質問の中からちょっと感じたことで再質問させてもらいますが、渡辺委員の質問のときに、品川区の教育は国より進んでいるんだというふうに自負をしていますというようなお話があったので、それは自負をすることはいいこと、自信を持つことはすばらしいと思うんだけれども。","respondent":"冠木指導課長、齋藤庶務課長","answer":"地域の皆様に混乱を与えてしまったという部分があることは事実ですので、ここは私どもも反省点として、それぞれの校長との共通理解というような部分でさらにこういった緊急対応について。先ほど、本多委員のお話は、校庭開放ではなくて、地域開放、一般開放の話だというふうに理解しましたのでご答弁は控えさせていただきましたけれども、先ほどの伊藤学園の例をはじめ、各学校が抱える問題については。","voiceIndex":388,"id":"exchange-173"},{"speaker":"須藤委員","kind":"質問","question":"改めて教育指導費のところで聞かせていただきますけれども、児童・生徒が教科に興味を持つということ、あるいは好奇心を持ってということが、その教科を好きになったりしていく、あるいは、その教科の向上をしてくるということにつながってくると思うんだけれども、いかがでしょうか。","respondent":"冠木指導課長","answer":"子どもたちがまずその教科に興味関心を持って、それに意欲を持って取り組んでいくという姿は教育の中で一番望ましい姿であって、さらにその後、子どもたちが伸びていく原動力になるということは間違いないと思います。","voiceIndex":391,"id":"exchange-174"},{"speaker":"須藤委員","kind":"質問","question":"最近、金魚とドジョウの詩で有名になった詩人の詩に、「負ける練習」という詩があるんですけれども、ご存じでしょうか。","respondent":"冠木指導課長","answer":"勉強不足で存じ上げておりません。","voiceIndex":393,"id":"exchange-175"},{"speaker":"須藤委員","kind":"質問","question":"先ほど来、武道ということで、礼法をという話ですけれども、投げられて受け身をとってぶざまな格好を見せるということが、年間１０時間の間でどの程度続くのかなと。そして、それを拙速的にやると、事故につながったりというようなことが出てきてしまうので、非常にそのあたりが難しいと思うんですけれども、授業でやったことと、今度、部活につなげるという考え方はいかがでしょうか。","respondent":"冠木指導課長","answer":"武道の礼に始まって礼に終わるという考え方を十分に理解していただいた上で、子どもたちが興味関心を持って競技の部活につないでいく、競技活動につながっていくということは、望ましい姿の１つであろうかなというふうには思います。","voiceIndex":395,"id":"exchange-176"},{"speaker":"須藤委員","kind":"質問","question":"今の例で出てきたんですけれども、学校の中で、「気をつけ、礼」という、気をつけの姿勢というのは教えているのでしょうか。","respondent":"冠木指導課長","answer":"教えております。４月の初めの体育の時間、あるいは４月の初めの学年集会等々で、「気をつけ、礼」については、「回れ右」も含めまして指導しています。","voiceIndex":397,"id":"exchange-177"},{"speaker":"須藤委員","kind":"質問","question":"学校の卒業式なんかに行って、来賓のほうへ向かって礼をするときも、足を開いて礼をしている。やはり礼というのは見ていてきれいでなければいけないので、足を開いて礼をされると、何となく違和感が出てきてしまう。そういったマナーと礼法と一緒になってしまって、礼をするときに足を開いたまま礼をしてしまうのではないかなというような気がするんだけれども、そのあたりはいかがでしょうか。","respondent":"冠木指導課長","answer":"マナーキッズのところでも、きちんとした礼ができるように指導しています。","voiceIndex":399,"id":"exchange-178"},{"speaker":"須藤委員","kind":"質問・要望","question":"だから、先ほどの詩人じゃないけれども、間違ってもいいんだよ、「にんげんだもの」という詩が出てきているんですけれども、私は教育委員会では、間違ってはいけないんだよ、教育委員会だものというふうに思っていますので、今の教育改革はすばらしいと思うんだけれども、間違ってはいけない、子どもたちが育っている９年間というのは、その前の未就学児を見ても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":401,"id":"exchange-179"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1350#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":117525,"voices":402}},{"id":"h23-20111017-4","meetingId":"h23-c-settlement","date":"2011年10月17日","dateIso":"2011-10-17","committee":"決算特別委員会","time":"午後６時１８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を137件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（秀）委員長","kind":"質問・要望","question":"本日の総括質疑は、ケーブルテレビ品川において、１０月２１日および１０月２３日に録画放映される予定です。質疑しているときは、後で映りますものですから、ぜひそれはご配慮願いたいと思います。申し合わせ確認事項を変更するということは、議会運営委員会に頼るということでありますけれども、理事会の中で話が出ましたので、最初からはしっかり、一問一答にならないようにしてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":1,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"私は、自民党を代表いたしまして、山内委員とともに決算特別委員会、総括質疑をします。はじめにまず、都市型観光の推進というテーマで伺ってまいります。そこではじめに、観光という中で、もてなすというキーワードもあるかと思います。その想定のもとに、現在、イベントが行われていたり、あるいは、日常の来訪者の現状を、どう把握されているのか伺います。","respondent":"中川原地域振興事業部長","answer":"ということで、今、ご質問にもありました、外国人、区外からの人、それから区民が、都市型観光の対象者となっているところです。イベント等の把握ですが、そういった意味で言いますと、外国人についてはまだ少のうありますけれども、区外、区民の参加者は多いと把握しています。","voiceIndex":2,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"意見","question":"そういう中で、人という点で聞いていきたいのですが、企業で、それぞれのご商売等の中で、お客様ニーズという言葉がありますが、そういう視点で考えたときに、日本政府の観光局の訪日外客消費動向調査２００９によると、日本を訪れたい理由の上位は、まず１位、日本の食事５８.５％、２位、ショッピング４８.５％、３位が温泉、以下、自然景観や伝統的な景観や旧跡を訪ねるとなっています。","respondent":"中川原地域振興事業部長","answer":"外国人は、特に体験を楽しまれておりまして、そのときに重要なことは、丁寧な説明でございました。食とかを体験するときに、どうしてこれがこの土地ゆかりのものなのか、大事なものなのかを丁寧に説明することで、満足度が非常に高まるということがわかったところです。","voiceIndex":4,"id":"exchange-003"},{"speaker":"渡辺委員","kind":"質問","question":"そこの点を踏まえて、今、観光全体の話も含めてなんですが、二通りあると思うんです。イベントで一極的に集中するやり方もあるし、日常、日々の取り組みという中で、観光施策を直接行う、あるいは支援する中で、日常のこと、そして、イベント等の集中型、それぞれどんな施策や支援を、現状で行っているか、考え方を伺えればと思います。","respondent":"中川原地域振興事業部長","answer":"都市型観光におけるイベントと、それから日常の取り組みについての、区としての考え方ですが、品川区は、この間、見てまいりますと、イベントがとても得意で、好きな土地柄があります。皆さん、とても上手にお祭りとかやられます。商店街のイベントもそうです。とても楽しいです。","voiceIndex":6,"id":"exchange-004"},{"speaker":"渡辺委員","kind":"確認","question":"ご答弁の中に、やはり高い意識を持って取り組まれていることを確認できたと思っています。次に、観光の観点という意味で、トイレについて伺いたいと思います。お客様が増える中で、トイレの問い合わせも増えているそうです。現にやっている部分もあるかと思いますが、使う人、あるいは提供する双方の方にひと手間かける、そんな工夫を、行政はどのように考えられているのか、伺いたいと思います。","respondent":"中川原地域振興事業部長","answer":"お願いしたところでも、使う側のモラルで、使い方が悪くて断られてしまう、いいと言ってくださったところが、継続して使わせてくださるのが、断られてしまって、いい例がなかなか見つからないというところもある地域がありますので、そういった意味で、区が間に入って。","voiceIndex":8,"id":"exchange-005"},{"speaker":"渡辺委員","kind":"質問・要望","question":"こちらのほうも、高い問題意識を持たれて取り組まれていると理解させていただきたいと思います。この魅力、そして水族館づくりとは、どんなことなのかということで、伺いたいと思います。現在の来場者数全体と、そのうちの区民利用者数の割合、また、当初の教育施設という政策目的に沿って、これまでもそうですし、現状で、区内の生徒・児童になるのでしょうか、来場状況を伺えればと思います。","respondent":"岩田都市環境事業部長","answer":"そのうち、区民割引を使って入館された方の数が１万７,６６５名、割合でいきますと、３.４％です。平成２２年度１年間における区内小中学校の利用状況ですけれども、３２校、１,８７２名の利用がございました。","voiceIndex":10,"id":"exchange-006"},{"speaker":"渡辺委員","kind":"確認","question":"今、魅力について、全体のお話をいただいたんですが、もう一度、伺いたいと思うことは、長期基本計画や総合実施計画の中で、平成２５年度までという中で、魅力という点と、水族館づくり、何かイメージ、節目があるかという中で、この決算特別委員会の中でもありましたので、その辺の確認を、再度、お願いできればと思います。この点を踏まえての評価を、どのようにされているのか伺いたいと思います。","respondent":"岩田都市環境事業部長","answer":"区の職員だけではなくて、さまざまな分野の専門家の方々にもいろいろご意見をいただきながら、現在、今後の進め方について、調整、検討している最中です。","voiceIndex":14,"id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"そういう中で、施設の規模や他の目的と合わせた複合化が必要であると思っています。あるいはリニアというのも、品川区にとっても、今後、何か大きなきっかけになるのではないかというような関連した施設だとか、そんなことを、いろいろまちでも議論があるところだと思いますので、すべて行政がやるとかではなくて、民間とどうつき合っていくかという複合化というテーマで、考え方を伺えればと思います。","respondent":"岩田都市環境事業部長","answer":"ご提案のありましたように、単に水族館のみではなくて、近くの鉄道の駅までの間のお店、あるいは、ショップ、こういったものもＰＲしながら、まち全体としてしながわ水族館が活力の中心になれるように、今後、いろいろ検討してまいります。","voiceIndex":16,"id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問・要望","question":"最後に、観光のテーマの中で、観光協会との連携で伺いたいと思います。そういうときに、施設があれば、あとは地元の商店等を活用すれば、いろいろな波及効果が生まれるのではないかという思いがあります。区内宿泊への仕掛けという点で伺えればと思います。そういう意味で、区民が旅行へ行くマネージメントを、区として、どうお考えか、この２点、お知らせください。","respondent":"中川原地域振興事業部長","answer":"観光協会を中心とする区内宿泊の仕掛けなんですけれども、まず、観光協会ですが、この役割は、地域の活性化につながる段取りや仕掛けを実施することがとても大事だと思っています。","voiceIndex":18,"id":"exchange-009"},{"speaker":"渡辺委員","kind":"提案","question":"協働推進のテーマで伺います。区政運営の基本姿勢において、協働と言われますが、どのような考えやイメージでしょうか。どんな取り組みをしているのか、その具体策として、協働事業提案制度、あるいは区民活動支援事業があるかと思いますが、まだ立ち上げて間もない中で、主な採用事業、それから、支援の期間はどうなっているのか、お教えください。","respondent":"中川原地域振興事業部長","answer":"そういった中で、区民にアイデアを出していただいて、こういう活動をしたら、まちがよくなるのではないかという提案をいただいた区民活動助成事業なんですけれども、どんな事業に助成をしたかといいますと、町会と連携しまして。","voiceIndex":20,"id":"exchange-010"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今、最後に期間の話がありましたが、１年ということが、地域要望の中でよくあります。きっかけをつくった後、必要性がある場合、継続もあるのですが、協働の視点から言うと、最初の立ち上げに力が置かれるわけで、その後、いい事業で支援すべきとなった場合に、役所内の所管が出てくると思います。そことの連携、あるいは、継続性という視点で、もう１点伺いたいと思います。","respondent":"中川原地域振興事業部長","answer":"いろいろなイベントに行きましてお願いするんですが、まだ寄附についてわかりにくい部分があると思いますので、今後、寄附のあり方につきましても、地域振興基金というふうに束ねてのやり方が今の方法ですが、こういった事業に使わせていただきますとか、そういった意味で。","voiceIndex":24,"id":"exchange-011"},{"speaker":"渡辺委員","kind":"質問","question":"最後、全体の話になりますが、今、それぞれ大きな問題意識もありますし、ぜひともお願いしたいのは、いろいろな政策課題というのは、どうしても、課題に対処するというものが、行政サービスの中で多いかと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-012"},{"speaker":"山内委員","kind":"質問","question":"都区のあり方と検討会について、伺います。濱野区長は、２３区の区長会の副会長として、都区のあり方において、我々の意のあるところをしっかりとくみ取っていただきまして、日ごろ、並々ならぬ思いで取り組んでいただいていることには、感謝をいたします。そこで、まず、これまでの都区のあり方の成果を伺いたいと思いますけれども、よろしくお願いいたしたいと思います。","respondent":"濱野区長","answer":"都区のあり方検討会、たしか平成１９年１月に第１回が持たれまして、まだ終わったわけではないのですけれども、今年の１月１９日、これがたしか２８回目の幹事会だったと思います。","voiceIndex":28,"id":"exchange-013"},{"speaker":"山内委員","kind":"質問・要望","question":"数的なこともありました。先ほどもお話がございました、４４４項目のうち、区側に移管することで大筋決まった５３項目、しかしながら、その後の検討会が開かれない、これはどうしてなのかといった疑問があります。それから、もしよろしければ、検討項目で挙がった４４４項目と、大筋で移管と決まった５３項目の経緯も、もしわかれば教えていただきたいと思います。","respondent":"濱野区長","answer":"その後、今度は３月１１日の大震災がありまして、これの被災地支援の仕事が総務局所管ということでありますので、このあり方検討会の所管でもある総務局が、どうしてもこちらのほうに力をかけなければならないということがあって、あり方検討会については。","voiceIndex":30,"id":"exchange-014"},{"speaker":"山内委員","kind":"意見","question":"実は、私のほうから、この後、都区のあり方について考えると、といった形で、３項目挙げさせていただこうかと考えています。今、区長からも若干答弁をいただきましたけれども、あり方を考えますと、まず第１に、区域の再編といったことを考えたときの５０万人といった基準を、まず軸に置いて考えなければならない。そのあたりに、少し隔たりがあるのかなという思いをいたしております。","respondent":"濱野区長","answer":"区側として、どうしようかということで、今、いろいろ議論をしておりますけれども、私自身といたしましては、少なくとも１月１９日の幹事会で、幹事会というのは、東京都も総務局長以下、それぞれの主要なポストの人間が出ているわけでありますから、そこの場で確認したことは。","voiceIndex":32,"id":"exchange-015"},{"speaker":"山内委員","kind":"質問・要望","question":"区長の答弁を伺っておりますと、非常に困難なところもあるのかなという気もいたしております。今後について、２３区と東京都とのお話をいろいろ伺っていますと、関係は一体大丈夫なのか、どうなのかという思いもしているんです。そういう隔たりもあるといった部分もありまして、改めて、東京都と区側の関係といったものをどのように考えていらっしゃるのか、そのあたりを伺いたいと思います。","respondent":"濱野区長","answer":"実は、先週の金曜日でありますけれども、区長会の正副で総務局長のところに行きまして、先ほどのあり方検討会の進捗と、児童相談所のこれからの検討の仕方について、精力的に進めてほしいということを訴えたところです。","voiceIndex":34,"id":"exchange-016"},{"speaker":"山内委員","kind":"質問・要望","question":"今後のあり方検討会の再開を考えますと、区長会からしっかりと要望していくといったことと、それに加えて、都議会といったところとの連携も、しっかりと重視をしていきながら、巻き込んで、検討会の再開といったことを要望していくということも、非常に重要なのかなと思いますけれども、最後に、そのあたりをお伺いさせていただきたいと思います。","respondent":"濱野区長","answer":"都区のあり方検討会が立ち上げられたそもそもの経緯でありますけれども、高橋前区長が、主要５課題の解決という仕事に、ほんとうに命懸けで取り組んだわけであります。","voiceIndex":36,"id":"exchange-017"},{"speaker":"山内委員","kind":"質問","question":"区長ともども、我々各議員がしっかりと意識を高めて臨んでいきたいと考えていますので、どうぞよろしくお願い申し上げます。続きまして、有価証券に関することについて、お伺いします。最初に、有価証券を保有することのメリット、そして、今後の有価証券の保有については、どのようにお考えなのかお伺いします。","respondent":"日下部企画部長","answer":"今後の考え方ですが、今もちょっと申し上げたのが、区の施策の推進、ひいては公益目的の実現ということになるわけですので、こういった考え方を基本として対応をしてまいりたいと考えているところです。","voiceIndex":38,"id":"exchange-018"},{"speaker":"山内委員","kind":"質問","question":"わかりました。金額では７億１００万円、非常勤取締役には、日下部企画部長が就いていると伺っております。現在、筆頭株主の品川区は、区民に対して、ケーブルテレビ品川の加入の促進をしていると思いますけれども、今回、このような事態が発覚したことで、品川区に筆頭株主といった意識はあるのかということを、ちょっと、私は懸念をいたしましたけれども、そのあたりについてお伺いしたいと思います。","respondent":"日下部企画部長","answer":"今後、ご指摘にありますような、株主としての意識というものをしっかり持って対応していくことが重要ではないかと認識しています。","voiceIndex":40,"id":"exchange-019"},{"speaker":"山内委員","kind":"質問","question":"もう一つ、東京臨海高速鉄道について、ちょっと伺いますけれども、保有率が１.８％と低いのですけれども、金額は２２億円と、品川区が投資している５社のうちでは断トツの金額であります。そこで、株主の品川区の臨海高速鉄道に対する影響力の誇示という点で、伺います。そこで、まず、改めて、ホームドアの設置の考えと、大井町線の大井町駅がなぜ選ばれたのかといった経緯をお伺いしたいと思います。","respondent":"片田防災まちづくり事業部長","answer":"そういう中で、国のほうも、今年２月ぐらいでしょうか、検討委員会を立ち上げてきたということで、たしか現在の時点では、中間のまとめということで、ホームドアについても、１日の乗降客が１０万人を超えるようなところについては。","voiceIndex":42,"id":"exchange-020"},{"speaker":"山内委員","kind":"質問・要望","question":"今、バリアフリー法の改善、１０万人以上の駅が対象といったことで、お話がありました。であるのならば、同じ大井町駅で考えるならば、ＪＲもありますし、そして、東京臨海高速鉄道が走っております。もし起こしていないのであれば、そういった考えは、今後こういったときに、どのように考えられるかといったところを、お伺いしたいと思います。","respondent":"片田防災まちづくり事業部長","answer":"したがいまして、私どものほうとしても、国の動向、中間のまとめを踏まえて、国、あるいは東京都が、そういう制度をきちっと制定する、そのうえで、区としてもそういう働きかけを含めて、ホームドアの設置を拡大していくといったような考え方で進めていきたいと考えています。","voiceIndex":44,"id":"exchange-021"},{"speaker":"山内委員","kind":"質問","question":"そこで、安全対策の今後の整備の不可欠といったことで、早期のホームドア設置、今、大井町駅を含めて、品川シーサイド駅、天王洲アイル駅、大崎駅と４駅ありますけれども、その辺は、株主として、品川区から臨海高速鉄道に働きかけをするといった考えは、今後どのように、タイムスケジュール的にあるのかどうか、そのあたりを伺いたいと思います。","respondent":"片田防災まちづくり事業部長","answer":"本間副区長も、非常勤の取締役というような立場をとっております中で、私どもも、そういう対応を含めながらきちっと鉄道事業者のほうにもお話をしていく、それから、国、あるいは東京都のそういう制度を十分に見極めながら、適正にそういう働きかけを含めて。","voiceIndex":46,"id":"exchange-022"},{"speaker":"山内委員","kind":"質問・要望","question":"本間副区長、よろしくお願いします。今後の影響力といったことへのさらなる誇示を、私は求めますし、また、最初に述べましたケーブルのことに関しましても、やはり株主といった意味での意識の向上といったことを、品川区の皆様に求めてまいりたいと思います。最後にそのあたりのご答弁をいただいて、私のほうからの質疑を、これにて終了させていただきたいと思います。","respondent":"日下部企画部長","answer":"あわせまして、株主ということで、事業運営に対しましても、一定の責任を持つという立場にもありますので、株主としての意識向上というご指摘がありました。しっかりと自覚を持って対応できるように努力をしていきたいと思います。","voiceIndex":48,"id":"exchange-023"},{"speaker":"金野委員","kind":"提案","question":"１点目の質問は、高齢者福祉について、お聞きいたします。先日、土木費の款別質問において、我が会派の鶴委員より、西中延区営住宅へのエレベータ設置を要望し、耐震補強工事の必要性とあわせ、区営住宅が複合施設として建て替えられるならば、現在、お住まいの方のさまざまな問題も解決するのではないかと提案いたしました。そこで改めてお尋ねいたします。","respondent":"日下部企画部長","answer":"ただしかし、いろいろな諸状況も勘案いたしまして、これはもう一日も早く速やかに検討を進める、このようなところで考えてあります。","voiceIndex":51,"id":"exchange-024"},{"speaker":"金野委員","kind":"質問・要望","question":"その間の安全性の確保が危惧されますが、どのようにお考えでしょうか。検討にあたっては、現在お住まいの方が、新しい複合施設になっても、漏れなく入居できるよう要望いたします。そのうえで、区民の命を守るため、また入所を待ち望む区民のためにも一日も早い特別養護老人ホームの建設を要望いたします。それぞれご見解をお伺いいたします。","respondent":"日下部企画部長","answer":"これはやっぱり、しっかりとした検討、設計を進め、しっかりとした工事を進めていくということで、どうしても一定の日数はかかりますが、先ほども申し上げましたが、できるだけ早く具体的な方向性を整理いたしまして。","voiceIndex":53,"id":"exchange-025"},{"speaker":"金野委員","kind":"質問","question":"ぜひ、よろしくお願いいたします。次に、高齢者の見守りについて、お聞きいたします。本年１０月からは、荏原第二地域センター管内において、支え愛・ほっとステーション事業がスタートしています。それぞれの事業内容と、実施状況はいかがでしょうか。そのうえで、二つの事業の今後の方向性についてもお聞かせください。","respondent":"木下健康福祉事業部長","answer":"しかしながら、先ほど申し上げた制度上の隘路がありますので、この部分については、私どもとしては、引き続き検討していきたいと考えているところです。","voiceIndex":55,"id":"exchange-026"},{"speaker":"金野委員","kind":"質問・要望","question":"その制度の整合性を保ちながら、今後に移行していくということも考えていく、できる限り、一日も早くこの事業を全区展開していくためにも、その整合性を持っていただきたい、このようにも思いますが、ご見解をお聞かせいただきたいと思います。款別審査でも要望いたしました、荏原第二地域センターの事業との整合性を図る意味でも、緊急通報システムの対象要件の緩和を再度要望いたします。","respondent":"木下健康福祉事業部長","answer":"その場合には、対象にならないということが出てきております。そのほか、介護保険の地域支援事業の対象に入れることも可能かと思いますが、ここにもやはり、若干検討を要する課題があるということでありまして、この辺の整理が必要だと考えているところです。","voiceIndex":57,"id":"exchange-027"},{"speaker":"金野委員","kind":"質問・要望","question":"続きまして、２点目の質問にまいります。次は、女性の視点からの防災対策について、お伺いいたします。このたび、地域防災計画改訂の時期にあたり、今回の東日本大震災で学んだ多くの教訓や、過去の大震災の教訓を踏まえ、今後、さらに災害に強いまち品川を構築していくよう求め、以下、質問をしてまいります。はじめに、本区における防災行政の現状について、お聞きいたします。そこで、お尋ねいたします。","respondent":"片田防災まちづくり事業部長","answer":"ただ、現在、防災計画を策定するにあたって、震災対策特別委員会等の中でも、それぞれご議論いただいて、６名の女性委員も入っていらっしゃるということも含めて、いろいろな機会をとらえた中で、私どもとしても。","voiceIndex":59,"id":"exchange-028"},{"speaker":"金野委員","kind":"質問・要望","question":"品川区の防災行政の状況は、わかりました。そこでお尋ねいたします。現在、本区の地域防災計画は、明年夏をめどに見直し作業が行われていますが、先ほど指摘した課題も含めて、新しい計画にどのように反映させていくのか、お伺いいたします。計画策定の過程で、女性の視点が反映できる仕組みづくりの構築と、女性の視点に立った地域防災計画の策定を強く要望いたします。それぞれのご見解をお伺いいたします。","respondent":"片田防災まちづくり事業部長","answer":"そういう中で、今、進め方の中では、早急にできる課題については行ったうえで、例えば帰宅困難者問題とか、あるいは、避難所の問題とか、そういう幾つかのジャンルに分けて、それぞれ庁内の検討会を含めて検討していきたいということを考えてあります。","voiceIndex":61,"id":"exchange-029"},{"speaker":"金野委員","kind":"質問","question":"ジャンルに分けて、それぞれ女性の視点を入れていくというご答弁をいただきました。続きまして３点目の質問にまいります。大井町駅周辺のまちづくりについて、お聞きいたします。そこで、お尋ねしたいことは、大井町駅周辺地区の現況と課題についてです。この構想を策定するにあたり、駅周辺地区の現況や課題の認識、また、まちづくりの基本的な考え方と方向性を、それぞれお答えください。","respondent":"片田防災まちづくり事業部長","answer":"こういう状況を踏まえて、それぞれのまちづくりの方向性ということを考えた場合、りんかい線ができても、乗りかえではまずいので、やはりおりていただいて、品川区を楽しんでいただくといったような考え方で、回遊性を重視したまちづくり。","voiceIndex":63,"id":"exchange-030"},{"speaker":"金野委員","kind":"質問","question":"より具体的にエリアを限定してお聞きしていきたいと思います。大井町駅周辺地区南側のまちづくりについて、お聞きいたします。地区の回遊性を高めるという、この回遊性、それから放射・環状の歩行者ネットワークの形成、これは、具体的にどのようなことをお考えなのでしょうか。この大井町駅南側の整備について、どのようにお考えなのか、それぞれご見解をお聞かせください。","respondent":"片田防災まちづくり事業部長","answer":"区内全体としては、現在、進めているマスタープランとの連動性、そういうものを考えながら、マスタープランの中で位置づけ、なおかつ、その具体的な個別施策の中で、大井町のまちづくりをどうするかという構想の中での位置づけを考えている中で、具体的なところは、現時点で。","voiceIndex":65,"id":"exchange-031"},{"speaker":"金野委員","kind":"質問・要望","question":"このような危険を回避するためには、安全で、便利な歩道橋にするための改善をほどこして、利用しやすいようにすることが重要と考えますが、本区のご所見をお聞きいたしたいと思います。歩道橋の改善には、高齢者や障害者、妊産婦など、安全に渡ることができるように、エレベータの設置も要望したいと思います。あわせて、ご見解をお聞かせください。","respondent":"片田防災まちづくり事業部長","answer":"その中でエレベータの設置ということも含めた中で検討をかけていきたいと考えていますけれども、現在、そういう構想の策定を含めて、民間の動向を十分に注視しながら、タイミングを図りながらということを考えていきたいと思っています。","voiceIndex":67,"id":"exchange-032"},{"speaker":"金野委員","kind":"提案","question":"最後に、どんたく通り周辺の整備について、お伺いいたします。現在、大井町西口区営駐輪場は、当日利用の１階は１２１％、ほか２階、３階部分は、その半分の利用率と聞いております。もっと有効に利用できるように、例えば、限られたスペースでも設置可能な機械式地下駐輪場を設置するなど、区営駐輪場の新たな整備を提案します。それぞれご見解をお聞かせください。","respondent":"片田防災まちづくり事業部長","answer":"とりわけ立会道路、これは補助１６３号線ができれば、委員ご指摘のように、車の流れもかなり変わってくるだろうということを考えてありますので、それを踏まえた中で、実際の交通量がどのように動くかということも検証しなければいけませんでしょうし、その中で。","voiceIndex":69,"id":"exchange-033"},{"speaker":"金野委員","kind":"質問","question":"どうか、大井町駅周辺まちづくり、魅力的で住みやすい市街地整備に向け、一層のご努力を期待し、私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-034"},{"speaker":"浅野委員","kind":"質問・要望","question":"実行計画が新しくなっても、今まで区が進めてきた区有施設の二酸化炭素排出量削減の実績は、継続して報告するように求めます。そして、これらの温暖化対策の実績および進捗状況については、逐一、品川区のホームページや、また広報「しながわ」において、ぜひとも、区民の方にわかりやすい広報に努めて、提供するように要望しますが、いかがでしょうか。ご見解をお伺いします。","respondent":"岩田都市環境事業部長","answer":"最初に、品川区環境計画という、これは、温暖化だけではなくて、地球の資源の有効活用という面も含めた総合的な計画ですけれども、まずこの計画が一つあります。これが、平成２４年度をもって、第１次が終わりますので、そこの改定作業を、来年度予定しております。","voiceIndex":73,"id":"exchange-035"},{"speaker":"浅野委員","kind":"質問・要望","question":"品川区の広報、努力をしていただいていると思いますけれども、ぜひとも、区民にわかりやすいもの、グラフ、また図を使っての説明にしていただきたいと思います。ＥＳＣＯ事業については、新しい施設建設、または設備更新などの機会をとらえて、まずは本区で導入して、その結果をもって事業者への導入を推進してはいかがでしょうか、ご見解をお伺いします。","respondent":"岩田都市環境事業部長","answer":"ひいてはＣＯ２の削減につながるということで、費用の削減分の何割かを、この事業者が受け取るという、非常におもしろいシステムですので、これは、私どもも活用していくべきだと考えておりますので、今後、この利用につきましては検討してまいります。","voiceIndex":75,"id":"exchange-036"},{"speaker":"浅野委員","kind":"質問","question":"今年は３月の東日本大震災の影響もあって、申し込みが増えていると伺っておりますが、防災の観点から、また、拠点となる区有施設への積極的な設置導入が課題となってくると考えております。そこで、助成事業および区有施設への設置について、これまでの進捗状況と、今後の推進に向けた取り組み課題について、あわせてお伺いします。","respondent":"岩田都市環境事業部長","answer":"太陽熱の温水器につきましては、東品川の特別養護老人ホームで導入等をしています。今後も、区の新築工事、あるいは大規模リニューアルの時期をとらえまして、こういった新エネルギー機器の設置を進めてまいる所存です。","voiceIndex":77,"id":"exchange-037"},{"speaker":"浅野委員","kind":"質問・要望","question":"ぜひとも、区有施設への積極的な設置、重ねて要望しておきます。期せずして、省エネの取り組みとなりましたが、コンテストには、どれぐらいの世帯が参加をしたのでしょうか。なお、これから暖房が必要となる季節になりますが、状況によって、区民への啓発事業という観点から、再び節電コンテストを実施することも検討しているのか、どうか、あわせてお伺いします。","respondent":"岩田都市環境事業部長","answer":"１,５００件弱の方々の参加状況を把握するのは、一概には難しいことではありますけれども、その節電での削減率が、対前年比で３０％以上削減された方は、申し込み者の５割を超えているということで、私どもが思っていたより、かなりの皆さんが削減に努力をされている。","voiceIndex":79,"id":"exchange-038"},{"speaker":"浅野委員","kind":"質問・要望","question":"防災対策の強化について、質問します。地震・津波対策を検討してきた中央防災会議の専門調査会は、首都直下型地震対策で、関東大震災並みのマグニチュード８クラスの地震の想定を求めるなど、最大クラスの地震による揺れと津波を想定するように提言し、津波到達時間が短い地域では、５分程度で避難できるようなまちづくりを目標に掲げました。","respondent":"片田防災まちづくり事業部長","answer":"現在、委員ご指摘のように、国のほうでは、中央防災会議を開催するなどして、なおかつ、津波・地震に対しても、津波対策検討委員会、あるいは、東京都のほうでも、地震・津波に伴う水害対策技術検証委員会などを設置して、東京都、国、それぞれの立場で、今。","voiceIndex":81,"id":"exchange-039"},{"speaker":"浅野委員","kind":"質問・要望","question":"区民への情報提供について、お伺いします。津波対策として測量した標高をホームページ等で公開して、津波ハザードマップの作成も検討すると伺っております。さらに、津波ハザードマップ等の防災情報を整理してはいかがかと思います。これは、区民にとっても、また、データを管理する側にとってもメリットがあると思いますので、ぜひとも整備していただければと思いますのが、いかがでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"確かに、その中には、地盤のマップというようなものは入ってございませんけれども、それとあわせて、どのような進め方ができるのかといったような検討は行っていきたいと考えています。","voiceIndex":83,"id":"exchange-040"},{"speaker":"浅野委員","kind":"質問・要望","question":"危険だという情報を得ても、避難しない人は必ず発生します。これらは、逃げ遅れなどの原因となりました。周りの方を助けよう、近所の方は大丈夫か、避難できたかと、ほかの人のことを気にかけて逃げ遅れた方も多かったと伺っております。地域防災計画を策定する過程で、津波被害の危険性があると判断された地域においては、避難訓練を実施することも検討すべきと考えますが、あわせてお伺いいたします。","respondent":"片田防災まちづくり事業部長","answer":"あるいは、現実から逃避して、自分のところには津波が来ないだろうといったような考えとか、あるいは、周囲がどこに避難したかということで、自分も同じ行動をとってしまうといったような呪縛状態、こういうことに陥ることが、今回の地震の中でも。","voiceIndex":85,"id":"exchange-041"},{"speaker":"浅野委員","kind":"提案","question":"公明党は、これまで、携帯メールへの配信、エリアメールの採用、商店街の放送設備やデジタルサイネージの活用、またツイッターの利用など、緊急情報の提供の重要性を指摘し、数多くの提案をしてきました。区としても、複数の通信手段によって、より確実に連絡する方法を検討することとしまして、エリアメールも、配信の準備を整えたと伺っております。その対策の進め方についてもお伺いします。","respondent":"片田防災まちづくり事業部長","answer":"進め方についても、そのためには、日常のコミュニケーションを中心としたケア体制をうまく活用して、地域でのコミュニケーションの強化の拡充を図って、要援護者の把握、それとあわせて、所管と連携をとった対応を考える必要があると考えていますので、そういう方向で。","voiceIndex":87,"id":"exchange-042"},{"speaker":"浅野委員","kind":"意見","question":"情報弱者への情報提供、これからますます必要になってくると思います。地域の方の力を得ながら、ぜひとも、このような方が逃げ遅れてしまうということがないようにしていただければと思います。ここで委員長に、資料の提示の許可をお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":89,"id":"exchange-043"},{"speaker":"浅野委員","kind":"提案","question":"これは、昨日、一昨日と、５時の定時放送もちゃんと聞くことができたものです。この防災ラジオの導入のネックとなっているのが、何度も伺っておりますが、コストの問題です。区としても、さらに調査検討を進めておられると思いますけれども、情報弱者の方、まずこのような方に積極的に助成制度を設けて提供していくことを提案しますが、いかがでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"それと価格の中で、どういうような変動があるのか、それともう一つ、当然効用は十分に理解していますけれども、対象者を含めて、防災ラジオが配付されたとしても、実際に耳が聞こえないという方も中にはいらっしゃいますので、先ほどの情報弱者ということもありますので。","voiceIndex":91,"id":"exchange-044"},{"speaker":"石田（慎）委員","kind":"質問","question":"よろしくお願いします。民主・改革ネットを代表して、井上委員とともに総括質疑をします。私からは、水辺の活用について、そして、事務事業評価について、防災について、お伺いをします。そして、区としても、水辺に親しむ施策にさまざま取り組んでおられますが、水害を防ぐために、また実際に水害が起こったときに、どのような対応策をとられているのでしょうか、あわせてお聞かせください。","respondent":"岩田都市環境事業部長","answer":"その場合、東京湾に面した地の利を生かした、船を使った対策というのは、どうしても必要になってまいりますので、そういった面では、今後とも、緊急時の水辺の利用というのは欠かせないものと考えております。それから、五反田に目黒川の水辺広場というのが完成いたしました。","voiceIndex":96,"id":"exchange-045"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"東京で、自然に触れ合う場所というのはなかなか少ない中で、水辺の精神面のいやし効果があると思います。そんな中で、全部を数えると、小さいところから大きなところまであると思いますので、主立ったところで構いませんので、品川区内にある桟橋がどのぐらいあるのか、また、その中で、どのぐらい活用されているのか、教えてください。","respondent":"岩田都市環境事業部長","answer":"公共桟橋といいますと、この４カ所になります。もう一つは、大井競馬場をおりたところに、特別区競馬組合が設置しました船着場が１カ所あります。それから、民間団体が、水辺を楽しむために設置されておりますのが、天王洲と勝島運河に１カ所ずつあります。","voiceIndex":98,"id":"exchange-046"},{"speaker":"石田（慎）委員","kind":"意見","question":"やはり今までずっと桟橋があるけれども、活用をしていなかったら、実際に必要なときに、ほんとうにその桟橋が使えるのかも含めて、その活用方法を、区として改めて、災害時のみならず、ふだんから、例えば品川区のイベントの際には活用をしていく、そういった方法があるのかどうか、そこだけお答えください。","respondent":"岩田都市環境事業部長","answer":"従来から天王洲、あるいは勝島では、地域の皆様がボートを浮かべたりということで、水辺を楽しんでいただいておりますので、区としては、そういったさまざまな方たちが水辺を楽しまれる運動を、いろいろな面からサポートしていく。","voiceIndex":100,"id":"exchange-047"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"災害時、平常時、両方の面から利用、その対応策、また活用方法、これからもしっかりと取り組んでいただきたいと思います。そこで、水辺について、もう１点だけ。目黒川や立会川において、浄化対策を行ってきましたが、平成２３年度の行政評価においても、目黒川の浄化対策について、見直しが必要ではないかと、評価がなされました。もともと目黒川は東京都の管轄であります。","respondent":"岩田都市環境事業部長","answer":"品川区としても、本格的な管理者は東京都ですけれども、流域の世田谷区、目黒区、品川区と力を合わせながら、目黒川の浄化については、今後も引き続き進めてまいりたいと考えております。","voiceIndex":102,"id":"exchange-048"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"続きまして、事務事業評価について、お聞かせいただきます。平成２２年度、５年ぶりに事務事業評価を行い、その評価を受けて、どのように平成２３年度の予算に反映したのか、教えていただきたい。それから、平成２３年度は、外部を入れた評価を行いましたが、これからの取り組みとして、事務事業評価、また、区民参加による行政評価、これに基づき、これからの展望をお知らせください。","respondent":"日下部企画部長","answer":"さらに廃止の関係です。そんなに大きくありませんが、グラフ誌「すまいるしながわ」の発行を廃止するということです。それから、箱根荘につきましては、平成２４年度の廃止に向けて検討を進める。そのような形で、平成２３年度の予算の中に反映をしたところです。","voiceIndex":104,"id":"exchange-049"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"その思いで、今回、どのように反映されたかをお聞きさせていただきました。その中で、例えば、平成１３年度から平成１７年度で事務事業評価を行い、そして、平成１８年度で成果と課題の総括、その後、５年後、平成２２年度、新たにゼロベースからの事務事業評価を行いましたが、この評価をやったときと、またやらなかったときの違いは何だったのか、お答えください。","respondent":"日下部企画部長","answer":"ただ、評価を実施しているかどうかということにかかわらず、それぞれの年度によりまして、見直しの内容とか、規模も上がったり、下がったり、いろいろとらえ方が難しい面もありますので、今、ご指摘のありましたような、事務事業評価をやっていたときと。","voiceIndex":106,"id":"exchange-050"},{"speaker":"石田（慎）委員","kind":"提案","question":"やったときとやらなかったとき、もちろんやらなかったときも、区として、必要な事業、また必要でない事業というのは、それなりに内部で集約をされたり、また、議会でも予算特別委員会や行財政改革特別委員会の際に、また議会からの提案、提言をしていますので、その点は、そこまでの違いはないのかもしれません。よろしくお願いします。","respondent":"日下部企画部長","answer":"今のご質問の趣旨というのは、おそらく、評価がＡ、Ｂ、Ｃ、Ｄ、Ｅとありますけれども、その中で特にＢ評価、継続という扱いになった事業は、これはもう文字どおり、事業をそのまま継続する。","voiceIndex":108,"id":"exchange-051"},{"speaker":"石田（慎）委員","kind":"意見","question":"品川シェルターにおいては、平成２２年度の決算書にも載っていましたが、平成２２年度は受け付けがなかったという。夏期のホームステイ事業、これも民間の企業がさまざまなプランを用意し、そして、留学に向けた制度を幾つか持っています。そういったときには、やはり民間の力を生かし、例えば、補助制度を設立するなり、新たな手法があると思いますが、その点のお考えをお聞かせください。","respondent":"日下部企画部長","answer":"ですから、そういうことを考えますと、このままずっとそれでいいということではありませんけれども、今の時点で、実施の可否まで踏み込めるような状況にはないのではないかと考えています。それから、２点目にご指摘のありました、マイバッグ運動のエコスポット。","voiceIndex":110,"id":"exchange-052"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"もちろん、その評価を十分に重視していただきたいわけでありますが、しかし、常にチェックをするその姿勢が何より大事なのかなと思います。それが事業につながり、またさらには、区民サービスの向上につながると思いますので、これからも、意識改革を含めた事務事業評価、また、外部の評価も入れながら検討をしていただきたいと思います。最後に、防災についてお聞かせください。","respondent":"片田防災まちづくり事業部長","answer":"区としての、今後の方向ということも含めてですけれども、事業所に対するきちっとした正しい行動認識、これは事業所のＢＣＰ等の策定を含めた支援等も検討しなければいけないでしょうし、その中で、企業者においても。","voiceIndex":112,"id":"exchange-053"},{"speaker":"石田（慎）委員","kind":"意見","question":"そんな中で、帰宅困難者、品川区でも、幾つかの施設をあけて受け入れをしていただきました。今後、例えば、避難所について、帰宅困難者がそこに駆けつけたときに、どのような対応をされるのか。帰宅困難者対策、今後の区としての方向性をお知らせください。","respondent":"片田防災まちづくり事業部長","answer":"それとあわせて、ご紹介がありました帰宅困難者の把握をきちっとしたうえで、では、民間企業、あるいは私立の学校とかがありますので、そういうところの避難所の確保とか、その充実に努めてまいりたいと考えております。","voiceIndex":116,"id":"exchange-054"},{"speaker":"石田（慎）委員","kind":"意見","question":"ぜひ、柔軟な対応をしていただきたく、お願いをします。避難所において、五反田地区では、大きな人口変動がある中で、避難所の受け入れ人数等の見直しが必要ではないかと思いますが、その点もお聞かせください。","respondent":"片田防災まちづくり事業部長","answer":"すべての方が避難されるわけではございませんので、被害想定に基づいて、一定のご自宅に戻れない方を想定していますので、もしその数に見合わないというような実態があるとすれば、先ほど申し上げましたような、補完避難所とか。","voiceIndex":120,"id":"exchange-055"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"最後に、防災計画についてお聞かせください。全体計画においては、国、そして東京都が出された後に、区のほうで出すという流れになると思いますが、例えば、今起きたら、現時点の計画を遂行するわけでありますので、今の時点で変えられるものに関しては変えて進めていただきたいと思いますが、その点の考え方をお聞かせください。","respondent":"片田防災まちづくり事業部長","answer":"委員ご指摘のとおり、今、現時点で起きたらという想定ですけれども、やはり平成１９年度に策定した地域防災計画、もちろん組織が変わって、名称が変わっておりますので、その辺の精査をきちっと行ったうえで、現行の体制の中で進めていくということが原則と考えています。","voiceIndex":122,"id":"exchange-056"},{"speaker":"石田（慎）委員","kind":"質問","question":"早急と言っても、なかなか難しいと思いますが、ぜひしっかりとした計画になるようによろしくお願いいたします。以上で、私からの質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-057"},{"speaker":"井上委員","kind":"確認","question":"学校給食の食材から内部被曝を防ぐための対策、東日本大震災のがれき処理について、災害時の要援護者の個人情報管理の３点について、お伺いをしていきます。学校給食の食材からの内部被曝を防ぐための対策について、お伺いをいたします。そこで、公給食に対する区の防止策について、お伺いをいたします。確認の意味で、３点質問をいたします。以上、３点について、答弁をお願いいたします。","respondent":"田村教育次長","answer":"これにつきましては、区教育委員会のほうでは、４月の時点で、校長連絡会を通じて、どうしても、保護者が弁当、水筒を持参をしたいという個別の申し出があった場合には、学校の判断として、柔軟に対応してくださいということで、学務課長から各学校に指示を出しています。","voiceIndex":128,"id":"exchange-058"},{"speaker":"井上委員","kind":"意見","question":"今の３点目のメグミルクについてなんですけれども、他社が公表していないというのは、企業の論理であり、私たち、子どもたちを学校に送り出している保護者としては、それで許される、納得ができるものではない。再三公表をお願いしているということにとどまらず、絶対に公表していただいて、それを区民に明らかにする必要があると思います。そのことについての決意を、もう一度、お願いいたします。","respondent":"田村教育次長","answer":"委員ご指摘のとおり、牛乳を飲んでいる児童、あるいは保護者の立場になりますと、おっしゃるとおり、企業の理論ではなく、安心ができる形の公開を求めていくということで、２３区の中で、品川区だけではございませんので、他区とも合同して。","voiceIndex":130,"id":"exchange-059"},{"speaker":"井上委員","kind":"質問・要望","question":"例えばヨウ素１３１では、成人より乳幼児のほうが８.７５倍もその影響を受けることになります。ですから、赤ちゃんや小さな子どもを抱える親御さん、特に母親が心配しています。特に学校給食、保育園給食の安全の確保は、品川区の責任ですから、公給食へのリスク管理は継続していかなければなりません。教育委員会で、そういった制度も活用して、食材の調査を行うように求めますが、見解を伺います。","respondent":"田村教育次長、本保品川区保健所長","answer":"ということから、産地や流通での検査をさらに徹底することでしか、食材の安全を確保することはできないと、教育委員会として考えておりますので、引き続き、国や東京都へ要請に努めてまいりたいという考え方です。私からは、放射能に関連する食品についての不安が広がる中で、どのように対応するかということについて、お答えいたします。区では、震災直後、一部の浄水場で乳児における暫定規制値を超える値が検出されたことがございました。","voiceIndex":132,"id":"exchange-060"},{"speaker":"井上委員","kind":"質問","question":"教育委員会のほうでも、どのようなフォローをお考えいただけているのかということも、質問いたしましたので、答弁をお願いいたします。","respondent":"田村教育次長","answer":"先ほど答弁の中で申し上げましたが、今、社会的に流通している食材については、安心ですので、また、保護者について、ご不安だとか、相談があれば、学校、あるいは教育委員会のほうで、責任を持ってご相談に応じたいと考えております。","voiceIndex":135,"id":"exchange-061"},{"speaker":"井上委員","kind":"質問","question":"次に東日本大震災の災害廃棄物、がれきの処理について、お伺いいたします。東日本大震災では、これまでに類を見ない膨大な量の災害廃棄物が発生しています。被災自治体だけですべてを処理することは困難なため、４月、東京都も、２０１３年度までに５０万ｔを引き受けることを表明いたしました。この協定の内容について、説明をお願いいたします。","respondent":"太田品川区清掃事務所長","answer":"３者の災害協定の内容です。建設混合廃棄物、それから、廃機械・機器類、これを１,０００ｔ、１０月から１１月まで、東京都で受け入れるです。その後、１２月から平成２４年３月まで、１万ｔを受け入れていくという内容です。","voiceIndex":137,"id":"exchange-062"},{"speaker":"井上委員","kind":"質問","question":"そこから見えてきた問題を中心に、区の対応と、見解を伺います。江戸川清掃工場から排出されました汚染焼却灰４８７ｔが中央防波堤埋立処分場に仮置きして保管されています。東京都や、東京二十三区清掃一部事務組合任せではなく、区民の安心を守る立場から、適切な処理、処分方法を、区長会として十分に検討して、指導すべきと思いますが、区長の思いと見解を伺います。","respondent":"太田品川区清掃事務所長","answer":"これを受けまして、東京二十三区清掃一部事務組合では、２３区のごみの中間処理と清掃工場の施設整備を担当するという立場から、現在、技術的な検討をしていると聞いているところです。","voiceIndex":139,"id":"exchange-063"},{"speaker":"井上委員","kind":"質問・要望","question":"被災地の一日も早い復興を願い、がれき処理の協力を惜しむものではありませんけれども、放射能をいたずらに拡散させることはあってはならないと思っています。見解を伺います。区は、区内２カ所で空間線量の定点測定をしておりますが、清掃工場の周りも定点観測地点に加えて、区民の不安解消に努めるべきです。増設を求めますが、あわせて見解を伺います。","respondent":"太田品川区清掃事務所長","answer":"したがいまして、ご提案の、区独自の測定については、東京二十三区清掃一部事務組合での測定結果が急激に高くなるなどの状況がない限り、現在のところ、実施する考えは特にございません。","voiceIndex":141,"id":"exchange-064"},{"speaker":"井上委員","kind":"質問・要望","question":"限りなく、区民の不安解消に努める手だてをしていただきたいと思います。ＰＣＢやアスベスト、重金属などの有害科学物質の混入を想定した環境対策を、東京都と東京二十三区清掃一部事務組合が行うよう要請すべきです。いろいろなところで、自治体の覚悟のなさが露呈をし、結果的に、被災地を傷つける行為が続いています。区長の強い決意をお聞かせください。","respondent":"太田品川区清掃事務所長","answer":"区といたしましては、国の処理方針等を巡視しながら、東京都に対しては、現地での分別の徹底、そして、東京二十三区清掃一部事務組合については、排ガス浄化処理装置の保守点検について、的確に行うよう要請をしていきたいと考えているところです。","voiceIndex":143,"id":"exchange-065"},{"speaker":"井上委員","kind":"質問・要望","question":"危険な電力ではなく、より安全な、持続可能なエネルギーを選択できる政策転換が求められています。二度と同じ過ちを、日本が犯さないために、どうやって脱原発を進めるかではなく、その前に、なぜ脱原発にすべきかを、福島を教訓に、国民が深く議論をすることが必要です。次に、災害時に市民力を生かせる個人情報の管理について、伺います。区民の疑問、この場で解決いただけるよう、説明をお願いいたします。","respondent":"片田防災まちづくり事業部長","answer":"基本的には、私ども、それぞれの関係所管のほうから、対象となる方のデータをきちっと収集して、本人の了解を得るべくご案内をさせていただいたうえで、本人が了解ということであれば、ご返送いただいたうえで、適切に名簿を整備いたしまして、基本的には、町会長とか。","voiceIndex":145,"id":"exchange-066"},{"speaker":"井上委員","kind":"提案","question":"それは、防災課が、福祉部局から目的外使用という手続で個人情報を預かり、登録を希望するか、しないか、郵送により確認しております。１万人を超える対象者がいますけれども、名簿登録者は３,０００人ぐらいにとどまっています。こういう障害者が集まる場で、特性に合わせたフォローが担当部局でできるはずなので、福祉部局での名簿づくりを提案したいと思いますが、見解を伺います。","respondent":"木下健康福祉事業部長","answer":"最終的な要援護者の名簿の主管を福祉部門で、というお話ですけれども、いわゆる発災直後の救助の問題と、その後の災害時介護といいますか、そういう支援の問題というのは、一応、役割分担をしていくべきだと考えておりまして、そういう点で言いますと、救助の問題というのは。","voiceIndex":147,"id":"exchange-067"},{"speaker":"井上委員","kind":"質問","question":"平時から、防災課、福祉部局の連携が欠かせないということが１点あるかと思います。現在、計画づくりにそのメンバーが位置づいているのか、もしそうでなければ、今後の方針について、見解を伺います。","respondent":"片田防災まちづくり事業部長","answer":"今回の防災計画の見直しについても、先ほど申し上げましたけれども、全体の幾つかの課題が見えてきておりますので、ジャンル別に、一定の庁内の検討会というものを、これから組織していくようなことを考えてありますので、その中で、福祉部局とか。","voiceIndex":149,"id":"exchange-068"},{"speaker":"井上委員","kind":"質問","question":"連携というのは当然だと思うんですけれども、その協議をする場に、構成メンバーであるという位置づけが担保されなければ、協議の場で意見を聞き合いましたということになってしまうのですけれども、そのメンバーにきちんと位置づけるということについては、いかがでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"現在、ＢＣＰといいましょうか、事業継続計画の策定を進めてありますので、そういう中でも、非常時の場合にどういう体制をとるか、平時の事業をどう継続できるかといったような議論を、あわせて行ってありますので、そういう連携の中で。","voiceIndex":151,"id":"exchange-069"},{"speaker":"井上委員","kind":"意見","question":"今、防災計画も見直されています。さまざまな課題も見えてきた中で、私たちも、区民の方からいただいたご意見などをしっかりと反映させる形で、平時からそういった対策に協力をするという形で取り組んでいきたいと思いますので、これからもお願いいたします。終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":153,"id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、一日も早い特別養護老人ホームの増設を求めて、品川区の特別養護老人ホーム増設計画はどのような方針なのか、ここを中心に伺いたいと思います。平塚橋会館での新たな特別養護老人ホームについての計画概要を伺います。開設時期はいつか、ベッド数はどう考えているのか、上にある区営住宅４８戸は引き続き併設となるのか、シルバーセンターは残すべきだと思いますが、いかがでしょうか。","respondent":"日下部企画部長","answer":"ただ、そういうことで、特別養護老人ホームは区政の重要課題でもあります。そういった観点から前向きに検討していく。それから、区営住宅は、先ほどもご答弁申し上げましたが、現に居住者がいらっしゃるということもありますので、ご不安のないように検討を進めているです。","voiceIndex":155,"id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"シルバーセンターは機能強化、認可保育園も、ぜひこれは要望しておきたいと思います。これまで、学校跡の活用、そして、民間の土地の取得も考える、さらに平塚橋会館の区営住宅とありますが、このさまざまな角度からの検討とは、これ以外にもあるのか、どういう角度なのか、また、地域配置についてはどういうふうに考えているのか、新たな特別養護老人ホーム整備方針を伺いたいと思います。","respondent":"日下部企画部長、木下健康福祉事業部長","answer":"耐震改修計画との整合性です。基本的に、私ども、今後、検討を進めていくということでありますけれども、平成２７年度を視野に入れて検討を進めていくと考えております。今回は、学校の跡施設ではなく、他の公共施設の跡活用ということが具体化されたわけであります。そういう点で、このような検討の取り組みが、さまざまな角度からの取り組みです。","voiceIndex":157,"id":"exchange-072"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて、整備方針を伺いましたけれども、何度聞いても、なかなかはっきりしない点は、増設をしますというご説明はありますが、一日も早い特別養護老人ホームをどうやって進めていくのか、この考えが示されないので、ここを伺いたいと思います。一日も早い特別養護老人ホームをどうつくるのか、考えを伺いたいと思います。そして、２点目は、いつまでに幾つつくるのかということです。","respondent":"木下健康福祉事業部長","answer":"それは、多様なニーズに応える施設整備ということでケアホーム、グループホームなどもしてまいりましたし、在宅介護を支援するということで、施策の充実にも努めてきた。このような総合的な進め方が、まず基本だということであります。","voiceIndex":160,"id":"exchange-073"},{"speaker":"中塚委員","kind":"質問","question":"特別養護老人ホームに限らず、総合的に進めたいとの考えですけれども、目標がない、そのための計画がない、これでは必要数を早くつくることができないのではないかと思いますが、この点を、どうお考えなのか伺いたいと思います。土地が見つかれば、というお話でありました。小規模特別養護老人ホームも積極的につくることを位置づけるべきではないかと思いますが、この点も、伺いたいと思います。","respondent":"木下健康福祉事業部長","answer":"経営的な効率を考えれば、３,０００m2というのは理想的な数字になるわけでありますけれども、単体の小規模は、とても経営的に難しいところでありますけれども、私どもとしては、グループホームと組み合わせることによって、かろうじて経営は成り立つかなと考えています。","voiceIndex":162,"id":"exchange-074"},{"speaker":"中塚委員","kind":"質問・要望","question":"特別養護老人ホームの整備、目標がなくても進むというのは、これはおかしいと、私は思います。入所を待っている高齢者の切実な実態にかみ合った増設計画を立てることこそ必要だと思いますが、この点を伺いたいと思います。ここで、数字について伺いたいと思いますが、今年３月の特別養護老人ホームの入所調整会議、６０９人が審査対象となりました。","respondent":"木下健康福祉事業部長","answer":"この４４０名の方の要介護度別分布ということでございましたので、要介護度１から５まで順番に申し上げます。８６名、８０名、１１４名、１００名、６０名。以上で、４４０名になっているところです。","voiceIndex":164,"id":"exchange-075"},{"speaker":"中塚委員","kind":"質問","question":"土地についてですけれども、やはりご説明を伺うと、まとまった土地はなかなか得にくいとの話がありました。特別養護老人ホームの入所についてですけれども、直近で見ますと、入所に至った方が、八潮南特別養護老人ホームが開設した後で１０９名と伺っております。病院からは退院を迫られる。こうした実態を、いつまでに、どう解決していくのか、そこを示す責任があると、私は思いますが、いかがでしょうか。","respondent":"木下健康福祉事業部長","answer":"小規模特別養護老人ホームのお話がございましたけれども、今度、杜松小学校跡で予定をしておりますけれども、こちらも、校舎の大きさから言うと、八潮南中学校の半分ぐらいでありますから、そういう点では、小規模を選択せざるを得ないだろうと考えています。","voiceIndex":166,"id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"一番の原因は必要数が足りていないこと、この実態にかみ合った一日も早い増設を具体化することこそ必要だと、改めて求めたいと思います。高齢者の実態は切実です。ここはＴＯＣの駐車場ではなく、特別養護老人ホームに、そしてさらに認可保育園や防災用の公園など、住民要望に沿ってこそ活用すべきです。特別養護老人ホーム増設へ、跡地活用の変更を決断すべきだと思いますが、いかがでしょうか。","respondent":"日下部企画部長","answer":"ただ、建て替えにあたっては、営業を継続しつつ建て替えを進めていきたいと、そのことが地域の活性化、それからまちのにぎわいといった点で、大変重要なことであると、こういった観点から、私ども区のほうといたしましても。","voiceIndex":168,"id":"exchange-077"},{"speaker":"中塚委員","kind":"質問・要望","question":"建て替えたいという願望だけで、既に学校跡地をＴＯＣに貸している、どう考えてもおかしいと思います。この話が持ち上がったのは平成１７年で、６年経った今になっても、建て替え計画が示されていません。なぜＴＯＣは遅れているのか。そして、品川区はいつまで待つのか伺いたいと思います。つまり、どういう計画になれば本格的な貸し付けを行うのか、その条件をご説明いただきたいと思います。","respondent":"日下部企画部長","answer":"その後、本格貸し付けということでありますけれども、当然のことながら、本格貸し付けをするにあたりましては、施設内容も含めまして、具体的な建て替えの計画、私どもが旧第一日野小学校跡地を貸し付けをするといった、先ほどもご答弁申し上げましたけれども、地域経済。","voiceIndex":170,"id":"exchange-078"},{"speaker":"中塚委員","kind":"質問・要望","question":"本格貸し付けの条件について、具体的な建て替え計画、しっかりと確認するとご説明がありました。今、説明があった、具体的な建て替え計画というのは、一体どういう条件なのか、さらに伺いたいと思います。大体、品川区は幾らを要求しているのか。これらすべてが決まって初めて本格貸し付けを行うということなのか、ここがずるずるだと、また延びてしまいますので、しっかりと説明していただきたいと思います。","respondent":"日下部企画部長","answer":"実際の施設の計画について、幾つかの具体的な内容について、今、内部的な検討を行っているという段階でありますので、私どもとしましても、できるだけ早く整理をしまして、区のほうにもご報告をいただきたいと。","voiceIndex":172,"id":"exchange-079"},{"speaker":"中塚委員","kind":"質問","question":"先ほど、本格貸し付けのための条件を伺ったら、具体的な建て替え計画という話がありました。しかし、その中身を聞いたら、結局何も決まっていない。どういうビルなのか、高さか、いつ工事が始まるのか、終わるのかも決まっていない。それとも、ここが決まっていなければ、白紙になるということなのか、ここが不明確だと、さらにずるずると延びてしまいますので、ここは改めて伺いたいと思います。","respondent":"日下部企画部長","answer":"改めてご答弁申し上げますが、本格貸し付けをするにあたりましては、当然のことながら、具体的な施設計画がどういうものであるか、その辺についてしっかり確認をする、これが前提条件になろうかと思います。","voiceIndex":174,"id":"exchange-080"},{"speaker":"中塚委員","kind":"質問","question":"具体的なものが何かと、その条件を伺っても、結局、説明ができていないと、私は思います。つまりは、ビルのコンセプトも、今の時点で定かでない。今、こういう状況ということなのでしょうか。これらを考えれば、どう考えたって、半年とちょっと先の来年の９月に、計画が進むはずがない。既にＴＯＣのペースで遅れているということなのでしょうか、伺います。","respondent":"日下部企画部長","answer":"具体的な内容ですけれども、これにつきましては、さっき申し上げましたように、例えば、施設全体の面積がどうで、用途的にもどういう配分でとか、そういう具体的な内容については、都市開発課長がご答弁申し上げましたように、幾つかの案について、今、内部検討を進めている。","voiceIndex":176,"id":"exchange-081"},{"speaker":"中塚委員","kind":"質問・要望","question":"結局、詳しく伺っても、具体的な計画が決まれば本格貸し付けだというものの、具体的な計画の条件等は何かというのは示されることがありませんでした。それよりも、一日も早く、急ぐべき特別養護老人ホームの増設、そして、認可保育園や公園など、区民要望にこそ充てるべきだと思います。では、最後に伺いますけれども、いかがでしょうか。","respondent":"日下部企画部長","answer":"そういう方たちの問題も含めて、どう対応していくか、区民生活に密接につながる問題でもありますので、両方の問題にしっかりと対応していくという観点で進めていきたいと考えております。","voiceIndex":178,"id":"exchange-082"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に一言述べたいと思います。結局、今も経済対策を述べましたけれども、どんなビルになるのかが決まっていないのです。決まっていないのに、協力をするというのは間違っている。しかも、母校がコインパーキングになるなんて、だれが考えてもおかしいと思います。私は、ここは住民要望に沿って、特別養護老人ホームや認可保育園、公園など、住民要望の実現に充てるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-083"},{"speaker":"飯沼委員","kind":"質問・要望","question":"９月２６日、文教委員会において、品川区の子どもたちを守る会から提出をされた陳情、内容は、子どもたちの被曝の防止を求めたものでしたが、満場一致で趣旨採択されました。趣旨採択を受けとめて、子どもを守る対策を求めます。はじめに、福島第一原子力発電所事故と放射能被害の認識をお伺いします。子どもたちが外部被曝、そして内部被曝をしないように、どのような対策をとられているのか、伺います。","respondent":"岩田都市環境事業部長","answer":"放射能の関係ですけれども、いわゆる福島第一原子力発電所の水素爆発によって、東京にも放射能を浴びたちりが降ってきて、いわゆる水道水の汚染から始まった、都民、区民の不安というのは、委員のおっしゃるとおり、特に小さい子どもを持っておられる親御さんにとっては。","voiceIndex":182,"id":"exchange-084"},{"speaker":"飯沼委員","kind":"質問・要望","question":"福島第一原子力発電所事故は、広島原爆に換算すると、２０個の膨大な放射性物質が放出され、いまだ収束をしていません。日本は、かつて経験したことのない大変な事態に直面をしているわけですけれども、一番求められているのは、放射線量の測定と公表、区内がどうなっているのか。放射線量をはかり、高いところが見つかれば除染を行うということなのか、確認をします。","respondent":"岩田都市環境事業部長","answer":"私どもが一番大事だと思っているのは、さらに次のような何らかの事故が起きることが心配ですので、継続的な定点における観測が一番大事だと。","voiceIndex":184,"id":"exchange-085"},{"speaker":"飯沼委員","kind":"確認","question":"確認なんですけれども、区民の皆さんが不安を抱いている箇所を測定してくださるのか。もしも、線量が高かった場合に除染をしていただけるのか、その点を伺いましたので、再度、お答えを願いたい。それから、水素爆発で放出された量があまりにも多かったんです。ですので、測定をしなければわからないといった状況なのですが、いかがでしょうか。","respondent":"岩田都市環境事業部長","answer":"年間５mmシーベルトを超えるような汚染状況が見つかった場合には、除染等を行う必要があるというのが、環境省が打ち出した数値ですので、この数値になれば、品川区として、それなりの対応は、当然のことながら、とっていくです。","voiceIndex":186,"id":"exchange-086"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ対応していただきたいのですが、個人の私有地ではなくて、例えば子どもたちが通う通学路、それから保育園の通園路といったところも、ぜひやっていただきたいのですが、いかがでしょうか。参考にしていただき、住民が希望する箇所とホットスポットになりやすい箇所を探して測定をし、必要な場合は除染を行って、区民を安心させていただきたいのですが、いかがでしょうか。","respondent":"岩田都市環境事業部長","answer":"しかし、一般の方々が購入可能な１０万円以下の、いわゆる学習用の観測器なんですけれども、これはかなり誤差が出ますので、いわゆる正確にはかるには、私どもの測定器の数値ではかる必要があると考えております。","voiceIndex":188,"id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保育園の前の側溝のところでの数値は、０.２１４μシーベルトでした。国に、最新技術を集めた食品検査体制を求めるとともに、区も一刻も早く独自の食品検査体制をつくるべきです。他地域でも始まっている給食の全食材検査体制を求めます。保健所など、区民向けの検査体制も求めます。そしてもう１点、保育園、学校では、野菜などを栽培をしていますが、安全チェックは行われているのでしょうか、伺います。","respondent":"金子子ども未来事業部長、田村教育次長","answer":"基本的な考え方ですけれども、再三申し上げておりますとおり、現在、市場に流通している食材というのは、政府が定めた暫定規制値をクリアしておりまして。学校も、保育園と考え方は一緒でございまして、流通しているものは安全という前提で考えています。失礼しました。１点、漏れました。最近、保育園の中でも、ちょうど季節ですので、保育園で採れた芋を焼いて食するということが、そろそろ始まります。","voiceIndex":190,"id":"exchange-088"},{"speaker":"飯沼委員","kind":"質問・要望","question":"クリアしているということですけれども、区独自での検査はしていないのでしょうか。もう１回、そこを確認させてください。子どもたちに特別な配慮が必要であるということで、２点、強調したいと思います。そして、私はぜひ、チェルノブイリに学んでほしいと思うんです。やり方はいろいろあると思いますが、品川区にできないはずはないと考えていますので、重ねて食材の検査体制を求めます。","respondent":"田村教育次長、本保品川区保健所長","answer":"先ほどもご答弁申し上げましたが、学校給食の食材の放射能測定ですが、国や都道府県、生産地、業者が、食材の安全を確認したものだけが流通していると認識しております。そのために、品川区としては、単独では行っておりませんけれども、ただ、以前、セシウムが含まれた稲わらを食した肉牛の中に、そのようなものが検出されたということについては、広域業者についての情報が。","voiceIndex":194,"id":"exchange-089"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区長は、共産党の一般質問、原発撤退を国に求めてほしいとの質問に対し、一自治体の立場で意見は差し控える、との答弁でした。３５万区民の健康と生活を守るため、ぜひ、原発からの撤退の立場に立っていただきたい、このことを要望いたします。子育て世代の大変さを私たちはどれだけ理解をしているのでしょうか。就労支援はもちろんですが、子育ての駆け込み寺として充実してほしいと願っています。","respondent":"金子子ども未来事業部長","answer":"今、委員がご指摘になった認証保育所、それから、保育ママ等々もありますけれども、そのほかとしましては、育児休暇を延長したり、あるいは、職場に連れて行ったり、認可外保育施設に預けたりということで、祖父母に預けるということもありますけれども。","voiceIndex":197,"id":"exchange-090"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっと数字がはっきりしなかったのですが、認可保育園を希望している子どもたちが、毎年３００人から４００人もいる状況が続いていますが、私は、これは区の怠慢であると思っています。保育園が不足しているから、認可保育園には入れません、認可外保育園で我慢をしてください、でいいのでしょうか。区がみずから責任を持つ、区立保育園大幅増設に踏み出すことを求めますが、いかがでしょうか。","respondent":"金子子ども未来事業部長","answer":"保育ママ事業、認証保育所の開設支援、こういったことも含めまして、総合的に対応して、待機児童については、一人でも減らすように努力していきたいと考えているところです。","voiceIndex":199,"id":"exchange-091"},{"speaker":"飯沼委員","kind":"質問","question":"一人でも減らしたいということでしたが、希望者全員を入園させる考えはないのでしょうか。私は、ここを問いたいと思います。続いて、未入園時の保護者の状況を見ていただきます。提示の許可をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":201,"id":"exchange-092"},{"speaker":"飯沼委員","kind":"質問","question":"２０１１年４月現在、認可保育園を希望し、入れなかった児童４０６名の保護者の内訳です。１番目、両親フルタイムなどの勤労者９６人、２番目、非正規やパート労働者６４人、休職中の方は、内定あり、内定なしも含めて、合わせて１００人。自営業者４１人、保護者の病気３人、その他となっています。希望者全員が入園できる対策は、品川区にあるのでしょうか。","respondent":"金子子ども未来事業部長","answer":"これだけ実施してきても、残念ながら、まだ待機児童が出ざるを得ないというのが現実ですので、私どもとしては、着実に待機児童の解消に向けて一歩一歩進めていきたいと考えているところです。","voiceIndex":203,"id":"exchange-093"},{"speaker":"飯沼委員","kind":"質問・要望","question":"さまざまな対策は、この間、幾重にも伺っていますけれども、ぜひ、品川区立でつくっていただきたい。特に区立で求める理由、今日もお話があったでしょうか、株式会社の誘致を、品川区は進めている。品川区みずからが、認可保育園大幅増設に踏み出すことを求めます。この間、介護のところでも申し上げましたけれども、株式会社は、撤退、倒産が起きた場合、子どもたちの受け皿はどうなるでしょうか。","respondent":"金子子ども未来事業部長","answer":"かつて、そういうふうな事情があったことは存じておりますが、東京都、あるいは品川区が厳しくチェックをして運営をしてまいりますので、そういうことはないと考えています。","voiceIndex":205,"id":"exchange-094"},{"speaker":"飯沼委員","kind":"質問・要望","question":"撤退、そして倒産があり得る、このことを防げると言い切れるのでしょうか。私は、子どもたちの成長、発達の場が、株式会社参入によって保育産業の変質が行われること、これは絶対に許されないことであると思います。ぜひ、直営のところを大いに頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-095"},{"speaker":"高橋委員","kind":"質問","question":"無所属品川を代表して、質問をいたします。１番目に、区内中学校での夏季休業中の補習の現状と、今後の仕組みづくりについてお尋ねいたします。現在、区内中学校では、サマースクールを実施しているとお聞きしましたが、その内容について、講座数、日数、内容、参加者など、また教員一人当たり何時間ぐらい担当しているか、こちらはわかる範囲で結構ですので、成果も含めて、お答えください。","respondent":"田村教育次長","answer":"生徒の状況を最もわかっているのは、日ごろ指導している学校の教科担当の教員ですので、各学校とも、生徒の実態に合わせて、細かく打ち合わせをして実施しているものです。実施校については、全校ですが、時間数は、平均して、週１５時間という形でやっております。","voiceIndex":210,"id":"exchange-096"},{"speaker":"高橋委員","kind":"質問","question":"ただいま、浜川中学校の例を、お話しいただきましたが、大変充実した夏季休業中の補習という形だと思います。今、お話を受けたのですが、さらに充実させていく手だては、どのようなもので、今、浜川中学校であったような仕組みを組織的にもう一歩踏み込んで、全中学校で充実したものにさせるためには、どのような工夫が必要とお考えでしょうか。","respondent":"田村教育次長","answer":"補習とは若干意味合いが異なるかもしれませんが、小中連携グループ内で、複数の学校が一緒にサマーチャレンジ講座というのも実施している例も幾つかあります。","voiceIndex":214,"id":"exchange-097"},{"speaker":"高橋委員","kind":"質問","question":"今、小中学校の枠を取り払って、そういった講座も行われているというお話を伺いましたが、大変すばらしいことだと思います。例えば戸越台中学校で行えば、周辺には中学校が三つほどあります。ですから、その子たちが通う。そういった形で、区内全体の基礎学力の向上、中学校という枠をとりつつ、実は区内中学校の学力アップにつながるような仕組みづくり、果たして、どのようにお考えでしょうか。","respondent":"田村教育次長","answer":"ただ一方で、やはり自分の学校以外、在籍しない生徒を自分の学校に呼んで授業をするということになると、その子の今までの勉学の進捗状況なり、個性なり、やり方というのも十分に把握して、それから、自分の学校に来るわけですから、生活指導上の配慮も必要ですが。","voiceIndex":216,"id":"exchange-098"},{"speaker":"高橋委員","kind":"質問・要望","question":"１番目の質問はそれで終わりにいたします。２番目の話ですが、新児童福祉法の施行に伴って、質問をします。区が、現在行っている障害を持つ児童の教育、福祉施策に力を入れているということは伺っております。発達障害児や、いわゆる保育園等における気になる子どもたちを含んだ障害児関連の施策について、どのような課題があるとお考えでしょうか。来年４月から新児童福祉法が施行されます。","respondent":"木下健康福祉事業部長","answer":"これはどういうことかというと、障害児の通所系事業については、責任主体が区市町村に明確化されるという点が、大きい変更になっているところです。そのような改正などが行われる予定になっているです。","voiceIndex":218,"id":"exchange-099"},{"speaker":"高橋委員","kind":"質問","question":"法律の詳細が、まだ出ていないということでありますけれども、今のようなご説明で、品川区にも影響があるということを、お話しいただきました。これは法体系の整理でありますけれども、今、言ったように、理念の整理でもあります。区としては、現時点で、今後の体制といいましょうか、いわゆるそういった保護者の混乱が生じないように、どのような考えをお持ちでしょうか。現時点で結構です。","respondent":"木下健康福祉事業部長","answer":"そういう点では、いわゆる福祉の療育とか、相談という部分についての一定の実績がありますので、現時点では、健康福祉事業部の障害者福祉課を主管課として考えていこうと思っているところです。","voiceIndex":220,"id":"exchange-100"},{"speaker":"高橋委員","kind":"質問・要望","question":"この問題は、また別の機会にお尋ねしたいと思います。次に、児童相談所の区への移管について、お尋ねします。現在のシステム、児童虐待防止に関して、親への指導や早期発見の方法についての課題は、どこにあるとお考えでしょうか。それを踏まえて、区に移管を要望しているわけでありますけれども、区に移管された場合、解決されるのでありましょうか。その点について、お答えいただきたいと思います。","respondent":"金子子ども未来事業部長","answer":"品川区も窓口となっております。現状では、子育て支援課と、家庭あんしんセンター内にあります子育て支援センターが両者で、区民からの虐待の通告を受け、４８時間以内に子どもの現認をし、児童相談所と連携をとって調査、訪問の対応をしているというような現状があります。","voiceIndex":222,"id":"exchange-101"},{"speaker":"高橋委員","kind":"質問・要望","question":"この評価結果を受けて、区は、児童センター事業について、どのような見通しを持っていらっしゃるのでしょうか。運営委託をしたことにより、基本的な機能や役割にプラスが生じたのでしょうか。その検証結果は、いかがでしょうか。児童の健全育成施設としての機能のレベルダウンという危惧も、委託業者に児童センターのノウハウをしっかりと継承していく、その方策によって可能ではないでしょうか。","respondent":"金子子ども未来事業部長","answer":"私どもとしましては、こうした委託を進めることによって、職員については、先ほどのご質問にもありましたが、虐待の対応について、窓口での相談、あるいは、既に実施しておりますけれども、児童相談所に職員を派遣するというような要員にも充てているところです。","voiceIndex":224,"id":"exchange-102"},{"speaker":"高橋委員","kind":"質問・要望","question":"失礼しました。レベルダウンという危惧も、きちんと継承すれば、可能ではないでしょうかということで、継承していただきたいということでした。その理由、そして、利用料金制の仕組み、そして、特に健康センターに利用料金制が導入されているのはなぜでしょうか。その指定管理のみならず、委託業者の工夫や、やる気を引き出す手段として、インセンティブについて、どのようにお考えでしょうか。","respondent":"木下健康福祉事業部長","answer":"そういう点で言うと、健康センターについては、指定管理制度を取るというのが、そういう意味では自然だと考えています。やはり民間事業者の創意工夫を生かせるということが一番大きい背景かと思います。当然、経費の面でも、従前よりも区の負担は軽減されるということがあります。","voiceIndex":226,"id":"exchange-103"},{"speaker":"高橋委員","kind":"質問","question":"そのインセンティブの２対８の部分なんですが、これが、例えば３対７、４対６のように、今後、見直しをするという予定はどうでしょうか。それをそのまま進めていくと、例えば、平成２４年度から貸し付けが決定している区民保養所のように、貸し付けという方向性、これはまた違ったお話になるのかもしれませんが、その点については、いかがでしょうか。","respondent":"木下健康福祉事業部長","answer":"現在、２対８ですが、これは毎年見直すという考え方であります。今、指定管理事業者は大きな成果を上げております、収入は大幅に上がってきているということもありますので、そういうインセンティブを働かすという意味では、現時点では、適当な割合だろうと考えています。","voiceIndex":228,"id":"exchange-104"},{"speaker":"高橋委員","kind":"質問","question":"３対７か、４対６かという点については、税外収入の確保の面からも、貴重な区有財産でありますから、還元金については、また別の機会にお尋ねしたいと思います。今回の大震災に係わる区の支出、防災関係、被災地支援などで支出した合計額、全庁的にどのぐらいになるのでしょうか。７月ごろに、区のほうにお尋ねしたのですが、昨日までお返事がないので、ここでお聞きしたいと思います。","respondent":"榎本企画財政課長","answer":"東日本大震災に対応した区の費用ということですけれども、実際に被災地のための費用としましては、今まで見込みも含めて１億６,７２５万円、それから、区のための震災対応費用として３億１,９９８万円ということで、合わせて４億８,７２３万円を予定をしております。","voiceIndex":230,"id":"exchange-105"},{"speaker":"高橋委員","kind":"質問・要望","question":"この点を踏まえて、どのように防災施策を進めていくおつもりでしょうか。このような不信とよりどころという、相反する二つの意識を踏まえて、今後、区の果たすべき役割、いわゆる公助と、その備えはどのように進めていくおつもりでしょうか。防災対策に関する区職員の育成は、どのような観点で、どのように進めていかれるつもりでしょうか。よろしくお願いします。","respondent":"片田防災まちづくり事業部長","answer":"特にこのようなアンケートの中では、ご案内のとおり、避難ルートを話し合うとか、備蓄を事前に準備しておくといったお話が重要ということの中で、自助の部分という認識の中で、区としても、自助がきちっとできるような支援、啓発を含めて、それを。","voiceIndex":232,"id":"exchange-106"},{"speaker":"高橋委員","kind":"質問・要望","question":"その形成に、行政も積極的にかかわっていっていただきたいと、要望いたします。これは、警視庁の事業なのですが、９月１日の防災訓練に伴う大規模交通規制、ＪＲ品川駅周辺での帰宅困難者対策検証訓練が実施されました。これに関しては、区として、どのような状況を分析し、そして、これを参考に、または警視庁などと連携し、地域防災計画の中で、どのように生かされるのでしょうか、お尋ねいたします。","respondent":"片田防災まちづくり事業部長","answer":"９月１日に行われた大規模交通規制です。具体的には、９月１日の９時から１０分間対応したという中で、これは、警視庁を中心として、所管の警察が共同でされたもので、現時点で、その分析というよりも、公表の中で、大きな混乱はなかった。","voiceIndex":234,"id":"exchange-107"},{"speaker":"高橋委員","kind":"質問","question":"最後に、子どものアイデアを活かした公園第１号である、鮫洲運動公園遊戯コーナーの改良工事について、お尋ねいたします。これには、職員の方、あるいは、工事業者が大変に携わっていたわけですけれども、この職員の方々の意識という観点、子どもの参加という観点、業者の取り組みという観点で、改めて、この事業の成果、そして、今後の施策にどう生かしていくのか。","respondent":"片田防災まちづくり事業部長","answer":"こういう取り組みを、引き続き継承していきたいと考えております。","voiceIndex":236,"id":"exchange-108"},{"speaker":"西本委員","kind":"質問・要望","question":"品川区として、しっかりとした考えのもと、ぶれることなく、一貫した全庁的な対応が求められるだろうと考えています。国、東京都の自治体への指針はどのようになっているのでしょうか。それに対し、品川区はどのような考え方で対策を講じていくのでしょうか。品川区独自の考え方での放射能対策はあるのでしょうか。２３区として協調しているものは、何か考えられているのか、お聞きいたします。","respondent":"岩田都市環境事業部長","answer":"品川区独自基準ですが、いわゆる放射線が人体に与える影響というのは、非常に難しい判断が要るものです。したがいまして、学識経験者や、あるいは国の基準が出された以上、一律その基準を一応のベースとして、今後、品川区が取るべき道を検討してまいります。","voiceIndex":240,"id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"区民の要求に対する対応についてもお尋ねいたしますが、窓口、個別対応では混乱すると思われます。その際の説明は、どのようにされていくのでしょうか。保育園、幼稚園、小中学校への対応は、どのようにされていくのでしょうか。カウンターを貸し出している自治体もありますが、区として、貸し出す予定はあるのでしょうか。何を基準にして理解してもらうかについての見解もお聞きいたします。","respondent":"岩田都市環境事業部長","answer":"それに、年間１mmシーベルトというのを割り返しますと、１時間当たり０.２３μシーベルトというのが一つの目安となることになります。したがって、これを超えた場合に、品川区としての何らかの対応を検討していくということになります。","voiceIndex":242,"id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"給食問題です。なぜ産地が必要なのでしょうか。意味のある公表というのは、食品そのものの放射能汚染度、放射線量を表示してこそ、意味を成すものではないでしょうか。どのような考え方で公表しているのか、その見解をお尋ねします。給食の食材の放射線量を測定してほしいという要求もあります。弊害のほうが大きくはないだろうかと思いますが、その見解について、お聞きいたします。","respondent":"金子子ども未来事業部長、田村教育次長","answer":"したがいまして、最前から説明しているとおり、市場に流通している食材は、基本的に安全なものと認識しておりますので、福島県を産地としている食材についても、それを使用している部分については、きちんと公表しています。食材の公表については、保育園と学校についても、同様の考え方で進めているものです。食材の放射能の対策ですが、先ほどもご答弁申し上げたように、正式に給食食材を検査するとなると、２kgのサンプルが必要となります。","voiceIndex":244,"id":"exchange-111"},{"speaker":"西本委員","kind":"質問・要望","question":"食材を公表する、産地を公表するということは慎重にしていただきたいと考えています。風評被害というのは、品川区から出してはいけないと思いますので、支援というあり方がどういうことなのかということをきちっと踏まえたうえでの公表を、ぜひ、していただきたいと考えています。それをしっかりと保護者に説明をしていくべきではないかと思いますが、その保護者に対する説明をどうされるのか。","respondent":"中川原地域振興事業部長、本保品川区保健所長、田村教育次長、金子子ども未来事業部長","answer":"いずれにしましても、正しい相談窓口をご案内するとともに、ちょっと誤解があって心配が高じている方については。しかし、それ以降は、問い合わせの件数は減っております。総数で、現在までで２１件です。保護者の関係ですが、学校は、３.１１以降、４月から定期的に、校長会、あるいは月１回やっていますが、副校長会等で、すべての情報について。保育園の保護者、幼稚園の保護者に対してですけれども、今、教育委員会がお答えしたのと同じように、区としての考え方、保育園。","voiceIndex":247,"id":"exchange-112"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、やはりしっかりとした情報を伝えていただければ、理解される方もいらっしゃるし、不安感もかなり軽減されるという状況があるかと思いますので、説明、それから相談については、しっかりと取り組んでいただきたいと考えています。全庁的な運用はどうされるのか、中心はどこで、どのようにとっていかれるのか、区民への情報開示の今後の対応についても、あわせてお聞きいたします。","respondent":"岩田都市環境事業部長","answer":"一般の区民からの問い合わせにつきましても、例えば学校給食のことならば教育委員会、あるいは、保育園の問題であれば保育のほうと、それぞれの質問の分野に応じて、それぞれの専門部署、人体への影響が心配な方については保健センターというような形で対応をしています。","voiceIndex":252,"id":"exchange-113"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひとも、区民の皆様が混乱することのないように、それから、マスコミ等々でも不安をあおり立てているような動きもありますので、そうならないように対策をしっかりととっていただきたいと思います。次に、品川区における特別支援教育について、お聞きいたします。この間、区は、整備を進めてきましたけれども、この設置の考え方、効果をどのように考えられているかを、お尋ねいたします。","respondent":"田村教育次長","answer":"そのような経緯のもと、区においても、品川区特別支援教育検討委員会を、平成１６年１１月に立ち上げまして、品川区として、特別支援のあり方について検討してまいりました。","voiceIndex":254,"id":"exchange-114"},{"speaker":"西本委員","kind":"質問","question":"介助員と学習支援員が設置されているわけですけれども、全介助率という意味では、平成１９年度以前は８０％以上とお聞きしています。この意味することは何なのか、この制度を取り入れて、子どもたちにとって、どのようなメリットがあったのか、また改善すべき課題があるのかどうかについて、お聞きします。それから、ＮＰＯ法人を活用されておりますけれども、その結果について、お聞きしたいと思います。","respondent":"田村教育次長","answer":"ＮＰＯ法人を活用した学習の成果によっても、一人ひとりの実態に応じた必要な支援が適切に実現することができたと、そのようにご理解いただきたいと思います。","voiceIndex":256,"id":"exchange-115"},{"speaker":"西本委員","kind":"質問・要望","question":"小中一貫教育について、以前から要望させていただいて、意見を言っておりますけれども、特別支援教育こそ小中一貫教育が必要なので、進めていただきたいと要望しておりました。それに対まして、この取り組みをどのように考えられてきたのかということを、まずお聞きしたいと思います。","respondent":"田村教育次長","answer":"小中一貫教育としての特別支援教育の取り組みですが、委員ご指摘のとおり、将来の社会参加を見据えて、義務教育９年間の特別支援教育を系統立てて実践することが大切だと考えています。","voiceIndex":258,"id":"exchange-116"},{"speaker":"西本委員","kind":"質問","question":"これらは、私は非常に期待するものと考えています。心配なのは、私立保育園において、就学前を含めて、どういう活用の方法があるのか、お聞きしたいと思います。それから、平成１９年４月に学校教育法が改正されたという動きがあります。それに伴って、国、東京都の動きが変わってくると思いますけれども、それに対する品川区の動きについても、お聞きしたいと思います。","respondent":"田村教育次長","answer":"最後に、やはり国、東京都の動きがありますので、品川区としては、今後は人的な配置を含めて、東京都からの情報を待っているだけではなく、国の動向を見ながら、特別支援について適切な対応をしてまいりたいと考えています。","voiceIndex":260,"id":"exchange-117"},{"speaker":"西本委員","kind":"質問・要望","question":"適正な数については、今後の動向をしっかりと見ていただきたいと考えています。最後になります、保育の質、小学校との連携を進めております。幼保一体化施設、いろいろな施設ができておりますけれども、今後、保育というものをどう進めていくのかということ。それについて、品川区がどのようにかかわっていくのか、などございましたら、最後によろしくお願いいたします。","respondent":"金子子ども未来事業部長","answer":"現在、中間のまとめという段階ですので、全国的な保育園、幼稚園に対する影響は非常に甚大ですので、これについては、今後の動きを注視しつつ、適切な対応をとっていきたいと考えているところです。","voiceIndex":264,"id":"exchange-118"},{"speaker":"大西委員","kind":"質問","question":"私は、品川区議会みんなの党を代表いたしまして、総括質疑をいたします。大きな質問を２項目申し上げます。区民生活の向上、それから、子どもの心の教育についての質問をいたします。そういう高齢者予備軍の方々を、品川区として、どのような形で迎えていくか、品川区に何かお考えがあるのかという点について。それから、高齢者に優しいまちづくりといったことについて、少しお尋ねしたいと思います。","respondent":"日下部企画部長","answer":"高齢者に対する雇用対策です。区のほうといたしましては、これは全国共通でやっている事業ですが、６５歳以上の方に対するシルバー人材センターということで、どちらかというと福祉的な要素も強いのですが、こういう形で対応している。","voiceIndex":267,"id":"exchange-119"},{"speaker":"大西委員","kind":"質問","question":"品川区でよかったと、自分たちは仕事を一生懸命、会社人間でやってきたけれども、ちょっと違う、品川区に貢献ができるという形での仕事の創生というのですか、ぜひ、そういう点も考えていただいて、品川区はおおよそ都心部ですので、かなりのホワイトカラー層もいると思います。経験、知識、いろいろなものがある。こういう高齢者と空き店舗の活用という接点で、何か考えられることはありますか。","respondent":"日下部企画部長","answer":"そういったことも含めて、今後とも、高齢者の雇用とまでいくかどうか、雇用と福祉、どういう形で対応していくか難しい面はありますが、そういう点も含めて、これからいろいろ幅広い形で工夫してまいりたいと考えております。それから、空き店舗の関係です。","voiceIndex":269,"id":"exchange-120"},{"speaker":"大西委員","kind":"質問・要望","question":"あの状態だったら、いっそあれを全部壊してしまって、全部１段目にして７０台置いたほうが効果的であると思うので、その辺の見直しも少し図っていっていただきたいというのが、要望として１点あるのと、その点に関しては、どういうふうに考えるか。ちょっと時代に逆行している考え方があるのではないかと思うんですけれども、この点について、私はぜひ、推進していただきたいと思うんですが、どうでしょうか。","respondent":"岩田都市環境事業部長、片田防災まちづくり事業部長","answer":"学生で、筋力のある人たちが上段に定期利用していただく。原則は、１日貸しの部分は、ラック式ではなくて、ガチャンとはめる形で、全部平置きが原則でやってあります。公営住宅のペットですけれども、住まわれている方はいろいろな方がいらっしゃいますので、原則、ペットの飼育は禁止しています。","voiceIndex":271,"id":"exchange-121"},{"speaker":"大西委員","kind":"質問・要望","question":"区役所の議会棟の前に駐車場がありますけれども、そこの横も２段式の駐輪場なんです。そのために、私も今は筋力がちょっと落ちているために、上段には、自分の手で乗せられないという実情があります。だから、そういうところを見直していっていただきたいということです。今の時代ですから、これから高齢化を迎える高齢者はどしどし増えてくる。","respondent":"桑村総務部長、片田防災まちづくり事業部長","answer":"その意味では、２段の上のほうについては、やはり力のある方にやっていただきたいと思いますけれども、これから、どういうふうな工夫ができるか検討してまいりたいと思います。民間住宅の中では、そういう考え方もありますので、もしそういうご相談があれば、民間の住宅を、関係機関と協議しながらご紹介するということは可能と考えております。","voiceIndex":274,"id":"exchange-122"},{"speaker":"大西委員","kind":"質問・要望","question":"高齢者としては、ペットは家族同様という方々も多くおられますので、少し柔軟な考え方を持って対応していただきますよう、要望しておきます。それからあと１点が、税ですね、むだ使いは、品川区としては当然できないわけですけれども、その状況の中で、昨年１０月３日、区長選挙と区議会の補欠選挙があったわけですけれども、この選挙に要した費用は、どれぐらいあったでしょうか。","respondent":"日下部企画部長、早津選挙管理委員会事務局長","answer":"東京都が水ビジネスということでいろいろ売り出しておりますが、これは、東京都の水道事業と、ある意味で、民間のいろいろなそういう浄水関係の技術というものを、うまく融合する形で。昨年の区長、区議会議員補欠選挙ですが、１億１,６００万円余です。","voiceIndex":277,"id":"exchange-123"},{"speaker":"大西委員","kind":"質問","question":"東京都の水ビジネスに関しては、単なるひとつの例として挙げたことであって、品川区でも、何らかの研究というのですか、考えてみる余地はないかなと思いました。それから、１億数千万円の税金を使って行ったという区議会議員補欠選挙、区長選挙ですけれども、補欠選挙をなくして、区長選挙と区議会本選挙を同時に行えば、その１億１,６００万円は浮くという考え方でよろしいですか。","respondent":"早津選挙管理委員会事務局長","answer":"区議会議員補欠選挙と区長選挙がなくて、４月の区議会議員選挙と同一にやればという仮定の場合に、どうなるかですが、その場合には、１億１,６００万円の執行は必要なくなるということになります。","voiceIndex":280,"id":"exchange-124"},{"speaker":"大西委員","kind":"質問","question":"ということは、法改正をしなくても、やろうと思えばやれると。それによって、１億円あたりの金額が浮く可能性があるという認識でいいですか。","respondent":"早津選挙管理委員会事務局長","answer":"いろいろなケースがあろうかと思いますが、そういうようなことが起これば、金額的には、ある程度浮いてくるということになります。","voiceIndex":284,"id":"exchange-125"},{"speaker":"大西委員","kind":"確認","question":"わかりました。ちょっと確認しておきました。続いて、心の教育について、ちょっと時間がありませんので、はしょっての質問になるかと思いますが、お許しください。今回の３.１１の震災を受けて、品川区では、子どもたちが、小中学校においては、何らかの形のボランティアみたいなことは行われたのでしょうか。","respondent":"田村教育次長","answer":"やはり今回、３.１１以降、小学校、中学校それぞれ作品をつくって、被災地に送ったり、あるいは、募金活動をしたり、ＰＴＡと合同でやったり、さまざまな学校の取り組みが、今回の被災にあたってとり行われたです。","voiceIndex":286,"id":"exchange-126"},{"speaker":"大西委員","kind":"質問","question":"日光の光林荘で、品川区から行かれたリーダーの方がおられるような感じなんですけれども、これは、小中学校の生徒ということでいいですか。その関係で、ひょっとして子どもたちは行けない年に当ってしまったのかと思うんですけれども、もしそういう形であれば、後々、どういう対応をなされるのか、教えてください。","respondent":"田村教育次長、金子子ども未来事業部長","answer":"今回、日光光林荘に富岡町の被災者を受け入れましたので、その間、そこを使えませんでした。小学校は箱根に１泊２日で行ったということと、中学校のほうは、今回、中止ということで、来年にやるということになりました。お尋ねの件は、富岡町の小中学生を日光林間学園に招待して、そのときに、品川区からもジュニアリーダー教室の中高生が参加したという件かと思いますが、その件に関しましては、この中高生についてはボランティアで参加したです。","voiceIndex":288,"id":"exchange-127"},{"speaker":"大西委員","kind":"質問","question":"英語教育においての、英語検定の位置づけというのですか、この点に関してはどうなっているのか。それから、もししっかりやっているのであれば、英語検定の成果を教えてほしいということ。千代田区では、都立九段高校を区立にして中高一貫を行ったと思うんですけれども、その点について、小中一貫校との違いとか何かあれば、ちょっと教えてもらえますか。","respondent":"田村教育次長","answer":"英語検定の位置づけですが、各学校、重要なテーマであるのですけれども、それぞれ各学校の取り組みとして、積極的に受験するようにということで取り決めておりまして、３級を目指している。ほぼ半数の学校が参加しているです。","voiceIndex":291,"id":"exchange-128"},{"speaker":"大西委員","kind":"質問・要望","question":"英語検定に関してですけれども、小中一貫教育に変えて、それから後に、３級レベルを目指したのであれば、その成果としては、どういう形のものが出ているかということを教えていただきたい。そういったことに対して、子どもたちが自主的に、要らなくなった冬物の洋服だとか、そういうものを送るという教育もあっていいのではないかと思うんですが、その点は、もう何か配慮はされていますでしょうか。","respondent":"田村教育次長","answer":"小中学校でのボランティアで、洋服というような話ですが、実際には、小中一貫校で制服があったりすると、卒業したものを、保護者も協力して、新たなものを買わないで利用できるものは提供して、使えるものは使っているということをやっていますので、この辺も。","voiceIndex":293,"id":"exchange-129"},{"speaker":"大西委員","kind":"質問","question":"英語検定の３級が５０％ぐらいの合格率というのは、ちょっと低いのではないかなという気がしております。これは、心の教育という点からして、１カ月にたった１回の食事を白米と梅干しにすることに、その意義を持って、親が反対するということはないのではないかと考えるのですけれども、いかがでしょうか。","respondent":"田村教育次長","answer":"款別審査のところでもありましたが、給食は、やはり栄養のバランスも含めて実費負担でやっていますので、そこを白米と梅干しにして浮かせて、被災地にというのは、若干考え方の基本的なところがあれかなと。","voiceIndex":295,"id":"exchange-130"},{"speaker":"大西委員","kind":"質問","question":"そのためには、ちょっとぐらいといいますか、今まではこうだからとか、文部科学省の方針がこうだからということではなくて、食事を１食、白米に変えたことは天地がひっくり返るようなことでも何でもない。私は、１回そのことをやれば、自分たちができることがあるんだということを、子どもたちの心の中に教えていくんだということだと思います。これをもちまして、私の総括質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":297,"id":"exchange-131"},{"speaker":"須藤委員","kind":"提案","question":"しかしながら、我が会派の委員が、決算審議において各款別審査や総括質疑で提案させていただいたように、東日本大震災後の防災に対する課題の対処、平塚橋会館を例に挙げたように、少子高齢化が進む品川区において、品川区の人口動態を見据えた区有施設のあり方の検討、景気低迷が続くと予測される中で、観光都市品川と絡めた商工業への支援の充実、きめ細やかな障害者福祉の施策への充実。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":300,"id":"exchange-132"},{"speaker":"武内委員","kind":"提案","question":"品川区議会公明党を代表して、意見表明をいたします。以下、その理由について何点か、要望を含めて申し上げます。最後に、本決算特別委員会にて、我が党の委員が提案、要望した防災対策、高齢者、障害者への福祉施策、環境、経済、人権、教育などの施策に対する意見を、来年度の予算編成をはじめ、区の各事業に十分に反映されますよう、要望いたしまして、意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":302,"id":"exchange-133"},{"speaker":"稲川副委員長","kind":"提案","question":"原発事故に伴い、区内でも放射能汚染の不安が広がる中、我が会派からの要望にいち早く対応されたことは高く評価しますが、さらなる計測の充実と、内部被曝リスクの軽減のためのきめ細やかな対応を求めます。最後に、我が会派が本委員会において指摘、提案した各項目を真摯に受けとめ、平成２４年度予算編成や、今後の施策に反映されるよう要望いたしまして、民主・改革ネットの意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":304,"id":"exchange-134"},{"speaker":"南委員","kind":"質問・要望","question":"こんなときだからこそ、区民に身近な自治体として、生活を根底から支える対策が求められますが、区はまず自助だと強調して、公助を最後に置き、受益者負担を各分野に徹底、自治体の役割を投げ捨てています。区民の不安に応えて、とりわけ子どもの集まる施設、給食、食材など、徹底した測定を求めます。大規模にこだわらずに、小規模でもつくるよう、改めて求めます。区民要望に積極的に応えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":306,"id":"exchange-135"},{"speaker":"須貝委員","kind":"質問・要望","question":"平成２２年度品川区各会計決算に対する、無所属品川の意見表明をします。無所属品川は、平成２２年度品川区一般会計、国民健康保険事業会計、老人保健医療特別会計、後期高齢者医療特別会計、介護保険特別会計の各歳入歳出決算を認定します。首都直下型大地震の発生が盛んに叫ばれている中、品川区は区民の生命、財産、健康を守るために、万全な備えを早急に構築すること、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":308,"id":"exchange-136"},{"speaker":"吉田委員","kind":"提案","question":"怠りない防災対策を、今後も長期的な展望で進めるよう求めます。本決算特別委員会にて、我が会派委員が提案、要望した、ひとり暮らし高齢者の福祉をはじめ、新生児訪問や子どもたちや車いすの方に優しい公園バリアフリー、また小中一貫校を進める中、おもいやりの学校教育や近隣セキュリティシステム強化等を取り上げることを期待し、よりよい区民生活の向上を要望いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":310,"id":"exchange-137"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1352#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":127863,"voices":316}},{"id":"h23-20111027-8","meetingId":"h23-cm10","date":"2011年10月27日","dateIso":"2011-10-27","committee":"建設委員会","time":"午前１１時００分～午後３時２７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"を行います。 (1)ウォームビズキャンペーンの実施","agenda":"を行います。 (1)ウォームビズキャンペーンの実施","exchanges":[{"speaker":"井上委員","kind":"確認","question":"もうウォームビズキャンペーンも何年かされているというふうに思いまして、私も決算特別委員会で発言していますけれども、温暖化防止プロジェクトでリーフレットとパンフをつくるということですけれども、もうそろそろこの周知方法を広報しながわとかホームページで十分ではないかというふうに思うんですけれども、これにかかわる経費はどのぐらいかかっているのかということを確認させてください。","respondent":"野呂瀬環境課長","answer":"経費というのは、ほとんど印刷代だけです。金額は後ほど。","voiceIndex":5,"id":"exchange-001"},{"speaker":"井上委員","kind":"意見","question":"これは助成金が出ているから使えているということではないと思いますので、ちょっと内部で検討していただければなという、これは意見です。","respondent":"野呂瀬環境課長","answer":"今の意見、検討します。それと、ポスターの作成ですけれども、ポスターが８万９,０００円です。それと、リーフレットは印刷代として１１万円です。","voiceIndex":9,"id":"exchange-002"},{"speaker":"中塚副委員長","kind":"質問","question":"このウォームビズキャンペーンの実施ですけれども、福島第一原発事故との関係はあるのか、どうなっているのか伺いたいのと、あと、冬の電力について、政府から今どういう話があるのか、見通しているのか、その点をご説明いただけますか。","respondent":"野呂瀬環境課長","answer":"それと、今後の政府の見通しというのも、一応、ウォームビズキャンペーンにつきましては夏の電力供給等々で、今後も引き続き節電にご協力ということは伺っておりますけども、あくまでもこれは地球温暖化、私どもでやっている地球温暖化対策地域推進計画に基づきまして、独自で。","voiceIndex":12,"id":"exchange-003"},{"speaker":"大沢委員","kind":"意見","question":"先ほど経費云々の話がありましたけれども、役所に訪れる方を見ると、比較的年齢の高い方がいるということで、確かにペーパーレスで云々という話もありましたけれども、それは情報弱者、ホームページ等々が見られない方にとっては、やはりこういう印刷物は大事なものだと思いますので、先ほど検討されるということのお話がありましたが、そこのところのお考えはありますか。","respondent":"野呂瀬環境課長","answer":"ペーパーレスということは考えておりません。あくまでも、周知につきましては電子、それとペーパーももちろん用いながら、効率的に、あまりまかない程度に考えております。","voiceIndex":14,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問・要望","question":"ちょっと今、あいまいもこたる表現なのですが、必ずしもこれ、ペーパーレスでいいということではないと思うので、ここのところはしっかりと、そこの費用と効果を考えながらやっていただきたい。いたずらにこの経費を云々ということではないと思いますので、そこのところはしっかりと考え方を中心に据えながらこの取り扱いをお願いしたいと思うんですけれども。","respondent":"岩田都市環境事業部長","answer":"ですから、一番有効な媒体として、当然、紙媒体も含むわけですので、さまざまな区民、３５万人いらっしゃいますので、できるだけ１人もわからないという方がいらっしゃらないような広報を心がけておりますし、また、一方で、ＩＳＯの関係もありますので。","voiceIndex":16,"id":"exchange-005"}]},{"id":"topic-02","title":"環境経営セミナーの開催","agenda":"環境経営セミナーの開催","exchanges":[{"speaker":"武内委員","kind":"意見","question":"このセミナーは、定期的に何かやっていたかどうかということと、あと、今後、どんな感じで、単発なのかどうか。それから、この講師の選定というのは、やっぱり環境課が中心になって選定されるのか。今、大体説明があったのでそういう事情だと考えていますが。それと、あと、この予算はどうなっているのかについてです。","respondent":"野呂瀬環境課長","answer":"ただ、これはセミナーということで、シンポジウムとか、そういうのをやったときということを考えておりまして、大体１人当たり１０万円ぐらいの予算で５人までというふうに考えておりましたんですけれども、今回、１０万円と１５万円ということでさせていただきました。","voiceIndex":22,"id":"exchange-006"},{"speaker":"武内委員","kind":"質問","question":"わかりました。せっかくやっていただくので、来ていただいた方に、アンケートなんかとるんでしょうけれども、これだけ効果があったよみたいなものを把握するような仕組みみたいなものはあるんですか。","respondent":"野呂瀬環境課長","answer":"当然、ただ聞いていただくだけじゃなくて、感想とか、アンケートをとりまして、後日、来年度に向けて、よりよいものをやっていく参考にするような形で考えております。","voiceIndex":24,"id":"exchange-007"}]},{"id":"topic-03","title":"第２２回東京都道路整備事業推進大会","agenda":"第２２回東京都道路整備事業推進大会","exchanges":[{"speaker":"中塚副委員長","kind":"質問","question":"あわせて、この三環状道路ですけれども、大震災が起きた今、こういう大型のプロジェクト、公共事業は復興財源に充てるべきだと、そういう意見も強くなっていますけれども、その点についてどのようにお考えなのか伺いたいなと。","respondent":"松代都市計画課長","answer":"都心を通過する車を三環状で回すことによって、環境面へも大きく配慮する。日常、区内道路等に影響しています渋滞等をそういったことでなくすと、いろいろな効果を生み出す意味でも、この三環状道路等は必要だろうというふうに考えているところです。","voiceIndex":31,"id":"exchange-008"},{"speaker":"中塚副委員長","kind":"質問","question":"近くに小学校があるところは、子どもへの影響がどうなるか、排気ガスの影響も心配されています。さらに、この東日本大震災が起きた今、こうした事業を果たして進めるべきかと新たな問題も上がっております。大震災が起きた今、この予算は復興財源にこそ充てるべきだと、こうした声について品川区はどうお考えなのか、改めて伺いたいと思います。","respondent":"松代都市計画課長","answer":"東日本大震災における復興に関係した政策判断ですけれども、その復興は復興として、国が中心となってやはり考えるべきであると思いますし、我々の立場としましては、やはり区民の安全・安心、防災を守る意味、そういった広い意味からも、我々の役割を統率する幹線道路。","voiceIndex":33,"id":"exchange-009"}]},{"id":"topic-04","title":"平成２３年１１月都営住宅（世帯向・単身者向住宅等）の募集","agenda":"平成２３年１１月都営住宅（世帯向・単身者向住宅等）の募集","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"きゅりあんから、今度変わったということで、きゅりあんのほうの事情ということで、区の都合ということではないのか。それと、今後もきゅりあんはもうやらずに、区のほうでということなんだということですね。今まできゅりあんでやっていたということなので、その方たちが間違えないような形で対応していただきたいと思うんですけど、どんな感じで考えておられますか。","respondent":"柏原住宅担当課長","answer":"休日の窓口の変更ですけれども、きゅりあんのほう、正確にいいますと男女共同参画センターの前にあります、多目的のお部屋といいますか、そういうところがございまして、実はここ、予約で占有的にとるということができないお部屋だったということで。","voiceIndex":40,"id":"exchange-010"},{"speaker":"武内委員","kind":"意見","question":"個人的には区役所のほうがいいのかなという気はしているんですけれども、そういう面では今回そういうふうになったので、その経緯が、例えばきゅりあんのほかの部屋を借りるという選択肢もあった、あるいはないかについては、あったけれどもこういうふうにしたのか、それとも、もうそういう使い方はやめてくれという、使い方自体がだめだという、今まで予約をとらずにやっていたという、その辺。","respondent":"柏原住宅担当課長","answer":"ちょっと説明が足りなくて申しわけございません。","voiceIndex":42,"id":"exchange-011"},{"speaker":"武内委員","kind":"質問","question":"道路の工事の人が２人ぐらい立ってました。これをどのようにしてやっていくのかということも含め、頻繁にあるものじゃないとは思うんですけれども、こういうことを機に、きっかけとして、ガードレールの安全、強化というんですかね、もうちょっと柱を小まめに入れたほうがいいんじゃないかなと単純に思ったんですけど、その辺はどうでしょうか。","respondent":"稲田道路公園課長","answer":"それと、反射板での表示、警戒標識みたいな、あるいは張りつけてやるのかどうか、その辺も現在、検討しながら工事は進めていきたいと考えています。","voiceIndex":49,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4020#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":10951,"voices":51}},{"id":"h23-20111107-6","meetingId":"h23-cm11","date":"2011年11月7日","dateIso":"2011-11-07","committee":"区民委員会","time":"午後０時５９分～午後２時４５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"を行います。 はじめに(1)の平成２３年度地域貢献団体感謝状贈呈式","agenda":"を行います。 はじめに(1)の平成２３年度地域貢献団体感謝状贈呈式","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっと２点ほどなんですけれども、細かいところで、奨励品というのはどんなものなのかと伺っておきたいということと、あと選考の基準について知らなかったものですから、教えていただきたいと思います。","respondent":"今井協働・国際担当課長","answer":"選考の基準につきましては、こちらの要綱に定めがあるところで主なものを申し上げますと、地域の連携や活性化に寄与し、地域の課題解決につながること。それから活動が継続的で、おおむね四半期に１回程度以上、通年活動していること。","voiceIndex":5,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"意見","question":"区の表彰審査会の場合ですと、選考基準というのが明確になっているんですけれども、今の説明ですと何かかなりその基準に沿った中から区のほうで選んでいくというふうな、区の判断といいますか、その辺が入ってくるかなと思うんですけれども、そこら辺のことがどういうふうになっているか。それとあと、２９団体のうち２４団体なんですけれども、すると５団体がどういうことで駄目になったのか。","respondent":"今井協働・国際担当課長","answer":"こちらは確かに選考の際は区のほうで選んでいくんですが、もともとこの地域貢献の考え方が、地域でふれあいサポート活動などを実施している中で、なかなか地域で活動していらっしゃる方に感謝の気持ちをお伝えする場がないということで、町会・自治会や地域センターなど。","voiceIndex":7,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"意見","question":"今回、出された一覧のところで出ている団体そのものが、区の方針じゃないですけれども、やはり表彰する、あるいは感謝状を贈呈するということになりますと、やはり一定の明確な基準といいますか、私はそれをしっかり持って、今の説明ですと１町会１団体とか、そういうことであればそういうしっかりした基準というもの、その基準がいいかどうかということも含めてというのがあるんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"}]},{"id":"topic-02","title":"の平成２３年度協働事業提案制度の審査結果","agenda":"の平成２３年度協働事業提案制度の審査結果","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"目的などはもう十分理解できるんですけれども、この選定していく作業の中で、ここにも書かれています町会・自治会、ボランティア団体、ＮＰＯ、商店街、公益法人等々、どの団体でも大丈夫というようなことだと思うんですけれども、それで採択をされている方を見てみますと、区政協力をする新規の団体であったり、既存の区政協力の団体であったりすると思うんですけれども。","respondent":"今井協働・国際担当課長","answer":"こちらの国保医療年金課につきましては、今、想定しているのは健康づくり推進委員ですとか、地域の医師会などとの連携を考えておりますし、高齢者福祉課につきましても、高齢者福祉課が既に持っています在宅支援センターなどの地域の資源を活かしながら。","voiceIndex":15,"id":"exchange-004"},{"speaker":"本多委員","kind":"提案","question":"それで、あともう一つ聞きたいのが、採択事業(1)の最初に書いてあるところに、提案団体がＪＴＢコミュニケーションズと株式会社ルネサンス、２つ出ているんですが、この取り組みというのは、歩調をとって１つのことをやっていくのか、それともまた個別に別々で取り組んでいって、いい意味で切磋琢磨みたいな感じなのか、その辺ちょっと教えてください。","respondent":"今井協働・国際担当課長","answer":"ルネサンスは全国で介護予防のイベントを実施しているとともに、国や厚生労働省などの実際の健診率向上プロジェクト委員にも入っておりますので、そういう中で全国的な介護予防の状況を把握しながら、連携して実施していくものと期待しております。","voiceIndex":17,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"それと、買い物支援事業というのは具体的に何をやるのか、その中身がよくわからないんです。そこの落ちてきている、要するに健診の仕組みが変わったわけですよね。それが、非営利のところに頼まなきゃいけないというか、そうなるとまたちょっと仕組みとして何かおかしいかなという感じもするんですけれども、そこら辺はどうなんでしょうか。","respondent":"今井協働・国際担当課長","answer":"ただ、今後６５％という国の基準を満たしていくためには、もう２年しかない中で、はっきり言えば倍増に近いところでやる中で、やはりなかなか所管と今までの既存のスペックではできないもので、実際に福岡市などで受診率を向上させてきたこの団体と一緒に連携することで。","voiceIndex":19,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"これはこれでこういうふうにやったというので、その成果がどうなるのか。今でさえ、区のほうから電話が来ても何か「えっ」というふうな声も聞くんですけれども、今度はこの人たちはどういう立場で電話するんでしょうか。「ええっ、できるの」と何かしつこくそんな思いなんですけれども、要するに自分たちがやって町会とかにお願いするのに、本当に、やれるんですか。そこのところを伺いたいと思います。","respondent":"今井協働・国際担当課長","answer":"地域の方は確かに素人ですが、地域の方々自身がこれのＰＲ者にならないと、地域の方々が本当にわかっていただかないと、いくらそれ以外の対象者じゃない方に言われても難しいと思いますので、この仕組みづくりと申しましたのは。","voiceIndex":21,"id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問","question":"最後の１点なんですけれども、健診は６５％行かないと、いわゆるペナルティーというか、そういうのが実際課せられるということなんですけれども、今のお話ですと、一方ではそういう６５％行かないとペナルティー、ところがその事業者には５０％でいいと述べたわけですよね。どうしてなんでしょうか。","respondent":"今井協働・国際担当課長","answer":"ただ、取り組みの閾値としては、１５％行けば、１年間の事業としては一定の事業効果があったものとしてみなせるんじゃないかというのが区の考え方です。","voiceIndex":23,"id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問","question":"最後１点なんですけれども、例えば今の健診率の向上のところでは、区のほうでは予算的にはどういうふうになっていくんでしょうか。それとあと、さっきの個人情報の関係、実際にこの会社のほうが直接電話をかけたりするものじゃないという話なんですけれども、そういうところは個人情報というのはしっかり守られているのかどうなのかも、あわせて伺いたいです。","respondent":"今井協働・国際担当課長","answer":"２点のご質問です。１点目は健診率向上に向けました区の予算ですが、これは、今、政策予算の中で審議されていくものですので、予算査定の中で。","voiceIndex":25,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"提案","question":"そうすると、今、提案団体、ここにお願いするというのは決まったけれども、じゃあ、それをやる上での幾ら予算をつけていくかというのは、これからだということなんですか。","respondent":"今井協働・国際担当課長","answer":"政策予算です。","voiceIndex":29,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"それは条件とか、何か大体このぐらいだろうというのはあるんでしょうか。もしかして、これをやるんだったらこれだけなんて、どんどん青天井に行くんでしょうか。そんなことはないと思うんですが。","respondent":"今井協働・国際担当課長","answer":"区の予算は青天井でございませんので、こちらのほうの提案事業は、この課題を提案した所管課から政策予算として協議の上していくもので、さらに企画の査定などを通りましてから、政策の中で予算としてこちらのほうで提案してまいります。","voiceIndex":31,"id":"exchange-011"},{"speaker":"藤原委員","kind":"意見","question":"そして結局は受診率を上げていきましょうというだけなんですよね。もう具体的に。ただ協働とかになってしまうとすごい施策かなと思うけれども、結局もうできないから、これで頭打ちだから、民間のノウハウを持っている人のところのお力をかりて、きれいな言い方で協働という形にして、受診率を上げていきましょうという施策の一つであると思っていますので、それでいいんですよねということが１点。","respondent":"今井協働・国際担当課長","answer":"もう一点目、この３０％台になる根本的原因。こちらのほうを、今、私のほうが申しわけありません。説明の中ではきちんと所管のほうで説明されていたかもしれないんですが、ちょっと私のほうで、今、きちんと説明できなかったのは大変反省しております。","voiceIndex":33,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"安心しまして、区と区民の協働の前に、区組織の協働、よく言われるじゃないですか。縦割りと言われますよね。１年目は５０％、最終的には６５％ぐらいに上げていきたいという目標があるわけですから、やはりそこの原因。でも、課長は大分ご存じみたいだったのですごく安心しまして、これからも区民のために、各課が協働連携してやっていっていただきたいことを切望して、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-013"}]},{"id":"topic-03","title":"喫茶コーナー（こみゅにてぃぷらざ八潮）の運営団体の決定","agenda":"喫茶コーナー（こみゅにてぃぷらざ八潮）の運営団体の決定","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"もう一つ、今後は朝食・昼食の提供を視野に入れたというふうになっているんですけれども、ここら辺の具体的な見通しというか、そこら辺はどういうふうになっていくのかなというのがあるんです。ですから、今、視野に入れたというように聞くんですけれども、そこら辺の見通しというのはどうかなと思っているんですけれども、どうでしょうか。","respondent":"今井協働・国際担当課長","answer":"２点目の免除になった考え方ですが、こちらは、今、委員もご指摘ございましたとおり、あちらの施設は、それこそ昔で言えばレストランもありましたけれども、そちらも撤退されたように、なかなかあそこを事業として。","voiceIndex":41,"id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問・要望","question":"それとあと、今、八潮じゃなくて町場のほうでは弁当なんかの配達も一部やっているところもあるので、そういうところも視野に入れて、そこまで展開できればと思っていますけれども、これは今の説明ですと、１２月ぐらいから食事のほうもというお話ですけれども、ぜひそちらの弁当等のほうも考えていっていただければなと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-015"},{"speaker":"山元委員","kind":"質問・要望","question":"本当に食事を朝からというのは、今、お年寄りのご飯食べない人がとても多いので、それは歓迎、ＯＫなんですが、これ、午前９時半から午後６時半までずっとやるということなんですが、現実的にお茶から今度ご飯になった場合、まだもうちょっと先の話なんでしょうが、人数的に何人ぐらいでおやりになって、実際、いくらボランティアといっても、なかなかそういう運営というのはどうなのかなという。","respondent":"今井協働・国際担当課長","answer":"先ほどこちらの団体は構成人員が多い上に、先ほどの養成講座などでいろいろ育ててきたサポーターもいらっしゃいますので、考え方としては、毎日３人程度が詰めるという形で、１名の方は完全に同じ方が常勤で詰めると聞いておりますので、運営体制と事業内容と。","voiceIndex":44,"id":"exchange-016"},{"speaker":"山元委員","kind":"質問","question":"もう１点なんですが、９時半から夕方６時半というのは、ある程度何人分とかって決められた何か、ある程度その辺を決めて目標というかやっていく予定ではないんでしょうか。その辺ちょっと教えていただければと。","respondent":"今井協働・国際担当課長","answer":"俗に言う営業の損益分岐点というのは、やはり原材料費をどのくらいかけるかというのと、あと人件費にかかってきておりますので、なかなかその先ほど言ったイベントで人がいっぱい集まっているときには、それこそいろいろなもの。","voiceIndex":46,"id":"exchange-017"},{"speaker":"山元委員","kind":"質問・要望","question":"やはり、地元の方たちにもかなり、すごく、知れば期待をして来ると思うんですが、最後に周知の方法といいますか、その辺はどういうふうになっているのか、最後教えていただきたいと思います。","respondent":"今井協働・国際担当課長","answer":"オープン後は区の新着情報に載せていったり、あとは逆にこれから協働推進室のおたよりにもなるんですが、私たちの協働推進の活動拠点に入っている人たちが一緒にニュースをつくっておりますので、そのニュースを自治会回覧板に挟み込むように、１１月に手配しております。","voiceIndex":48,"id":"exchange-018"},{"speaker":"藤原委員","kind":"質問・要望","question":"結局多様な広域活動の活性化というのがシルバー大学とかそういうのを示していて、そして地域の活性化というのは八潮の地域の方が来てくださいみたいな形でとればどうでしょうか。","respondent":"今井協働・国際担当課長","answer":"地域の活性化につきましては、今はまずは身近な八潮と考えておりますが、区民活動という点では、こちらは区内全域の地域活動の拠点と考えておりますので、そういう意味では協働推進室を中心に区内全体の区民活動の拠点となるよう、さらに努力してまいります。","voiceIndex":50,"id":"exchange-019"},{"speaker":"藤原委員","kind":"提案","question":"私も、今、この提案を伺って想像すると、あの八潮のあそこの場所が人でごった返していることがものすごく想像されると思うので、これからもまた報告のときに、あふれんばかりの人が来てくれるという報告が来ることを願いつつ、頑張ってください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-020"},{"speaker":"石田副委員長","kind":"質問","question":"それが１点と、以前も、これ、募集をかけて、決定がされて、撤退をされたと。そのときに、このみんなの食育は参加をされたのか。なぜ今回、１団体が撤退された後に非常に厳しい状況下の中で、なぜここが手を挙げたのかという、その理由がもしわかれば教えていただければと思います。","respondent":"今井協働・国際担当課長","answer":"ただ、団体としましてもいろいろな大きな絵を描いておりますので、最初から区としては大きな絵を動かすよりも、徐々にお客様を広げたほうがいいですよというアドバイスはさせていただいていたり、私どもでとりましたアンケートなどを実際に提供して。","voiceIndex":53,"id":"exchange-021"}]},{"id":"topic-04","title":"有印公文書偽造による融資あっ旋の被害","agenda":"有印公文書偽造による融資あっ旋の被害","exchanges":[{"speaker":"藤原委員","kind":"意見","question":"改めて聞きたいんですけれども、この融資あっ旋を受けるときに、許認可とかを受けているところは、その文にありますよね。それの証明書のコピーを持ってきてと。ほかのところは大丈夫ですよね。","respondent":"福島ものづくり・経営支援課長","answer":"今回こういうふうに摘発されたことによりまして、偽造しますとこういう逮捕されると、大変重い刑罰に、１年以上の拘留になりますので、そういったことがよく皆様にも理解されたのではないかと考えております。","voiceIndex":64,"id":"exchange-022"},{"speaker":"沢田委員","kind":"確認","question":"そうすると、この認定証を一応提出していただいていたというのは、いちいちその提出されたものは確認しなくて、それを見てＯＫということ。もしあれだったら、これからそういうことがあったということは、それが提出された時点で警察にちゃんとＯＫが出ているのか確認してとか、そういうことはないのか。","respondent":"福島ものづくり・経営支援課長","answer":"やはりそういう偽造ですとか、そういうことをやられると、今回のような形で摘発されるんだということでしか、うちのほうでは多分できないだろうと思います。","voiceIndex":66,"id":"exchange-023"},{"speaker":"沢田委員","kind":"確認","question":"再発防止のために、今後もいちいち確認もやはりしないということですか。そういう意味では、認証というか、その警備業法に基づく認定証を出してもらっているところには、そういう認定証確認をしたほうがいいんじゃないかなと思います。","respondent":"福島ものづくり・経営支援課長","answer":"その認定証が正しいかどうかを１つ１つ、やはり東京都の公安委員会にうちの公文書を持って、これが正しいですかというふうに聞くというのは、やはり時間もかかってしまいますので、かなり難しいことだろうと考えています。","voiceIndex":68,"id":"exchange-024"},{"speaker":"沢田委員","kind":"質問・要望","question":"こういうことがあった以上、やはり確認できる部分はできるだけ、手間がかかるにしても、警備会社はたまたまこの警備業法で認定証というのをもらっているからそれの提出を求めているわけで、そんなに全部の会社が何か認定をもらっているわけじゃないと思うので、数もそこまで多くないかと思うんですけれども、やったほうがいいのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-025"},{"speaker":"石田副委員長","kind":"質問","question":"ただ、例えば申請のときに原本を持ってきて１回見ると。原本をコピーするというのはなかなか難しいと思うので、そこは抑止力になるのかなと思うんですが、改めてこういった事件が発覚した中で、そういったことをやっていくのか、区としての考えがあるかお伺いします。","respondent":"福島ものづくり・経営支援課長","answer":"あるいはコピーすら、とっていないところもあるというふうに聞いていますので、今後検討もさらにしていきますけれども、元本確認ができるかどうか、その辺については十分検討しながら考えていきたいと思います。","voiceIndex":71,"id":"exchange-026"},{"speaker":"石田副委員長","kind":"質問・要望","question":"なので、私はこういった事件があったということは、やはり再発を防止していかなきゃいけないので、そういったい意味で、やはり区としてはしっかりとした態勢で、そういった融資あっ旋を臨んでいただきたいんですが、検討されるということですから、改めてそこはやっていただかないと、税金でやられているわけだから、そこはしっかりと区の態勢を求めますけれども、いかがでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"確かにそれはありますし、どういうふうにやったらできるかというのは検討はしてみたいとは思いますけれども、この融資あっ旋のあっ旋自体は品川区が行いますけれども、さらにこの先は銀行、ならびに信用保証協会のほうで、実際、融資を実行するかどうかの審査も入ります。","voiceIndex":73,"id":"exchange-027"},{"speaker":"石田副委員長","kind":"質問","question":"ぜひ、よろしくお願いをいたします。それと、今回こういったことが警察のほうから捜査で発覚をした中で、今、多くの企業が融資を受けていると思うんですが、じゃあ、今まで受けてきたこのコピーはあるわけですよね。もう一回チェックを実際したのか、する予定があるのか、その辺をちょっと教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"する予定もございません。やはりこの認定証を持ってきてもらうというのは、その仕事が成立しているかどうかを確認するだけですし、またそれ以外でも、確定申告票の写しを出してもらったりですとか、あるいは税金のほうの納税証明書、さまざまな書類を出してもらっています。","voiceIndex":75,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"地域活動課長の今のお話の中で、転入してきた方にというお話でしたが、実際品川区の中に住んでいらっしゃる方でも、もう町会・自治会に入らない方が多いわけじゃないですか。その理由を地域活動課として押さえておかなくてはいけないと思うんですけれども、具体的になぜ町会に参加しないのか、自治会に入らないのかということを押さえていると思うので、その辺をお願いします。","respondent":"武内地域活動課長","answer":"町会そのものの活動について、まだまだ理解できないで、何をやっているんだというような部分も多分にあるのではないかと。","voiceIndex":82,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"入る入らないは個人の自由で、なるほどなと思ったんですけれども、入るきっかけがないと、今、おっしゃいましたね。何かこういうきっかけづくりになるということですね。じゃあ、出会いづくりと同じで、そういうのも町会とそこに住んでいる区民との出会いづくりというふうに考えればいいんでしょうか。","respondent":"武内地域活動課長","answer":"ええ。そのような委員が言われるとおり、私もそういうふうに考えているんですけれども、それを打破するために、例えば１つの方策として、従来からワンルームマンションを建設する際、住宅の建築確認申請が出てきます。","voiceIndex":84,"id":"exchange-030"},{"speaker":"石田副委員長","kind":"質問","question":"このパンフレット、先ほど年間の転入の数を示していただきましたが、パンフレットは何部作成をされたんでしょうか。","respondent":"武内地域活動課長","answer":"とりあえず、当面３,０００部ということで作成しています。","voiceIndex":86,"id":"exchange-031"},{"speaker":"石田副委員長","kind":"意見","question":"先ほど２万件、３万件の方たちが転入をされている中で、３,０００部というのは、それはすぐに皆さんにお配りをしたと考えれば、それこそ一月、二月でなくなってしまうわけですよね。今回、こういったものを本来は町会単位でやるのを、区として町会に加入してもらいたいという思いで統合チラシをつくったと思うんですが、それでは３,０００部でいいのか。その配布方法をお聞かせください。","respondent":"武内地域活動課長","answer":"これは高級な紙で印刷しているのは３,０００部ですけれども、もちろんこれは手づくりで庁内印刷で幾らでも印刷できますので、その辺は今回初めてですので、これで完璧だという部分なのか、あるいはまた町会の役員や何かに聞いて。","voiceIndex":88,"id":"exchange-032"},{"speaker":"石田副委員長","kind":"意見","question":"３,０００部と聞いて、実はちょっと安心をしたというか、これを見たときに、いろいろと改善の余地があるのかなというふうに見られます。その地域活動課で今回ご報告いただきましたけれども、これは転入という部分に関しては戸籍住民課がそこの一番の窓口ですので、その辺のかかわり合いというか、関係性はどのように連携をしていくのか、お知らせください。","respondent":"武内地域活動課長","answer":"さらに各地域センター単位で、地域センターのその関連する町会等のパンフレットを各地域センター単位でつくっておりますので、それも合わせて配布して町会の加入の促しをしていまして、希望によってはその場で受付をするという対応をとらせていただいています。","voiceIndex":90,"id":"exchange-033"},{"speaker":"石田副委員長","kind":"質問","question":"１点だけ。これはなぜ横浜市のところに事務局があるんでしょうか。これは主催しながわ観光協会ですよね。その点が。これは電話番号も、申し込みのあて先も横浜なんですよね。これはなぜ横浜にその事務局が置いてあるのか、お知らせください。","respondent":"米田商業・観光課長","answer":"受付業務につきましては東急電鉄のほうで行っていただいている。そちらの事務局が横浜にあるものですから、一般的な問い合わせにつきましてはそちらで行っておりますが、当然観光協会等でもこちらに関するお問い合わせをいただきました場合には、お答えはしています。","voiceIndex":96,"id":"exchange-034"},{"speaker":"石田副委員長","kind":"質問","question":"わかりました。東急電鉄の協力のもとにやられているという中で、せっかくしながわ観光協会が大井町にできたわけですから、ぜひその部分を、これは主催がしながわ観光協会ですよね。せっかくすごい反響があるイベントですので、これはしながわ観光協会のアピールとしても私はいいのかなと思うので、その点ぜひ今後配慮してはいかがかなと思うんですが、お考えを伺えたらと思います。","respondent":"米田商業・観光課長","answer":"そういった意味ではある程度観光協会の認知もされているのかなとは思っておりますけれども、ご指摘をいただきました点、いわゆる申し込みと問い合わせの混乱を招かない形で、今後の表記について考えていければと考えています。よろしくお願いします。","voiceIndex":98,"id":"exchange-035"},{"speaker":"宮崎委員","kind":"質問","question":"これは参加費は無料なんですけれども、お店のほうは、先ほど試供品と言いましたけれども、つまみ食いの部分については、そちらはお店の負担でやるんですか。","respondent":"米田商業・観光課長","answer":"観光協会、主催者側から一定の金銭等の供与をしておりまして、そちらの範囲内で試供品を街頭でお配りいただくようにお願いしているところですが、中にはサービス精神旺盛で、それを超える試供品を提供されている商店もあるかもしれません。","voiceIndex":100,"id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"お店によっては大分そういう声も聞くんですね。いっぱい来たので、やはり追加で出さざるを得なかったとか。ちなみにその１店舗当たりの助成額というんですか。１２月３日土曜日の午後３時までとなっているんですけれども、この３時までというのはどういうふうに、何が３時までなんですか。お店のほうはこの３時でもう試供品終わりという時間になるんでしょうか。","respondent":"米田商業・観光課長","answer":"ただ、これはやはりそのお店の立地によっても、お客様のいらっしゃるところが多いところにつきましては増額等を図りながらというようなことで、臨機応変に対応しているということでは聞いているところですが、一定一つの基準ということだろうとは思います。","voiceIndex":102,"id":"exchange-037"},{"speaker":"石田副委員長","kind":"質問","question":"要するに要員の配置が１５時までということですか。","respondent":"米田商業・観光課長","answer":"一応そういうことで考えています。","voiceIndex":104,"id":"exchange-038"},{"speaker":"石田副委員長","kind":"意見","question":"１点だけ。せっかくこれだけ多くの方たちが参加をしていただいている中で、やはりその日だけだとどうしても寂しいのかなと。来てもらうために、例えば協力してもらっているお店に、じゃあ、次回に来られた時に、例えば５％オフのクーポンだとか、そういった次回来てもらうのにつなげるために何か方策というのは。ちょっとそこだけ。","respondent":"米田商業・観光課長","answer":"あわせて次回につなげるためには、やはりお店として商店がそれぞれ出ておられる中で、その商店がやはりご自身で考えていただく部分というのがあるんだろうと思いますが、そういう中で。","voiceIndex":106,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2620#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":32734,"voices":113}},{"id":"h23-20111107-7","meetingId":"h23-cm11","date":"2011年11月7日","dateIso":"2011-11-07","committee":"厚生委員会","time":"午後１時００分～午後３時２８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"杜松小学校跡高齢者福祉施設の運営事業者公募","agenda":"杜松小学校跡高齢者福祉施設の運営事業者公募","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"施設構成のところで、地域密着型特別養護老人ホーム、認知症高齢者グループホーム、小規模多機能型居宅介護とあるんですけれども、そのほかもそうですけれども、これはどういう考えで、これにしたのか教えてください。","respondent":"原高齢者福祉課長","answer":"区のほうでも、今の高齢者の状況等々、それから入所の申し込みの状況等々の中で、特別養護老人ホームについては、一定程度整備をしていくといった方針の中、こちらについては考えているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"小規模多機能型居宅介護は、定員に満たないところが多くあるということなんですけれども、これを進めていくにあたって、今後、この構成が見直されるということはあるのでしょうか。","respondent":"原高齢者福祉課長","answer":"確かに、定員に満たないところではありますけれども、サービスが始まって間もないということも背景にありますし、いろいろな状況がありますけれども、区といたしましても、より多くの方が利用できるように、ケアマネージャー等の連絡会、それから、家族に対して。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"地域への説明会はやっているのでしょうか。昨日、さくら会まつりなどに参加させていただいて、町会や地域の子どもたちがすごくたくさん集まって、にぎやかで、そんなに大きな規模ではないのに、すごく活気があると思ったので、やはり地域との連携と理解なども、すごく必要、大切だと思ったので、今回の杜松小学校跡地での地域への説明会はやっているのでしょうか。","respondent":"原高齢者福祉課長","answer":"地域に愛される中で学校運営をしてきているという背景の中でも、きちんと地域の方々への説明会等々は実施していくと考えております。この間、町会の方々と、一定の打ち合わせをしていますし、今後についても、そういうことを丁寧に実施していきたいと考えているところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"平成２６年度に開設というのは、大体いつごろになるのか教えていただきたいと思います。それから、まとめて聞いてしまいますが、５ページの改修工事にかかる費用を、協議のうえ決定するということですけれども、おおよそどのぐらいを考えているのか、お聞かせいただきたいと思います。","respondent":"原高齢者福祉課長","answer":"開設の予定時期ですけれども、３ページに少しその辺のところを書いてあります。３年先を見通す中で、なかなか難しいところはありますけれども、今のところ、平成２６年度の第三、あるいは第四半期と想定しています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それから次に、５ページの運営期間中の2)のアのところ、一定の運営費助成を行う予定ということですが、区内で小規模多機能型居宅介護に助成しているところはあるのかと思ったのと、もししているなら、どれぐらいなのか。そして、今回はどのぐらいを想定しているのか。それから、(4)の2)の整備補助基準、この仕組みを教えていただきたいのですが。","respondent":"原高齢者福祉課長","answer":"小規模多機能型居宅介護の助成の件ですけれども、サービスの定着等々を含めて、また、仕組みとしてのこともございまして、運営上、なかなか厳しい状況もあるということを踏まえて、今、区内で小規模多機能型居宅介護が３施設ありますけれども。","voiceIndex":13,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"提案","question":"幾つか教えてください。逆に、これぐらいは、ほかの施設で邪魔にならないところというと、言い方は変だけれども、そういうところを、ここら辺でと提案してもらうのもいいんだけれども、地域の人と話したのなら、区がここら辺でどうだろうぐらいの提案をして、特に４０m2なんて書いてあるんだから、これは多分、東京都とも話をしているんだと思うんですよ。","respondent":"原高齢者福祉課長","answer":"大きく三つの条件をつけしていますけれども、１番、２番はいろいろなところで実施をしていると認識をしておりますし、あとは、３,０００m2以上のこういった施設の整備を、自分のところで実施をしているかどうかというところが、一つのところかなと思います。","voiceIndex":15,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"提案","question":"こういう形でやる。だからオーケーなんだけれども、特別養護老人ホームも、例えば認知症高齢者グループホームも２ユニットだから、多分、事業者にしてみたらかつかつ。事業者から見れば、多分、こういうことになるので、そうするとやっぱり、ある一定規模の社会福祉法人が担ってくれないと、なかなか提案自体もできない。それだけにしておきますから、お考えがあれば、教えてください。","respondent":"木下健康福祉事業部長","answer":"指定管理の部分については、前回も申し上げましたけれども、お互いに適度な緊張感が必要ですから、長いということで漫然と経営するのではなく、やはり５年ごとに議会の議決が必要なんだということを、運営事業者も認識し。","voiceIndex":17,"id":"exchange-007"},{"speaker":"若林委員","kind":"確認","question":"要するに、この事業者が改修ということですべてちゃんとやってくださるのですね、という確認になるのでしょうか、そういうことです。そうすると、さっき、４５０万円が小規模多機能型居宅介護のほうに、前例でということでしたが、そうすると、区の予算としては、この程度の規模の施設には、年間、このぐらい出していかなきゃいけないという目算というのは、今、どうなんでしょうか。","respondent":"原高齢者福祉課長","answer":"２点目の改修のところですけれども、新築と違いまして、今の躯体を残しながら改築になりますので、こちらにつきましては、きちっとした形で、事業者が責任を持って実施できるように考えていきたいと思っているところです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"若林委員","kind":"意見","question":"施設の運営・維持管理業務で、地域交流・活動拠点の運営も入っていますけれども、社会福祉法人が、こういうものもやられるということで、所管として、いわゆるこの所管の、このままやるのかということ。経費の問題も含めて、例えば利用料金制度にして、そこら辺も含めて、経費運営のほうに資するような指定管理のあり方というものも検討の余地があるのかとは思うんですけれども、参考までに聞かせてください。","respondent":"原高齢者福祉課長","answer":"一方で、これを離すという考え方も、一つにはありますけれども、先ほどの施設の関係の中では、連携をしてやっていくということで、ここの場合については、一体的な管理の中で運営をしていくのがいいのではないかと、区のほうでは考えているところです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"施設構成の(4)の地域交流施設のところでは、この中身についても、今度、プロポーザルで公募される事業所が提案をするということなのでしょうか。区として、地域交流施設として、どんな中身にしたいという考えは、どういうことになっているのかということ。それから、その他の任意提案というのも、例えば、どんなことが考えられるのかということも、ちょっとお聞かせいただきたいと思います。","respondent":"原高齢者福祉課長","answer":"改修によってどれぐらいもつかですけれども、なかなかここのところは難しいところもあろうかと思いますけれども、少なくとも２０年以上はもつということで判断をしています。","voiceIndex":23,"id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"それは、会議室とか何か、そこのところの提案というのも、事業所がされるということなのでしょうか。そこのところの中身を、ちょっと教えていただきたいと思います。それからもう一つは避難所なんですけれども、基本的に今までの杜松小学校の避難所と同じ機能を持つという考え方になるのでしょうか。そこら辺のところを、ちょっと教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"平成２５年から豊葉の杜学園がオープンしたり、こういったような事情もありますので、防災の担当のほうで、きちんとその辺を踏まえて、どういう形が一番適切かというところを考えていくところです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"わかりました。もう一つ、確認させていただきたいのが、６ページの上のほうを見ると、区とのパートナーシップの確保ということで、区は「区立施設としての基盤整備の支援」を行って、選定事業者は、「区立施設の基盤整備を行い」と書いてあるんですけれども、これは区立の施設になるので、基本的には、建物の工事は区がやるという考え方で、工事費は全額区が出すという考え方でいいんですよね。","respondent":"原高齢者福祉課長","answer":"土地、建物とも含めて、区立になります。そういった中で、区が工事費を出すのですけれども、その工事の中身、それから設計等については、社会福祉法人が提案をしたうえで、区と協議のうえ進めていくというような仕組みです。","voiceIndex":27,"id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうためにも、これは、地域の方にとっても、ほんとうに待ちに待った喜ばれる施設なので、全容が決まって、こういう建物を建てますという建築の説明ではなく、こういうことでつくっていきますということを、町会の方だけではなく、ぜひ説明会をして、地域の方に説明をする場をつくっていただきたいと思うんですが、いかがでしょうか。","respondent":"原高齢者福祉課長","answer":"そういった意味では、ここは、小規模多機能型居宅介護ですし、地域のグラウンド等々として開放等もしていくといった位置づけの施設ですので、そこについては、丁寧に実施していく考えです。","voiceIndex":29,"id":"exchange-013"}]},{"id":"topic-02","title":"平成２３年度区内における熱中症の状況","agenda":"平成２３年度区内における熱中症の状況","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"避暑シェルターは、どれぐらい利用されたのか。この時期、ぐんと伸びたりしたのかとか、その辺をお聞きしたい。それから、対策をたくさん打たれている中で、実績がわかれば、(2)、(3)と教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"いろいろなところで避暑シェルター機能ということで実施をしてまいりました。","voiceIndex":36,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"２３区で見ても、平均を下回っているので、評価できるものだとは感じるんですが、搬送された方は、年齢構成など細かいことがおわかりでしたら、どういう状況の人だったかとか、教えていただきたいのと、それから、今後、さらなる対策を考えているのか、教えてください。","respondent":"原高齢者福祉課長","answer":"年齢構成で多いところは、７０代、８０代で３８％ぐらいというような数値になっているところです。さらなる対応です。熱中症は、昨年から特に話題になってきておりまして、私どもも、昨年もさまざまな対応、それから、今年もそれに追加する形で対応してまいりました。","voiceIndex":38,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけ、お願いだけしておきます。来年、もしこういうことをやるなら、ぜひそこの部分は、３回言えば１回ぐらい全員に伝わるかもしれないので、それはこういう趣旨ではないということだけを言っていただきたい。それだけお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-016"},{"speaker":"鶴委員","kind":"提案","question":"幾つか、次回どうするかというような質問もあって、また、今、提案もありましたけれども、多分、特に避暑シェルターの対策が効果があったという認識でいるのかと思います。避暑シェルターってかたいよねとか、もっと柔らかい名前はどうかとか、集まりやすい名前にしたらどうでしょうという提案もさせていただいて、僕にしてみれば、ちょっとかたいなという感じもします。","respondent":"原高齢者福祉課長","answer":"節電効果は、来た方々がどのぐらいかということと、そのことによっての効果ということと、各家庭の中には、暑いときは、家でクーラーをつけないようにということで、商店、デパートのほうで買い物がてら涼んでいるという方もいらっしゃいますので、そういった中と。","voiceIndex":41,"id":"exchange-017"},{"speaker":"鶴委員","kind":"提案","question":"ネーミングの提案をさせていただいたときに、荒川区なんかは、逆に効果がどうこうという部分もそうなんですけれども、何世帯の方が来ると、どれだけの節電効果があるという試算を出していたような記憶があるので、そうした事例なども参考にしていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-018"}]},{"id":"topic-03","title":"本日は、所管事務調査といたしまして、品川区の介護保険制度と国の介護保険法の改正","agenda":"本日は、所管事務調査といたしまして、品川区の介護保険制度と国の介護保険法の改正","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"国のほうの改正の概要ですけれども、１番の5)の介護療養病床の廃止期限を猶予とあるんですが、新たな指定は行わないということで、徐々に移行していくという形だと思うんですけれども、受け皿は、品川区としてはどう考えているのかを教えていただきたい。","respondent":"原高齢者福祉課長","answer":"今回、そういった中で、たんの吸引が一つの部分で出てきておりますけれども、これは、家族、あるいは実際にたんの吸引をするスタッフ、こちらのほうも大変負担が大きいと考えておりまして、こちらは、国、あるいは東京都のほうが研修体制を組んでいく形が基本となりますけれども。","voiceIndex":49,"id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"人員を増やしていってほしいと、私は思うんですけれども、そうはいっても、医療のところは医療の専門家だと、私は思うんです。それから、２ページの日常生活圏域ニーズ調査は、もう行われたのでしょうか。ちょっとお聞きしたいと思うんですが、いつ、何人ぐらいに行われて、調査のまとめは出ていたのか、どうか、ちょっとお聞きしたいと思います。","respondent":"原高齢者福祉課長","answer":"３月に実施しまして、区内の７０歳以上のひとり暮らしの高齢者を中心にニーズ調査をしまして、約６,０００件ということで、実際に配付できたのは５,８７１件ということで、回収が３,１５５人ということで、地域の中で。","voiceIndex":51,"id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問","question":"調査の結果、まとめ、報告などは出ているのか。私たちが見れる形があるのでしょうか。","respondent":"原高齢者福祉課長","answer":"現在も、こちらのほうは一つの調査ということで、まとめを最終的にしておりまして、こういったところを踏まえて、第５期の介護保険事業計画にもあわせて持っていくということで、対応を考えているところです。","voiceIndex":53,"id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"基金とかいいですよ、そうなってきたら、これは保険制度だけれども、これは調べていないのでごめんなさい、もう一つ、基金を取り崩していくのは、それは一つだけれども、そうすると多分、今も少し行われているけれども、一般会計からの繰入金ということも、各自治体で出てきたりすると、そこも膨らんでくる可能性があるのかなと、私は非常に思ってしまって、保険なんだから。","respondent":"原高齢者福祉課長","answer":"保険料の上昇の件ですけれども、国のほうで見込みをする中で、いろいろな要素で保険料が平均で上がるだろうということを推計しまして、その中で、その上がりに対して何らかの方策で上昇の緩和を図っていこうということで、一つには、財政安定化基金、これは都道府県単位に、国。","voiceIndex":55,"id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問","question":"すみません、私もすごく不勉強なんですが、今、尾道市と京都市は、ちょうど我々も視察に行ったので、介護保険料が大体４,５００円ぐらいなんです。京都市みたいな大きいところでも４,５００円。尾道市でも４,５００円ぐらい。京都市なんかは平成２２年度の歳入が約１,０００億円もある。そのお金は、結局どこから、保険料に跳ね返すしかないのかというところを、もう一度、教えてください。","respondent":"原高齢者福祉課長","answer":"残りの５割については、現在のシステムですと、６５歳以上が２０％、それから、いわゆる２号ということで、４０歳から６４歳までの方が３０％というような割合が、もう決められてありますので。","voiceIndex":57,"id":"exchange-023"},{"speaker":"向委員","kind":"質問・要望","question":"２４時間対応のモデル事業のところで、少し気になったというか、教えていただきたいんですが、８人の実施状況の概要が、今後の課題と一緒に載っていて、具体的な事例も拝見したところ、認知症とか、要介護度がそこまで重たくない方の具体例だったので、トイレのことが結構改善されたという変化が多かったと思うんですが、４番目の方で「介助者の負担が大きくサービス内容に課題が残っている」というところで。","respondent":"原高齢者福祉課長","answer":"こちらの方は、当時要介護４、現在は要介護５ということで、介護度も非常に重い方で、それから、老老介護ということで実施をさせていただいた方です。この方は、定期巡回で就寝介助ということで、夜、決められた時間に介護をしているです。","voiceIndex":59,"id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"広域的なものだと言われますけれども、ますます老人保健施設が入りにくくなってしまうような、そういう状況になってくるのではないかと思うんです、療養病床をこれからなくしていくという方向の中で。そういう点では、老人保健施設を、区として、どういうふうに整備していこうとしているのか、そこのところについて、ちょっとお聞かせいただきたいと思います。","respondent":"原高齢者福祉課長","answer":"そういった意味では、区としましても、ご家族の方の相談に柔軟に対応しながら、家族の方がそういったところにつないでいけるような支援をしていきたいと思っているところです。","voiceIndex":61,"id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だから、やっぱり介護療養病床は介護療養病床でなくさない、それから、受け皿に対しても、今、行き場がなくて大変だという状況がありますので、老人保健施設に関しても、区としても、どうやったらできるかというところをしっかりと検討して、土地の部分もあるということなんですけれども、そういうところで確保していく努力を、ぜひお願いしたいと思っています。","respondent":"原高齢者福祉課長","answer":"そういった意味では、今回、１カ月ですけれども、こういった評価、それから、今も継続しておりますので、そういった状況を見ながら、どういった方々が、このサービスを使うことによって、介護者の負担軽減につながっていくのか、あるいは。","voiceIndex":63,"id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"訪問看護もセットになっていると、もう一つの訪問看護とはセットでは使えないということになると思うんですけれども、そういう形で、これは訪問介護だけの定期巡回ということになると、訪問看護ステーションはまた別枠で使えることに、仕組みとしてはなるのでしょうか。そこのところも教えてください。","respondent":"原高齢者福祉課長","answer":"区のほうでは、今の段階では２０万円で利用者負担が１割で２万円で、事業者のほうが１８万円というような形で設定を考えて、実施をしています。","voiceIndex":65,"id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これを導入するかどうかは、自治体が決めていくということですけれども、私は、一般質問でこの問題を取り上げさせていただいたときには、今までどおりのサービスをしていきますというご答弁をいただいたんですが、区としては、この総合事業を要支援１、２の方に使うということではなくて、今までどおりの介護給付サービスでいくということで確認をさせていただいていいでしょうか。","respondent":"原高齢者福祉課長","answer":"それは、要支援１、２のサービスというよりは、それ以外のサービスで、例えば配食なんかについても、要支援の方は使えなくて、非該当の方が使えるとかになりますと、使えていたものが使えなくなるというようなことがありますので、そういったところは。","voiceIndex":67,"id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"配食サービスとか、そういういろいろなものは、今まででも、地域支援事業の中でされてきたわけですよね。だから、介護予防・日常生活総合支援事業にしなければいけないということはないと思いますし、介護予防・日常生活総合支援事業にしないとできないものというのはあるのですか。","respondent":"原高齢者福祉課長","answer":"そういう意味では、品川区の実施しているこういったものを、こういった事業の中で取り組んで、利用者が安心してというような考え方に基づいたものも一つの事例ということで考えているところです。","voiceIndex":69,"id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、国とか、都道府県とかの分も、ぜひここの中に入れて、保険料が上昇しないようにしていただきたいと思っているんです。区としては、そういうところを、国のほうに上げていくことをしていただきたいと思うんですが、いかがでしょうか、ということが一つ。一人当たりとして幾らぐらいになるのか、わかったら教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"２点目の区の部分ですけれども、平成１２年度から、この部分を拠出させてもらっておりますけれども、どのぐらいかというのは、まさに今、都道府県のほうで、東京都のほうで、どのぐらいを取り崩しに使うかということで、現在、検討会が行われてあります。","voiceIndex":71,"id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"介護保険料は、前回は据え置きになりましたけれども、そしてまた、低所得者の負担軽減がされてよかったと思っていますけれども、高齢者にとってもほんとうに大変な状況がありますので、国や都道府県の財政安定化基金も、介護保険の負担軽減に回せるように、ぜひ、区のほうからも言っていただきたいと要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3308#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":43570,"voices":77}},{"id":"h23-20111107-8","meetingId":"h23-cm11","date":"2011年11月7日","dateIso":"2011-11-07","committee":"建設委員会","time":"午後１時００分～午後２時５９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、報告事項を行います。 初めに、(1)「平成２３年度目黒川水質改善対策検討の中間まとめ」","agenda":"の１、報告事項を行います。 初めに、(1)「平成２３年度目黒川水質改善対策検討の中間まとめ」","exchanges":[{"speaker":"武内委員","kind":"質問","question":"根本的なところで、３ミリ以上の雨が降るとどうしても川のほうに流れてきてしまう。水が汚濁してくるということなんですけれども、ある程度海水導水をやることで、仮に雨が降って入ってきても、今までよりは断然変わってくるのか。それとも雨が降って入ってきてしまえば、やはりまたそれが何年かたってしまうと、また戻っちゃうとか、やり続けなければいけないのか、その辺のところを教えてください。","respondent":"岩田都市環境事業部長","answer":"これも、徐々にですけれども、進んでまいりますから、将来的には合流式下水道から出る汚濁物質の量は、将来的には徐々に減っていく。そういう見込みが１つあるということと、当然のことながら、東京湾の水質自体も、毎年毎年きれいになってきているんです。","voiceIndex":6,"id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"やはり今の下水の話なんですけれども、合流式から分流式へ徐々にやっていくということ、これは１００億円近くかかるこの費用負担、面積比ではほとんどが世田谷区ということになる。そういう費用負担なんかはどうなんでしょうか。","respondent":"岩田都市環境事業部長","answer":"具体的に金銭的なことは言っていませんけれども。場合によっては、流域３区で一部費用をみるのであれば、どういう見方があるかというと、先ほど冒頭で出ました、汚濁物質を流している量、この量の割合で考えるのが妥当ではないかというふうに、品川区は考えているところです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"将来的なビジョンはこうあるというのはわかるんですけれども、そうすると、海水導水のほうでランニングコストというのは、何年かはこうかもしれないけれども、その先、多分上がっていくだろうという、それがどういう予測がされているのかということと、あと今は合流式なんですけれども、分流式にしていくという選択肢がどの程度検討されているのかということと、世田谷、目黒、品川の分流式のほうで。","respondent":"岩田都市環境事業部長","answer":"これは粗々の試算ですから、例えば海水導水の場合ですと、まず巨大なポンプがありますね。これも本体そのものの減価償却はおそらく１５年ぐらいのものですけれども、３年から５年に１回、リニューアルをしなければいけないんです。そういった経費がこの中におしなべたい。","voiceIndex":10,"id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"どこかで何かの見直しをかけられるとか、そういうものなのか、行政の事業というのは、一度始めれば、どこまでどんなふうにいっても進むことになるかと思うんですけれども、そういうところの評価のところとか、そういうことはどういうふうに考えているんでしょうか。","respondent":"岩田都市環境事業部長","answer":"これでは全然足りません。毎秒３トン入れますけれども、これがどんどん少なくなって、毎秒１トン、あるいは０.５トンまでは下がるかもしれませんけれども、何らかの形で人工的な装置というのは今後もずっと続けていかない限り、目黒川は生き返らないということになります。","voiceIndex":12,"id":"exchange-004"}]},{"id":"topic-02","title":"品川区水とみどりの基本計画の中間のまとめ","agenda":"品川区水とみどりの基本計画の中間のまとめ","exchanges":[{"speaker":"井上委員","kind":"質問","question":"計画の目標の将来目標のところで、今、みどり率２５％という、これはパブリックコメントによって検討もあり得るということだったんですけれども、２５％の根拠というのは、練馬なんかでは３０％というふうに出していて、みどりの人に与える効果というのは結構あるということに立てば、ここのところがもう少し上がるとか、そういうものについてはどのような見解を持っているんでしょうか。","respondent":"藤田水とみどりの課長","answer":"この２５ですけれども、１つは、品川という土地の中で人々が生活していくことも当然頭に置きながら、数値の目標を作成していくべきというところで考えております。","voiceIndex":18,"id":"exchange-005"},{"speaker":"武内委員","kind":"確認","question":"確認なんですけれども、屋上の緑化とか壁面の緑化、これも入れるんでしたっけ。","respondent":"藤田水とみどりの課長","answer":"しかしながら、都市の環境や安全を支えるみどりの保全とか創出が必要だということで、そういった身近なみどりについても、この中では評価をしていきたいという考え方は持ってあります。","voiceIndex":20,"id":"exchange-006"},{"speaker":"中塚副委員長","kind":"質問","question":"パブリックコメントの結果がどうだったかということを伺いたいのと、それとこの中間のまとめですけれども、計画策定の趣旨に環境問題の多様化や防災への意識の高まりとありますけれども、それは具体的にどういうものを指しているのか、その問題意識を伺いたいと思います。それにこの計画がどう対応しているのか、ご説明いただけますでしょうか。","respondent":"藤田水とみどりの課長","answer":"それからみどりのカーテンの部分ですけれども、こちらのペーパーの基本方針の方針２のところにあります水とみどりが身近にある豊かな暮らしをつくる、施策として水とみどりに親しめる環境の整備というところに位置づけていくべきかなと考えていますが、今後の取りまとめの中で。","voiceIndex":24,"id":"exchange-007"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"そこをこの計画の中でどう評価されているのか、位置づけられているのか、そこについてご説明いただきたいと思います。","respondent":"藤田水とみどりの課長","answer":"しかしながら、品川区のみどりをどうしていくかということを考えたときに、例えばこれまで私どもみどりの実態調査の中で、過去１０年間で相当数のみどりが増えたというような話もしてきてありますけれども、例えばそれがＣＯ２の問題と比較をすると。","voiceIndex":26,"id":"exchange-008"},{"speaker":"中塚副委員長","kind":"意見","question":"最後に意見ですけれども、この間も言ってまいりましたが、都市部を冷やすヒートアイランドの対策、ＣＯ２の対策、喫緊の課題だと思うんですね。それこそ人類が生存してくための。あわせてほかの対策もしっかりやっていく。今のご説明ですと、グローバルな考え方と分けるという話がありますが、そこはしっかりとこの水とみどりの計画に位置づけなければいけないんじゃないのかなと思います。","respondent":"稲川委員長、野呂瀬環境課長","answer":"ほかにありますか。ご発言がないようですので、本件を終了いたします。現在の放射線測定の状況からご説明いたしますと、区では本年６月から、小・中学校、幼稚園・保育園、公園の土壌に含まれる放射性物質を測定した結果、すべて安全内の数値でございました。","voiceIndex":28,"id":"exchange-009"}]},{"id":"topic-03","title":"放射能対策の今後の進め方","agenda":"放射能対策の今後の進め方","exchanges":[{"speaker":"井上委員","kind":"質問","question":"区が購入した測定器で、もう半月ぐらい届いてからあると思うんですけれども、この間どういった活用をされて、どういったところをはかられていったのか、その状況を教えてください。","respondent":"野呂瀬環境課長","answer":"保育園・幼稚園も測定しています。状況ですが、学校につきましては大体終わるところなんですけれども、公園が全部で２５０カ所、それと区道等も含めますと、全部で約４００カ所ぐらいの測定箇所があると聞いておりますので、順次その測定を進めている状況です。","voiceIndex":33,"id":"exchange-010"},{"speaker":"井上委員","kind":"質問・要望","question":"私たちも測定器を持ちながら調査をしているときに、自治体間のネットワークもありまして、学校周辺の道路の側溝は、上からはかると大したことはなくて、それを外したときにその汚泥というか、そこで高濃度の測定が明らかになっているんですが、私たちが一般にやるときはそれを外すことはできないので、上だけをはかっているんですが、そういうところの、区が行政としてやるので。","respondent":"野呂瀬環境課長","answer":"今、側溝を外して測定ということですけれども、今現在はガイドラインに沿いまして、とりあえず１ｍの高さの空間線量、というのは、まずポイントが側溝のポイントよりも、１ｍの高さで空間線量が高いところがあるかどうかを測定するというのが基準になっておりますので。","voiceIndex":35,"id":"exchange-011"},{"speaker":"井上委員","kind":"質問・要望","question":"それから測定が今までだと１週間に一遍の事業者でしたから、公表はそういうペースだったと思うんですけれども、今現在は毎日やっているのかどうか、そこも確認していなかったんですが、毎日４台でやっているのかということと、公表のペースはどのくらいで今、されているんでしょうか。","respondent":"野呂瀬環境課長","answer":"公表のペースは、区内２カ所の業者による測定は来年３月まで、これは継続しておりますので、それは今までどおり、毎週１回ずつ測定して、公表はしております。","voiceIndex":37,"id":"exchange-012"},{"speaker":"井上委員","kind":"質問・要望","question":"今、適時調べていって、高かったら公表するということではなくて、きちんとやっているんですから、その部分については心配ない、データがちゃんと知りたいというのが、保護者、地域の方のニーズなので、高かったら報告するとかというのは、求めているこちら側としては違いますので、それについては随時、そんなにまとめてではなくて、できる範囲で随時公表していくということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-013"},{"speaker":"武内委員","kind":"質問・要望","question":"その都度一つ一つずつ出していけとは言わないけれども、あまりためて、ためてということだと、安全だというお話ですから、なるべく早い段階で出してもらったほうが逆に安心すると思うので、ぜひそれは検討していただきたいなという要望と、あとは原則１ｍのところなので大丈夫でしょうとお話なんでけれども、ちょっと過敏な方たちもいらっしゃる中で。","respondent":"岩田都市環境事業部長","answer":"この間の決算特別委員会の款別審査でもお答えしたんですけれども、区が購入した機械２台と東京都からお借りしているものは、何のためにやったかといいますと、我々のそれぞれの所管の部署が、学校であれば学校、あるいは保育園であれば保育の人たちが。","voiceIndex":40,"id":"exchange-014"},{"speaker":"武内委員","kind":"意見","question":"最後のところなんですけれども、例えば学校だと、はかっているそのときに大丈夫ですよというのを、学校のほうにお知らせして、それで学校から、ケース・バイ・ケースなんでしょうけれども、保護者等にもという場合もあれば、問い合わせがない場合には言わない場合もある。それは学校の判断ですね。","respondent":"岩田都市環境事業部長","answer":"異常値は出ておりませんので、保護者からの問い合わせがあれば、全く異常はありませんでしたというふうに順次お答えしているそうです。","voiceIndex":42,"id":"exchange-015"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"国の基準と品川区の基準と何がどう違うのか、なぜそうしたのか、そこをご説明いただきたいと思います。全体的なことになるんですけれども、今年６月から行ってきた測定と、あと今日、報告があったこの放射能対策の今後の進め方について、従来と何がどう違うのか、考え方や、測定の方法や、対象や、従来の区の対応とどう違っているのか、全体的な話ですけれども、お伺いしたいと思います。","respondent":"岩田都市環境事業部長","answer":"数字だけ見ると倍なんですね。それがどういうことなのかというのは、一般の区民の方には理解ができませんし、我々職員でもなかなか理解できないところなんです。ですから、品川区としては０.２３までは全く問題ありませんということで説明をしていく以外ないんですね。","voiceIndex":44,"id":"exchange-016"},{"speaker":"中塚副委員長","kind":"質問","question":"今日の資料の測定方法について、放射線測定に関するガイドラインにより実施するということなので、このガイドラインについて幾つか伺いたいと思うんですけれども、このガイドラインは３部構成になっていまして、第Ｉ章が「環境中の放射線量の平均的な状況を把握するための測定法」とありまして、第II章が「除染等のための比較的高い放射線量の原因となっているポイントを特定するための測定法」。","respondent":"野呂瀬環境課長","answer":"それに沿って、先ほど申しましたとおり、例えば公園だとか、学校だとかに、それぞれのところではかっているというところでございまして、場合によっては、その施設によっては、１つの施設で数カ所はかるような場合が出てくると考えております。","voiceIndex":46,"id":"exchange-017"},{"speaker":"中塚副委員長","kind":"質問","question":"先ほどのご説明にもあったんですけれども、要するに住民や地域の方々から、周辺より放射線量の高いところが見つかったときの対応について、既に幾つか行っているというご説明がありましたけれども、具体的にどういう対応をしていくのか、そこをしっかりと伺いたいと思います。改めて区が測定して、結果の公表、対策の公表、こういうことなのかどうか伺いたいと思います。","respondent":"岩田都市環境事業部長","answer":"先ほども言いましたように、今現在、品川区で持っている測定器は４台です。東京都からお借りしているものも含めて。そのうち今回、国が示しているガイドラインとして使える、判定に使える機械は２台のみです。シンチレーションという６５万円の高精度の測定器のみです。","voiceIndex":48,"id":"exchange-018"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"住民の方々が自分で落ち葉を集めたり、どこに捨てていいのかとよく伺うんですけれども、住民自身がどこに捨てればいいのか、考えをご説明いただきたいと思います。その対応を行うべきだと思うんですけれども、いかがか。言うまでもなく福島第一原発事故に由来するわけですから、第一義的には東電、原発を進めてきた経過説明、要するに最終的にはどこに費用負担を求めていくのか、伺いたいと思います。","respondent":"岩田都市環境事業部長、野呂瀬環境課長","answer":"現在、福島県以外のこういった対策について、各自治体が行ったさまざまな対策に対して、国は明確な考え方を出しておりません。落ち葉は除染するような部分は出ていないんです。０.２３マイクロシーベルト以上のものが出たと確定した場合には、品川区は速やかに災害対策本部を設置し。","voiceIndex":50,"id":"exchange-019"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"正確さもきっとあるでしょうから、区の今回の進め方について、広報というか、説明というのをどうやっていくのか、そこを伺いたいと思います。ちょっと聞き漏らしたかもしれませんが、小学校、中学校は違うみたいなので、そこは後で伺いたいんですけれども、ほかの自治体では地表５cmでやっていると。結果に応じた除染などの対応を求めたいと思いますが、いかがでしょうか。","respondent":"岩田都市環境事業部長","answer":"先ほどもお答えしましたように、国の統一見解が出ましたので、まずはこの統一見解のやり方で我々は対応していきたいと考えております。ただ小学校、幼稚園、中学校につきましては、別に文部科学省の通知がありますので、学校関係につきましては１ｍ、５０cm、１０cm。","voiceIndex":54,"id":"exchange-020"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、ガイガーカウンターのお話をいただきまして、区民の皆さんが不安になって自主的にみずからが求めてはかるということで、ガイガーカウンターですけれども、ロシア製が比較的安価な値段で大量に出回っているということなんですけれども、そのはかり方とか、カウンターについての予備知識、その他もろもろの情報について、区のほうから何か周知をされていることはあるんでしょうか。","respondent":"野呂瀬環境課長","answer":"今のご質問ですけれども、ガイガーカウンターについて、今のところ、区民に対しての周知というか、説明はしておりません。","voiceIndex":56,"id":"exchange-021"},{"speaker":"大沢委員","kind":"質問","question":"ですから、個人の方がはかられることによってかえって不安が増したり、または逆に減ったりということがあるので、そこら辺の一定の基準というか、基準を設けるのは大変かもしれません、難しいことかもしれないんですけれども、そこに一定の線というか、使用にあたっての条項というのは区から発する必要があると思うんですけれども、あくまでも個人の購入することですから。","respondent":"岩田都市環境事業部長","answer":"今は、まずは簡易の４万円から７万円で売っているような、いわゆる空中線量の測定器、これは簡易なものがいっぱい売っていますので、そういうものを皆さん買い求めて、いたるところではかっておられますので、場合によってはそういうものの利用の仕方とか。","voiceIndex":58,"id":"exchange-022"},{"speaker":"井上委員","kind":"質問・要望","question":"公表とか比べるものについては別にそれは１ｍを否定するわけではないので、それでも結構なんですけれども、そういうところは臨機応変に、ちゃんとデータをとっていくということが必要だと思いますので、３分から５分そこにいて、追加の測定をするということになると思いますけれども、そういうところはそれで問われたときに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-023"}]},{"id":"topic-04","title":"大崎駅周辺地域イベント「目黒川みんなのイルミネーション２０１１」への協力","agenda":"大崎駅周辺地域イベント「目黒川みんなのイルミネーション２０１１」への協力","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"それとイベントについてちょっと伺いたいんですけれども、この使用済み食用油というのをどうやって回収しているんですかね。周辺の方々が、そういう１つの運動の中でやっているのかということを伺いたい。どうやって集めてこのイベントを成功させているのか伺いたいのと、あと発電機というのは特別な発電機なのか、普通にディーゼルエンジンというんですか、普通の発電機なのか、特別な発電機なのか。","respondent":"三宅都市開発課長","answer":"ＯＧＴＭがこちらのイベントに協力する理由、目的ですけれども、そもそも大崎・五反田タウンマネージメントというのは、大崎駅周辺地域まちづくり連絡会において、平成１６年に都市再生ビジョンというのを策定しておりまして、幾つか戦略を掲げているところの５つ目に。","voiceIndex":65,"id":"exchange-024"},{"speaker":"武内委員","kind":"質問","question":"報道した後、東京都にも大分問い合わせとかがあったと聞きましたけれども、今みたいな説明を聞けば、ちゃんとそこまでやっていただいているのですけれども、品川のほうにそういう、いろいろないい面、悪い面あるんでしょうけれども、賛成、反対あるんでしょうけれども、問い合わせとか、そういうのはあったんでしょうか。","respondent":"太田品川区清掃事務所長","answer":"私も広報のほうに４日に確認をしてきましたけれども、広報のほうは来ていない。環境課のほうに３件ぐらいお問い合わせがあったということは聞いておりますけれども、清掃事務所のほうにはございません。","voiceIndex":71,"id":"exchange-025"},{"speaker":"中塚副委員長","kind":"質問","question":"どんなふうに考えたらいいのかなという声もあわせて聞きます。不安だという話を聞くと、その場その場は低くても、最終的にごみですから、燃やしたり処理したり、小さくなって埋め立てるわけですよね。そういうところについての測定はどういうふうに行われているのか。結果の公表についてはありましたけれども、埋め立て場所での測定場所についてはどういう方法になっているのか伺いたいと思います。","respondent":"太田品川区清掃事務所長","answer":"ただ８,０００ベクレルに満たないものについては、国の方針として安全性があるという前提で、通常の廃棄物と同様に埋め立てて構わないというガイドラインが出ておりますので、それにのっとって今回、全体を含めて処理しているということで聞いているところです。","voiceIndex":73,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4022#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":36435,"voices":77}},{"id":"h23-20111107-9","meetingId":"h23-cm11","date":"2011年11月7日","dateIso":"2011-11-07","committee":"文教委員会","time":"午後１時００分～午後２時４２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"人事委員会勧告の内容なんですけれども、これというのは３ページ目のところの実施時期等のところで、平成２３年度４月から改訂の実施云々と書いてあるんですけれども、これというのは平成２２年度の人事委員会勧告の内容で、平成２３年度の実施がされるということの受けとめでいいんですか。ここの文言がちょっとよくわからなかったのが１つです。","respondent":"冠木指導課長","answer":"３つ目は制度の部分ですので、これは主に総務委員会のほうでご議論されているというふうに理解はしていますけれども、幼稚園の教員についても１つの区の職員という考え方でやらせるというふうに私どもは認識しております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３ページ、４ページのところの部分なんですけれども、特に「人事制度の整備」というところの２の「人材の育成」というところで少し気になったのが、(1)の「昇任意欲の醸成」というところで、意識調査とか書いてあるんですけれども、こういった面で幼稚園とか、固有職員はまだ人数的に少ししかいないですが、こういう部分の意識調査とか、品川区の傾向がどうなのか、わかったら教えていただきたいのと。","respondent":"田村教育次長、冠木指導課長","answer":"若干、ちょっと指導課長の説明が不十分だったのでやりますと、今年度平成２３年度の勧告は、さかのぼってではありません。これを受けまして、メンタルヘルスの部分で私どもの庶務課のほうに看護師がおりますので、そこで多少なりとも少し心配だなという先生については、産業医の面接につなげると、そういうような形で対応をしています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"今、勤務時のアンケート等を行っているんだということで、この辺はいつぐらいにとりまとまって、その中身が活かされるわけですか。","respondent":"冠木指導課長","answer":"今、ちょうどそれぞれの学校からアンケートをいただいて、それがそれぞれ分析をかけて、そしてもし心配な先生がいた場合には、産業医に伝えるという対応をしています。年内には状況はまとまってこようかなと考えています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"わかったらご報告いただきたいと思いますけれども、個々の先生たちの状況を分析して産業医につなげるだけじゃなくて、全体的なトータルの中身も結果がいろいろ検証されて、また対策とかがとられるわけですね。その辺も含めてぜひご報告をいただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"},{"speaker":"須藤委員","kind":"質問","question":"詳しくは総務委員会でということなのですが、１点だけ。品川区の教育委員会としては、教職員が本当に改革プラン、改革で頑張ってくれていると。逆に品川のようにすべてやってくれという模範たる絵を示すような考え方はできないんですか。国が破ったんだから、品川区だって破ったっていいじゃないかというような思いがあるんだけれども、いかがでしょうか。","respondent":"田村教育次長","answer":"それについても賛否両論ありまして、やはり憲法違反じゃないかという考え方もありますので、この辺は国のほうの今後の審議経過を見ていきたいと考えていますし、地方公務員については、当時の総務省は、地方公共団体については適切な措置を講じていただきたいと。","voiceIndex":13,"id":"exchange-005"},{"speaker":"須藤委員","kind":"意見","question":"特別区の人事委員会というのは、まして２３区が基礎自治体として独立したときに、そのもの自体がどこまで必要だというところ、これは総務委員会でやらなきゃいけないんだろうけれども、そういう話に当然なってこようかと思うので、やはり品川区としていろいろな意味合いで頑張ってきているところが、職員の意識を低下させるような仕組みに、あえて法律だからという形をつくるということ自体が。","respondent":"若月教育長","answer":"この件についての法的なさまざまな根拠であるとか、経緯というのは、ただいま教育次長がご説明をしたとおりです。そこへ持ってきまして、例えば教員のいわゆる給与負担というのは国庫負担が原則でありますので、この当事者は、品川区の場合には国と東京都になるわけであります。","voiceIndex":15,"id":"exchange-006"},{"speaker":"須藤委員","kind":"質問","question":"独自に労使交渉に入ってくるかと思うんだけれども、議会の中でもそういう意見、考え方は、もう職員の皆さんが頑張っているということの評価をしていくためには、それこそ人事権の採用の問題まで、区で採用というところまで入ってきてしまうけれども、そういった全体的な人事権確立もしてきているのだから、そういう仕組みができるような、もっとしっかりと次のステップに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-007"},{"speaker":"須藤委員","kind":"意見","question":"今、説明の中で、地域の祭礼等で第１・第３週目がどうしても不都合なら、他の週も確保するというような表現があるんだけれども、祭礼というのはずっと学校が土曜日になる前からもうずっとやっているので、大抵お子さんたちが担ぐ日は午後の時間にセットしていると思うんです。朝から担がせるよという町会は、渡部委員は町会に詳しいから聞いてみるといいんだけれども、大抵午後になっていると思うんだ。","respondent":"冠木指導課長","answer":"地域等々の行事につきましては、それぞれの地域のお祭りの日程であるとか、それに影響する学校の規模、複数校かかわっているという状況も報告としていただいておりますので、そんなところを見据えながら、基本はやはり委員がおっしゃったように。","voiceIndex":23,"id":"exchange-008"},{"speaker":"須藤委員","kind":"質問","question":"ですから、どうしても複数の場合は他の週も確保するというような考え方になってしまうのか。","respondent":"田村教育次長","answer":"指導課長が説明しましたけれども、私のほうで補足しますと、考え方は委員がおっしゃっているとおりの説明をしています。先日も地域センターの所長会がありまして、私が出て直接お話ししたのは、ここは原則と書いているけれども、もう第１・第３土曜日の午前で行くんですよと。","voiceIndex":25,"id":"exchange-009"},{"speaker":"須藤委員","kind":"質問・要望","question":"ちょっと最近僕らが聞くと、昔はいわゆる皆勤賞を出します、ねらいますというようなお子さんたちが多いんだけれども、近年は親の旅行がここにあるから、学校を休んで一緒に旅行に行きなさい、連れていきますみたいな、教育と子育てというのが全然違うところでとらえてしまう親御さんたちが多いので、やはり学校があるからこの日はだめなんだということを、家庭の中でも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"だからここに５番のあたりなんですけれども、また地域の方々、土曜日でもゲストティーチャーなんかに来ていただいたりとか、いろいろそういうイベント的な、ちょっとそういうところもないように、意味もあると思うんですが、やはり確かな学力の定着を図るということを主に推進していただきたいと思うんです。その辺をちょっとお聞きしたいと思います。","respondent":"冠木指導課長","answer":"これが大前提です。土曜日に実施していくという趣旨の中で、地域に開かれたというような視点もあるので、こういった５番であるとかの理由も当然あるんですけれども、第一義的にはやはり授業時数をしっかり確保して、その中で子どもたちに繰り返し履修させるべきは履修させる。","voiceIndex":28,"id":"exchange-011"},{"speaker":"阿久津委員","kind":"質問・要望","question":"勉強不足で基本的なことをちょっとお伺いしたいんですけれども、この小・中学校における土曜日の授業実施というのは、これはいわゆる全国的な動きなんでしょうか。それとも品川区独自の動きなんでしょうか。そういう情報があれば教えていただきたいということが１点と、あと、保護者の方からは、いわゆる土曜日の授業をやってほしいという意見というのは、教育委員会のほうに届いているんでしょうか。","respondent":"冠木指導課長","answer":"もちろん地域の方々、あるいは保護者の方々から、土曜日の設定、もう現実に、今、１０日以上実施をしている学校も複数ありますので、そういった中から、その設定の方法であるとか、あるいはそうではない学校から、もう少し土曜日をやってほしいというようなお声は届いております。","voiceIndex":30,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"上から順番にお伺いしたいと思いますが、原則として第１・第３の土曜日の午前中授業と書いてあります。時間的には何時から何時までなのかというのが１つです。その下に夏季休業日中には授業日は設けないということで、春休みとか冬休みはどうなのかというところを教えていただきたいのと、あと、主な実施理由のところなんですが、小学校は平成２３年度から、中学校は来年度から実施。","respondent":"冠木指導課長","answer":"これは、国語とか算数とか、そういう授業時間が１,０８０時間なら１,０８０時間必要であって、それ以外のところで、今、学校は当然実施をしておりますので、カウントには入ってこないんですけれども、土曜日に文化祭であるとか。","voiceIndex":32,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"中学校が１,０５０時間なんですが、その辺が新学習指導要領によって増えた部分と、品川区の小中一貫教育の、その辺の違いがよくわからないので、そこを教えてください。","respondent":"冠木指導課長","answer":"今の小中一貫教育要領の数値と今回ご案内している数字には、３０時間の差があります。","voiceIndex":34,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"実際に授業時間数を確保するために土曜日の設定が増えるわけですけれども、これによって、平常の月曜日から金曜日の時間の枠が変わるのかどうか、単純に増えたたけなのか。その曜日によってのこま数を教えてほしいのと、ちょっとここのところを答えていただきたいんです。かなりその辺が関心事になっているかとも思うので、ここはどうでしょうか。","respondent":"冠木指導課長","answer":"土曜日に実施することによって全体枠を増やすわけですので、これは子どもたちにとってという意味合いで説明しますと、子どもたちから見たときに、日々の時間設定に余裕が出てくることは事実です。","voiceIndex":36,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"意見","question":"総枠が増えるので、裁量、やりくりというか、いろいろ工夫はできるかもしれないけれども、総時間が増えてしまうから、日々の月曜日から金曜日が少しでも軽くなる、こま数が減るということにはならないという、そこを。","respondent":"若月教育長","answer":"何か細かいのを私が答えるのは変なんですけれども、やっていることがわかっているものですから。簡単に言うと、今までは、１年生ではないですけれども、学年によっては３年生ぐらいから６時間目、７時間目もあったんです。学校によってあるんです。","voiceIndex":38,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"この裁量というか、子どもたちに合わせてその辺はやっていける幅が若干できたというとらえ方でいいでしょうか。すみません。ちょっと具体的に１年生と２年生のところを聞きたかったんですが、一、二年生というのは水曜日は４こまですよね。ちょっとその辺を一般的なスタンダードでいいので、１年生と２年生のところの１週間のこま数を教えていただけると。スタンダードで基本的なところを教えてください。","respondent":"冠木指導課長","answer":"ただ、個別の学校の状況については、ちょっと今、まだ私どものほうの手元にございませんので、ここではご案内できませんが、そんな状況です。","voiceIndex":40,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"週５日制の行われていたときの趣旨とかあり方というものに対して、その当時としては土曜日、日曜日、学校の授業ではできない体験を、家庭とか、また地域の方々との交流で行っていくというところが強調されていたんですが、その辺の考え方がどう変わってきたのかというあたりと、私は現場の声なんかを聞くとかなり子どもたちに負担、忙しくなる。","respondent":"冠木指導課長、若月教育長","answer":"ですので、こういった学校・地域・家庭が連携して、土曜日に開かれた学校づくりの意味も込めて教育活動を行っていくということについては、何らその趣旨にのっとったものですので。それに伴って、現在のようなゆとり時代の学校週５日制は、とてもじゃないけれども運用できない。したがって土曜日も授業の日として振り分けるという経緯があるわけです。","voiceIndex":42,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ゆとりの教育がされていて学力が落ちたという、そういった評価はそれだけではないなという、やはりゆとりが持てるためには、社会全体のところの変化ももっとないと、子どもたちにゆとりが求められなかったのではないかなと思っているんですけれども、その辺は見解が違うと思うんですが、そういった面では、ゆとりがあると学力が落ちるのでなくて。","respondent":"冠木指導課長、田村教育次長","answer":"今回、第１・第３土曜日に固定化するということで、今まで以上に、これは勤務時間の振り替えということで、先生方の勤務については対応していくんですけれども、より調整しやすくなると。先ほど来指導課長が説明しているように、例えば去年だと日野学園、一貫校でどれぐらい、超過勤務というのもこれは厳密に申し上げますと、教員というのは超過勤務というのは原則ありませんので。","voiceIndex":45,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"意見","question":"今、振り替えを夏休みで７月、８月にとっていくということなんですけれども、１学期とか前半のほうはいいんですが、後半のところの調節もきちんとできるのかどうか、ちょっとそこが心配なのと、あと、授業の準備時間というのは、前、どこかで統計みたいなのが出ているのを見たことがあって、ちょっと探したのですが出てこなかったんですが、それこそ若手とベテランと違うのはもちろんあるんですけれども。","respondent":"冠木指導課長","answer":"ですからそんなところで確実にとらせたいと考えています。それから２つ目の統計については、いろいろなところで統計をとっておられるので、ちょっと私どもの手元にはございませんけれども。","voiceIndex":48,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"教育を志して頑張っていらっしゃる、本当に品川区の先生たちが元気で働いていただけるための対策というのは、私はまだまだ不十分であると思っていますので、アンケートもとっているということなので、ぜひ現場の声をしっかりと受けとめて対策をとっていただきたい。なので、ぜひその辺の手立てもとっていただきたいと思いますけれども、いかがでしょうか。","respondent":"冠木指導課長","answer":"いろいろとご意見いただきましたので、いずれにいたしましても、この第１・第３の土曜日を設定をすることによって、子どもたちの学習状況の改善であったり、実際に学力が伸びていくというような中で、品川区として成果が上がっていくように。","voiceIndex":50,"id":"exchange-021"},{"speaker":"渡部委員","kind":"質問","question":"幾つか質問します。今、長い質疑の中でいろいろ伺えたんですけれども、小学校が平成２３年度から、中学校が平成２４年度からの完全実施ということなんですけれども、移行期間も含めてさまざまな学校がいろいろなことをやっていると思います。それと、今回、この文教委員会資料はたしか２日の日いただけたと思います。保護者さんはお手紙でわかることだと思います。大きくその２点をお聞きします。","respondent":"冠木指導課長、田村教育次長","answer":"土曜日が入りますと大体５１時間程度余裕が出てまいりますので、確保しやすくなりますので、そういった中でよりきめ細かい子どもたちへの対応ができていくのではないかと考えているところです。ちょっとスケジュールの関係は私のほうからご説明しますと、出だしが１１月１日に校長連絡会という定例でやっている会議がありまして、そこには幼稚園と小学校と中学校の校長先生全員出ていますので、そこで１１月１日スタートに。","voiceIndex":52,"id":"exchange-022"},{"speaker":"渡部委員","kind":"質問","question":"ただ、やはりここは学校なんだという中で、しっかりとみんなにわかっていただいて、第１・第３の土曜日は品川区は学校ありますよ、出欠とりますよという学校なんですから、それは各学校から、町会とかはいいかもしれないんですけれども、やはり教育委員会として品川区として、僕は品川区はこういうふうにやっていきますというのを発信するべきことなのかな。","respondent":"田村教育次長","answer":"まだスタートを切ったばかりですので、まだ町会なり保護者なりに浸透していませんので、行って周知期間でやったときに、必ずしも保護者・町会のみじゃなくて、品川の区民の方にも第１・第３の土曜日は来年度から授業が午前中あるんだよという形で、広報だとかホームページだとか。","voiceIndex":55,"id":"exchange-023"},{"speaker":"渡部委員","kind":"質問・要望","question":"ただ、やはりこの子どもにかかわる、しかも学校教育上のことですから、本当にそこはしっかりと、話を聞くのではなくて、しっかり伝えるということのほうが大事なのかなと思っています。一つ、そう言っても学校とかで、いろいろな学校かどうかわからないんですけれども、土曜日は学校授業がなかったから、例えば教室を借りている団体とかだって、どうしてくれるんだとかいう話があると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-024"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"現在、学校のところは４８校中３分の１、今後も簡易なものも含めてどんどんはかっていくということですか。大体１校当たり１５カ所ということですので、厳しい品川区の基準においても超えているところはなかったというところにおいては、除染をするところはなかったというとらえ方でよろしいんでしょうか。大体そうでしたね。保育園の場合は１カ所ですか。ちょっとそこを教えてください。","respondent":"吉岡保育課長","answer":"その結果として、先ほど申し上げたように０.２３マイクロシーベルト毎時を超えることはなかったという状況です。","voiceIndex":64,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つは、国のところもそうなんですが、東京都のところも地表の高さ１ｍというところが基準になっていますよね。そういった面では、関係者、保護者の皆さんとかの心配な箇所、それからここをはかっていただきたいというようなところも含めて、拡大してはかっていただきたいと思うんですが、もうこれは再度、再三質問になるんですが、この辺はいかがでしょうか。","respondent":"吉岡保育課長、齋藤庶務課長","answer":"保育園・幼稚園ですけれども、一般的な基準としては１ｍの高さという基準で測定をしているということでありますけれども、保育園庭については子どもが小さいということもありますし。学校です。小学校でも高さは１０cmと５０cm、学校では１０cmと１ｍ。これは文部科学省に基準がございましたので、これに従って区長部局よりも丁寧にはかっている。","voiceIndex":66,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ詳しくはかって、あとは環境課のところが公表するとなっていましたけれども、結構、今時点でまだ心配していて、どの程度ですかという関心・心配にこたえるのは、やはり数値をきちんとお伝えすることが安心につながることであると思うので、きちんと公開をしていただきたいなと思っているんです。これは空気中と土壌のところだけですか。食材のところは全然進展はないのでしょうか。","respondent":"和氣学務課長","answer":"この範囲が１日１校だそうです。３つの機関で１日１校です。しかも横浜は基本的に食材一括購入しているということもございまして、検査しやすいんですが、それでも１日１校ですから、６００日たたないと検査できない話になってしまうんです。","voiceIndex":69,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"出口でしっかりとチェックをする。それをやろうとしないところに問題があるんだと言われているので、私は今の体制でできないのでやりませんというのではなくて、やはり安全なものを食べさせるために、出口のところでは大丈夫だけれども、はかって大丈夫ですよ、安心して食べてくださいというところにぜひ立ってほしいんです。なので、ぜひこういった声も上げていただきたいんですが、いかがでしょうか。","respondent":"和氣学務課長","answer":"ですから各区でばらばらとお金を出してやっても、本当につけ焼き刃しかできないので、それこそ都が音頭をとって区市町村と一緒になって、それなりのお金を投資して、そういう検査体制をしっかり確立してほしいということも含めて要請しています。","voiceIndex":71,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"都に要請ということでははかったほうがいいという思いで固まっているんですか。出口だけじゃなくて、はかる方向でという。あくまでも出口段階だけなんですか。区としてはもうそれ以上やらないということなんでしょうか。そこをさっきから言っているんですけれども。","respondent":"和氣学務課長","answer":"繰り返しになりますが、基本的に出口で、やはり品川に来るときはちゃんと安全で来てほしいということが一番大事なことだと考えていますので、そこがまず前提で。","voiceIndex":73,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"しつこいみたいですけれども、結局質問に答えていないんです。同じ答えを繰り返しているだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-030"},{"speaker":"渡部委員","kind":"質問","question":"すみません。１点だけ、聞き漏らしだったらすみません。小学校、中学校１６校で終わったという話で、全部終わるのはいつですか。全部終わってないんですね。全部終わるのはいつぐらいになりますか。","respondent":"齋藤庶務課長","answer":"それで、最初は順調に終わるつもりだったんですけれども、どこでもはかりたいという話になりました。それで、今月中に１０台簡易測定器が来ますので、きちんとできれば、十分確保できれば年内、あるいは年度内にでも必ず測定し終えたいと考えております。","voiceIndex":76,"id":"exchange-031"},{"speaker":"渡部委員","kind":"質問","question":"年内に頑張ってください。それと、環境課も公表じゃなくて、例えば各学校の１５カ所をはかられて、０.２３マイクロシーベルトという基準になってということは、各学校のホームページのどこかに、はかりました。いついつはかりました、こうでしたというのを出すのが、僕は一番有効かと思うんですが、その辺はいかがでしょうか。","respondent":"齋藤庶務課長","answer":"私どもも委員と同じ考えでおりましたが、区長部局との調整で、全体を見ながら公表しようということになりましたので、足並みをそろえていくです。","voiceIndex":78,"id":"exchange-032"},{"speaker":"阿久津委員","kind":"確認","question":"先ほどほかの委員からの質問があったものの確認なんですけれども、今、いつまでに実施されるということで、今年もしくは今年度という、これはいつから実施されているのかということと、それとあと、これはだれが検査を行っていらっしゃるんでしょうか。もし万が一見つかった場合に、簡易な除染とあるんですけれども、これはどなたが行うんでしょうか。","respondent":"齋藤庶務課長","answer":"１つは０．２４マイクロシーベルトあるいは１時間１マイクロシーベルト程度であれば、いろいろお話を聞くと、区の職員あるいは学校では用務員が手袋、マスクをして土壌を削るなり、はくなり、高圧洗浄機で流せばいいようなんですけれども。","voiceIndex":80,"id":"exchange-033"},{"speaker":"阿久津委員","kind":"質問","question":"最後に１つだけ、先ほどほかの委員から、環境課のほうからとりまとめて公表するとあったんですけれども、そこでは当然学校の名前と、どこを１５カ所はかったというのは、正式に出るのでしょうか、それとも出ませんでしたという内容なんですか。","respondent":"齋藤庶務課長","answer":"少なくとも学校名、ここは安全だと、これは必ずお出しします。全部どこまでの数値を載せるかにつきましては、今、フォーマットで送ってはいるんですけれども、どこまで公表するかは部局との調整だということでご理解いただきたい。","voiceIndex":82,"id":"exchange-034"},{"speaker":"阿久津委員","kind":"質問・要望","question":"わかりました。これは１つだけ要望ですけれども、どこをはかったか、１５カ所というのはこれはもう定点、決まったところということなんでしょうか。","respondent":"齋藤庶務課長","answer":"文部科学省で一例を示しております。グラウンドレベル５カ所、水の集まるところ、植物菜園、そういうところを決めて丁重に実施しております。別途に学校からこの場所でもはかってくれです。","voiceIndex":84,"id":"exchange-035"},{"speaker":"阿久津委員","kind":"意見","question":"最後です。そうしましたら、環境課のほうでもし測定値を出すといった場合には、細かい数値を出していただいたほうが説得力があると思いますし、また憶測を呼ばないと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4742#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2011-01-01&TermEnd=2011-12-31"}],"sourceMeta":{"pages":0,"characters":33470,"voices":91}}]);
